const getSettings = function() {
  try {
    const s = Object.assign({}, defaultSettings, JSON.parse(fs.readFileSync(SETTINGS_FILE)));
    // Migrate old Norwegian color key names to English (one-time, transparent)
    if (s.colors) {
      const c = s.colors;
      const migrations = [
        ['kursBg','courseBg'],['kursBorder','courseBorder'],['kursText','courseText'],
        ['turBg','tripBg'],['turBorder','tripBorder'],['turText','tripText'],
        ['standBg','boothBg'],['standBorder','boothBorder'],['standText','boothText'],
        ['moteBg','meetingBg'],['moteBorder','meetingBorder'],['moteText','meetingText'],
      ];
      migrations.forEach(function(m) {
        if (c[m[0]] !== undefined && c[m[1]] === undefined) { c[m[1]] = c[m[0]]; delete c[m[0]]; }
      });
    }
    return s;
  }
  catch(e) { return Object.assign({}, defaultSettings); }
};
