// Resolve English source text into the language the user asked for.
// Unknown text and unknown languages both fall through to English.
function tr(text, req, vars) {
  const lang = serverLang(req);
  let out = text;
  if (lang !== "en") {
    const entry = TRANSLATIONS[text];
    if (entry && entry[lang]) out = entry[lang];
  }
  if (vars) Object.keys(vars).forEach(function(k) {
    out = out.replace(new RegExp("\\{" + k + "\\}", "g"), vars[k]);
  });
  return out;
}

// Same overlay for a known language code rather than a request object
// (background jobs, scheduled email, agent pushes).
function trLang(text, lang, vars) {
  let out = text;
  if (lang && lang !== "en") {
    const entry = TRANSLATIONS[text];
    if (entry && entry[lang]) out = entry[lang];
  }
  if (vars) Object.keys(vars).forEach(function(k) {
    out = out.replace(new RegExp("\\{" + k + "\\}", "g"), vars[k]);
  });
  return out;
}


