const WHISPER_URL = process.env.WHISPER_URL || "http://whisper:9000";

// ── GPU Arbitration — Whisper has priority over ComfyUI ──────────────
// Tracks which service currently owns the GPU.
// Whisper always wins — ComfyUI is stopped before transcription starts.
// ComfyUI start checks that Whisper is idle before proceeding.

const COMFYUI_CONTAINER = process.env.COMFYUI_CONTAINER || "comfyui";
const WHISPER_CONTAINER = process.env.WHISPER_CONTAINER || "whisper";
var   _gpuOwner         = null;  // null | "whisper" | "comfyui"
var   _whisperBusy      = false; // true while a transcription is in progress

async function gpuAcquireWhisper() {
  // Stop ComfyUI if it's running, then claim GPU for Whisper
  _gpuOwner = "whisper";
  _whisperBusy = true;
  try {
    const st = await dockerStatus(COMFYUI_CONTAINER);
    if (st.online) {
      console.log("[gpu] Whisper needs GPU — stopping ComfyUI");
      await dockerStop(COMFYUI_CONTAINER);
      // Brief pause so CUDA memory is fully released before Whisper loads
      await new Promise(function(r) { setTimeout(r, 2000); });
    }
  } catch(e) {
    console.warn("[gpu] Could not check/stop ComfyUI:", e.message);
  }
}

function gpuReleaseWhisper() {
  _whisperBusy = false;
  _gpuOwner = null;
  console.log("[gpu] Whisper released GPU");
}

async function gpuCanComfyStart() {
  // ComfyUI may only start if Whisper is not actively transcribing
  if (_whisperBusy) return { ok: false, reason: "Whisper is transcribing — please wait" };
  return { ok: true };
}

// ── Whisper transcription endpoints ──────────────────────────────
// POST /api/transcribe — transcribe audio via Whisper
// Accepts multipart/form-data with field "audio"
const transcribeUpload = multer({ storage: multer.memoryStorage(), limits: { fileSize: 100 * 1024 * 1024 } });

app.post("/api/transcribe", auth, rateLimit(40, 60000), transcribeUpload.single("audio"), async function(req, res) {
  if (!req.file) return res.status(400).json({ error: "No audio file" });
  const lang = req.body.language || "no";

  // Acquire GPU — stop ComfyUI if needed
  await gpuAcquireWhisper();

  try {
    const form = new globalThis.FormData();
    const blob = new Blob([req.file.buffer], { type: req.file.mimetype || "audio/webm" });
    form.append("audio_file", blob, req.file.originalname || "audio.webm");

    const whisperRes = await fetch(WHISPER_URL + "/asr?" + new URLSearchParams({
      language: lang,
      output:   "txt",
      encode:   "true",
      task:     "transcribe"
    }), {
      method: "POST",
      body:   form
    });

    if (!whisperRes.ok) {
      const errText = await whisperRes.text();
      console.error("[whisper] Error:", whisperRes.status, errText.slice(0, 200));
      gpuReleaseWhisper();
      return res.status(502).json({ error: st("whisper_error_prefix", req) + whisperRes.status });
    }

    const text = (await whisperRes.text()).trim();
    console.log("[whisper] Transcribed " + req.file.size + " bytes → " + text.length + " chars");
    gpuReleaseWhisper();
    res.json({ ok: true, text, language: lang });
  } catch(e) {
    console.error("[whisper] fetch error:", e.message);
    gpuReleaseWhisper();
    if (e.code === "ECONNREFUSED" || e.code === "ENOTFOUND") {
      return res.status(503).json({ error: st("whisper_unavailable", req) });
    }
    res.status(500).json({ error: e.message });
  }
});

