// POST /api/comfyui/generate — queue txt2img or img2img, poll until done, return image URL
app.post("/api/comfyui/generate", auth, rateLimit(10, 60000), async function(req, res) {
  const {
    prompt         = "a motorcycle event poster, dramatic lighting, crowd",
    negativePrompt = "text, watermark, blurry, low quality",
    width          = 768,
    height         = 512,
    steps          = 20,
    cfgScale       = 7,
    model          = null,
    seed           = -1,
    refImage       = null,   // filename from /upload/image
    refStrength    = 0.6     // denoise: 0.1 = ref dominates, 0.95 = prompt dominates
  } = req.body || {};

  const clientId   = require("crypto").randomUUID();
  const actualSeed = seed === -1 ? Math.floor(Math.random() * 2**32) : seed;

  // txt2img workflow (no reference image)
  const workflow = {
    "1": { "class_type": "CheckpointLoaderSimple", "inputs": { "ckpt_name": model || "__default__" } },
    "2": { "class_type": "CLIPTextEncode",  "inputs": { "text": prompt,         "clip": ["1", 1] } },
    "3": { "class_type": "CLIPTextEncode",  "inputs": { "text": negativePrompt, "clip": ["1", 1] } },
    "4": { "class_type": "EmptyLatentImage","inputs": { "width": width, "height": height, "batch_size": 1 } },
    "5": { "class_type": "KSampler", "inputs": {
      "model": ["1", 0], "positive": ["2", 0], "negative": ["3", 0], "latent_image": ["4", 0],
      "seed": actualSeed, "steps": steps, "cfg": cfgScale,
      "sampler_name": "euler", "scheduler": "normal", "denoise": 1.0
    }},
    "6": { "class_type": "VAEDecode",  "inputs": { "samples": ["5", 0], "vae": ["1", 2] } },
    "7": { "class_type": "SaveImage",  "inputs": { "images": ["6", 0], "filename_prefix": "events-admin" } }
  };

  // img2img workflow — replace EmptyLatentImage with LoadImage + VAEEncode
  if (refImage) {
    const denoise = Math.min(0.95, Math.max(0.1, parseFloat(refStrength) || 0.6));
    // Node 4 becomes LoadImage, node 8 becomes VAEEncode (produces latent from ref image)
    workflow["4"] = { "class_type": "LoadImage", "inputs": { "image": refImage } };
    workflow["8"] = { "class_type": "VAEEncode",  "inputs": { "pixels": ["4", 0], "vae": ["1", 2] } };
    // Also resize the reference image to match requested dimensions
    workflow["9"] = { "class_type": "ImageScale", "inputs": {
      "image": ["4", 0], "width": width, "height": height,
      "upscale_method": "lanczos", "crop": "center"
    }};
    workflow["8"].inputs.pixels = ["9", 0]; // use resized image
    // KSampler uses VAEEncoded latent and partial denoise
    workflow["5"].inputs.latent_image = ["8", 0];
    workflow["5"].inputs.denoise = denoise;
  }

  // Resolve default model if none specified
  if (!model) {
    try {
      const mi = await fetch(COMFYUI_URL + "/object_info/CheckpointLoaderSimple", { signal: AbortSignal.timeout(4000) });
      if (mi.ok) {
        const md = await mi.json();
        const models = (md.CheckpointLoaderSimple && md.CheckpointLoaderSimple.input &&
                        md.CheckpointLoaderSimple.input.required &&
                        md.CheckpointLoaderSimple.input.required.ckpt_name &&
                        md.CheckpointLoaderSimple.input.required.ckpt_name[0]) || [];
        if (models.length) workflow["1"].inputs.ckpt_name = models[0];
        else delete workflow["1"].inputs.ckpt_name;
      }
    } catch(_) { delete workflow["1"].inputs.ckpt_name; }
    if (workflow["1"].inputs.ckpt_name === "__default__") delete workflow["1"].inputs.ckpt_name;
  }

  try {
    // Queue the prompt
    const queueRes = await fetch(COMFYUI_URL + "/prompt", {
      method: "POST", headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ prompt: workflow, client_id: clientId }),
      signal: AbortSignal.timeout(10000)
    });
    if (!queueRes.ok) {
      const err = await queueRes.text();
      return res.status(502).json({ error: "Queue failed: " + err.slice(0, 200) });
    }
    const promptId = (await queueRes.json()).prompt_id;
    if (!promptId) return res.status(502).json({ error: "No prompt_id returned" });

    // Poll history until done (max 120 s)
    const deadline = Date.now() + 120_000;
    let outputFilename = null;
    while (Date.now() < deadline) {
      await new Promise(function(r) { setTimeout(r, 2000); });
      const histRes = await fetch(COMFYUI_URL + "/history/" + promptId, { signal: AbortSignal.timeout(5000) });
      if (!histRes.ok) continue;
      const hist  = await histRes.json();
      const entry = hist[promptId];
      if (!entry) continue;
      if (entry.status && entry.status.status_str === "error") {
        const msgs = (entry.status.messages || []).map(function(m) {
          const val = m[1];
          if (!val) return '';
          if (typeof val === 'string') return val;
          // val might be an object like { node_id, node_type, exception_message, traceback }
          if (val.exception_message) return val.exception_message;
          if (val.exception_type)    return val.exception_type;
          return JSON.stringify(val);
        }).filter(Boolean).join("; ");
        console.error("[comfyui] workflow error:", msgs);
        return res.status(500).json({ error: msgs || "ComfyUI workflow failed" });
      }
      const outputs = entry.outputs || {};
      for (const nodeId of Object.keys(outputs)) {
        const images = outputs[nodeId].images || [];
        if (images.length) { outputFilename = images[0].filename; break; }
      }
      if (outputFilename) break;
    }
    if (!outputFilename) return res.status(504).json({ error: "Generation timed out after 120s" });

    // Fetch image from ComfyUI and save to uploads
    const imgRes = await fetch(COMFYUI_URL + "/view?" + new URLSearchParams({ filename: outputFilename, type: "output" }),
      { signal: AbortSignal.timeout(15000) });
    if (!imgRes.ok) return res.status(502).json({ error: "Could not retrieve image from ComfyUI" });

    const imgBuf   = Buffer.from(await imgRes.arrayBuffer());
    const saveFile = "comfy-" + Date.now() + "-" + require("crypto").randomBytes(4).toString("hex") + ".png";
    const savePath = path.join(UPLOADS, saveFile);
    fs.writeFileSync(savePath, imgBuf);

    console.log("[comfyui] Generated:", outputFilename, "→", saveFile, "(" + imgBuf.length + " bytes)");
    res.json({ ok: true, imageUrl: "/uploads/" + saveFile, filename: saveFile, seed: actualSeed, promptId });

  } catch(e) {
    console.error("[comfyui] generate error:", e.message);
    if (e.code === "ECONNREFUSED" || e.code === "ENOTFOUND")
      return res.status(503).json({ error: "ComfyUI not available — check that the container is running" });
    res.status(500).json({ error: e.message });
  }
});
// ── END ComfyUI ───────────────────────────────────────────────────────

const _activeStreams = new Map();


function watchdogRequest(method, path, body) {
  return new Promise(function(resolve, reject) {
    if (!WATCHDOG_URL || !WATCHDOG_TOKEN) {
      return reject(new Error("WATCHDOG_URL eller WATCHDOG_TOKEN ikke konfigurert"));
    }
    const url    = require("url").parse(WATCHDOG_URL + path);
    const mod    = WATCHDOG_URL.startsWith("https") ? require("https") : require("http");
    const data   = body ? JSON.stringify(body) : null;
    const opts   = {
      hostname: url.hostname,
      port:     url.port || (WATCHDOG_URL.startsWith("https") ? 443 : 80),
      path:     url.path,
      method:   method,
      headers:  {
        "Authorization": "Bearer " + WATCHDOG_TOKEN,
        "Content-Type":  "application/json",
      },
      timeout: 8000,
    };
    const req = mod.request(opts, function(res) {
      const chunks = [];
      res.on("data", function(c) { chunks.push(c); });
      res.on("end", function() {
        try { resolve({ status: res.statusCode, data: JSON.parse(Buffer.concat(chunks).toString()) }); }
        catch(e) { resolve({ status: res.statusCode, data: {} }); }
      });
    });
    req.on("error", reject);
    req.on("timeout", function() { req.destroy(); reject(new Error("Watchdog timeout")); });
    if (data) req.write(data);
    req.end();
  });
}

