// Fetches GPS position from a live tracking share URL (Sizzapp, Garmin Share, etc.)


// ── GPS Tracker API ──────────────────────────────────────────────
// Endpoints for LILYGO T-SIM7670G tracker device
// Authentication: mTLS client certificate (Traefik forwards CN header)
// Traefik must be configured to forward: X-Forwarded-Tls-Client-Cert-Info

const TRACKER_FILE  = path.join(DATA, "tracker_log.json");
const TRACKER_SECRET = process.env.TRACKER_SECRET || "";

// mTLS auth middleware — verifies client cert CN forwarded by Traefik
// Traefik adds X-Forwarded-Tls-Client-Cert-Info header when mTLS is used
// Falls back to Bearer token for testing without Traefik
function trackerAuth(req, res, next) {
  // Check for Traefik mTLS cert info header
  const certInfo = req.headers["x-forwarded-tls-client-cert-info"] || "";
  if (certInfo) {
    // Extract CN from cert info (format: CN=tracker-01,O=NAF,C=NO)
    const cnMatch = certInfo.match(/CN=([^,;%]+)/);
    if (cnMatch) {
      req.trackerDevice = decodeURIComponent(cnMatch[1]);
      return next();
    }
  }
  // Fallback: Bearer token (for testing / non-mTLS setups)
  const auth = req.headers["authorization"] || "";
  if (TRACKER_SECRET && auth === "Bearer " + TRACKER_SECRET) {
    req.trackerDevice = req.body && req.body.deviceId ? req.body.deviceId : "unknown";
    return next();
  }
  res.status(401).json({ error: "Unauthorized — valid client cert or Bearer token required" });
}

// POST /api/tracker/location — device pushes GPS fix
app.post("/api/tracker/location", rateLimit(120, 60000), trackerAuth, function(req, res) {
  const { lat, lng, alt, speed, battery, satellites, hdop, clients } = req.body;
  const deviceId = req.body.deviceId || req.trackerDevice || "unknown";

  if (lat === undefined || lng === undefined) {
    return res.status(400).json({ error: "lat and lng required" });
  }

  const fix = {
    deviceId, lat, lng,
    alt:        alt        !== undefined ? alt        : null,
    speed:      speed      !== undefined ? speed      : null,
    battery:    battery    !== undefined ? battery    : null,
    satellites: satellites !== undefined ? satellites : null,
    hdop:       hdop       !== undefined ? hdop       : null,
    wifiClients: clients   !== undefined ? clients    : null,
    ts: new Date().toISOString()
  };

  // Append to log
  const log = readJSON(TRACKER_FILE) || [];
  log.push(fix);
  // Keep last 10 000 fixes (~3 days at 30s interval)
  if (log.length > 10000) log.splice(0, log.length - 10000);
  writeJSON(TRACKER_FILE, log);

  // Broadcast to admin clients via WebSocket
  broadcastToAll({ type: "tracker_fix", fix });

  res.json({ ok: true });
});

// GET /api/tracker/latest — last fix per device
app.get("/api/tracker/latest", auth, function(req, res) {
  const log = readJSON(TRACKER_FILE) || [];
  const latest = {};
  log.forEach(function(fix) {
    latest[fix.deviceId] = fix;
  });
  res.json({ devices: Object.values(latest) });
});

// GET /api/tracker/history — fix trail for one device
app.get("/api/tracker/history", auth, function(req, res) {
  const { deviceId, limit, since } = req.query;
  let log = readJSON(TRACKER_FILE) || [];
  if (deviceId) log = log.filter(function(f){ return f.deviceId === deviceId; });
  if (since)    log = log.filter(function(f){ return f.ts >= since; });
  const lim = parseInt(limit || "200");
  res.json({ fixes: log.slice(-lim) });
});

// DELETE /api/tracker/log — clear the log (admin only)
app.delete("/api/tracker/log", auth, adminOnly, function(req, res) {
  writeJSON(TRACKER_FILE, []);
  res.json({ ok: true });
});

// ── Stream management API ────────────────────────────────────────────
// nginx-rtmp on_publish callback — GoPro started streaming
app.get("/api/stream/notify", function(req, res) {
  const key = req.query.name || req.query.stream || "";
  if (!key) return res.status(400).send("no name");
  _activeStreams.set(key, {
    key, label: key,
    hlsUrl:    RTMP_HLS + "/hls/" + key + ".m3u8",
    startedAt: Date.now(), lastSeen: Date.now(), active: true
  });
  console.log("[stream] Started: " + key + " (" + _activeStreams.size + " active)");
  res.send("ok");
});

// nginx-rtmp on_done callback — GoPro stopped streaming
app.get("/api/stream/done", function(req, res) {
  const key = req.query.name || req.query.stream || "";
  if (_activeStreams.has(key)) {
    _activeStreams.get(key).active  = false;
    _activeStreams.get(key).endedAt = Date.now();
    console.log("[stream] Ended: " + key);
  }
  res.send("ok");
});

// List active streams — used by admin UI
app.get("/api/streams", auth, function(req, res) {
  const streams = Array.from(_activeStreams.values())
    .filter(function(s){ return s.active; })
    .map(function(s){ return { key:s.key, label:s.label, hlsUrl:s.hlsUrl, startedAt:s.startedAt }; });
  res.json({ streams, hlsBase: RTMP_HLS });
});

// Rename a stream key to a friendly label
app.put("/api/streams/:key/label", auth, managerOrAdmin, function(req, res) {
  const s = _activeStreams.get(req.params.key);
  if (!s) return res.status(404).json({ error: "Stream not found" });
  s.label = (req.body.label || req.params.key).trim();
  res.json({ ok: true, label: s.label });
});

// Public stream list — no auth, for TV channel

// ── Stream recordings → event media ──────────────────────────────
// nginx-rtmp records each live session to RECORDINGS_DIR (record on).
// These endpoints let a manager attach a recording to an event's
// guestbook gallery as a backup, and later REPLACE the low-bitrate
// stream copy with the real camera footage.

const _VIDEO_EXTS = [".flv", ".mp4", ".mov", ".mkv", ".webm", ".m4v"];

function _ffmpegAvailable() {
  try { require("child_process").execFileSync("which", ["ffmpeg"], { stdio: "ignore" }); return true; }
  catch (e) { return false; }
}

// ── Faststart migration for existing guestbook videos ──────────────
// Older uploads (before the upload-time faststart fix existed) may still
// have the moov atom at the end of the file, which means browsers can't
// start playback until the whole file has downloaded. This job scans
// gb-photos once and remuxes any video that needs it, in place.
var _fixVideosJob = { running: false, total: 0, processed: 0, fixed: 0, alreadyOk: 0, failed: 0, log: [], startedAt: null, finishedAt: null, dryRun: false };

function _isVideoFaststart(filePath) {
  var ext = path.extname(filePath).toLowerCase();
  if (ext === ".webm") return true; // different container format, not affected by this issue
  var fd;
  try {
    fd = fs.openSync(filePath, "r");
    var size = fs.fstatSync(fd).size;
    var pos = 0;
    var headerBuf = Buffer.alloc(8);
    while (pos < size - 8) {
      fs.readSync(fd, headerBuf, 0, 8, pos);
      var atomSize = headerBuf.readUInt32BE(0);
      var atomType = headerBuf.toString("ascii", 4, 8);
      if (atomType === "moov") return true;
      if (atomType === "mdat") return false;
      if (atomSize === 1) {
        var extBuf = Buffer.alloc(8);
        fs.readSync(fd, extBuf, 0, 8, pos + 8);
        var big = extBuf.readBigUInt64BE(0);
        if (big > BigInt(Number.MAX_SAFE_INTEGER)) return null;
        atomSize = Number(big);
      }
      if (atomSize === 0 || atomSize < 8) break;
      pos += atomSize;
    }
    return null;
  } catch (e) {
    return null;
  } finally {
    if (fd !== undefined) try { fs.closeSync(fd); } catch (e) {}
  }
}

function _videoHasRotationTag(filePath) {
  try {
    var r = require("child_process").spawnSync("ffprobe", [
      "-v", "error", "-select_streams", "v:0",
      "-show_entries", "stream_side_data=rotation",
      "-of", "csv=p=0", filePath
    ]);
    return r.status === 0 && /-?\d+/.test((r.stdout || "").toString().trim());
  } catch (e) {
    return false;
  }
}

// Always fully re-encodes — matches the TV-kanal video uploader, which is
// the one upload path proven reliable in production. A conditional fast
// "-c copy" path was tried first but couldn't be confirmed reliable for
// every real-world file, so simplicity and consistency win here over speed.
function _remuxVideoFaststart(filePath) {
  return new Promise(function (resolve) {
    var tmpPath = filePath + ".faststart.tmp.mp4";
    var { spawn } = require("child_process");
    var args = [
      "-i", filePath,
      "-map_metadata", "-1",
      "-c:v", "libx264",
      "-preset", "fast",
      "-crf", "23",
      "-vf", "scale=trunc(iw/2)*2:trunc(ih/2)*2",
      "-c:a", "aac",
      "-b:a", "128k",
      "-movflags", "+faststart",
      "-y", tmpPath
    ];
    var ff = spawn("ffmpeg", args);
    ff.stderr.on("data", function () {});
    ff.on("close", function (code) {
      if (code !== 0) {
        try { fs.unlinkSync(tmpPath); } catch (e) {}
        return resolve({ ok: false, error: "ffmpeg exit " + code });
      }
      if (!fs.existsSync(tmpPath) || fs.statSync(tmpPath).size === 0) {
        try { fs.unlinkSync(tmpPath); } catch (e) {}
        return resolve({ ok: false, error: "Tom eller manglende output-fil" });
      }
      try {
        fs.renameSync(tmpPath, filePath);
        resolve({ ok: true });
      } catch (e) {
        resolve({ ok: false, error: e.message });
      }
    });
    ff.on("error", function (e) { resolve({ ok: false, error: e.message }); });
  });
}

async function _runFixVideosJob(dryRun) {
  if (_fixVideosJob.running) return;
  var dir = path.join(DATA, "gb-photos");
  var videoExts = [".mp4", ".m4v", ".mov", ".webm"];
  _fixVideosJob = { running: true, total: 0, processed: 0, fixed: 0, alreadyOk: 0, failed: 0, log: [], startedAt: new Date().toISOString(), finishedAt: null, dryRun: !!dryRun };

  if (!fs.existsSync(dir)) {
    _fixVideosJob.log.push("The gb-photos folder does not exist yet - nothing to do.");
    _fixVideosJob.running = false;
    _fixVideosJob.finishedAt = new Date().toISOString();
    return;
  }
  if (!_ffmpegAvailable()) {
    _fixVideosJob.log.push("ffmpeg was not found on the server - cannot run.");
    _fixVideosJob.running = false;
    _fixVideosJob.finishedAt = new Date().toISOString();
    return;
  }

  var files = fs.readdirSync(dir).filter(function (f) {
    return videoExts.indexOf(path.extname(f).toLowerCase()) !== -1;
  });
  _fixVideosJob.total = files.length;
  _fixVideosJob.log.push("Fant " + files.length + " video file(s). Re-encoding all of them to guarantee a fixed start and correct rotation (the same method the TV channel uses).");

  for (var i = 0; i < files.length; i++) {
    var filename = files[i];
    var filePath = path.join(dir, filename);
    var sizeMB = (fs.statSync(filePath).size / 1024 / 1024).toFixed(1);
    var fast = _isVideoFaststart(filePath);
    var hasRotation = _videoHasRotationTag(filePath);
    var notes = [];
    if (fast !== true) notes.push(fast === null ? "struktur uklar" : "ikke faststart");
    if (hasRotation) notes.push("rotasjonstag");
    var noteStr = notes.length ? " (" + notes.join(", ") + ")" : " (ingen kjente problemer, re-koder likevel for sikkerhets skyld)";

    if (dryRun) {
      _fixVideosJob.log.push("○ " + filename + " (" + sizeMB + " MB)" + noteStr + " — dry-run, ingen endring gjort");
    } else {
      var r = await _remuxVideoFaststart(filePath);
      if (r.ok) {
        _fixVideosJob.fixed++;
        _fixVideosJob.log.push("✓ " + filename + " (" + sizeMB + " MB)" + noteStr + " — re-kodet");
      } else {
        _fixVideosJob.failed++;
        _fixVideosJob.log.push("✗ " + filename + " (" + sizeMB + " MB) — FEILET: " + r.error);
      }
    }
    _fixVideosJob.processed = i + 1;
  }

  _fixVideosJob.running = false;
  _fixVideosJob.finishedAt = new Date().toISOString();
  _fixVideosJob.log.push("Ferdig. " + _fixVideosJob.fixed + " re-kodet, " + _fixVideosJob.failed + " feilet.");
}

app.post("/api/admin-tools/fix-videos/start", auth, managerOrAdmin, function (req, res) {
  if (_fixVideosJob.running) return res.status(409).json({ error: st("job_already_running", req) });
  var dryRun = !!(req.body && req.body.dryRun);
  _runFixVideosJob(dryRun); // fire-and-forget — client polls /status
  res.json({ ok: true, started: true });
});

app.get("/api/admin-tools/fix-videos/status", auth, managerOrAdmin, function (req, res) {
  res.json(_fixVideosJob);
});

// Transcode (or copy) a source video into gb-photos as MP4.
// Falls back to a plain copy if ffmpeg is missing or the source is already mp4.
function _ingestRecordingToGbPhotos(srcPath, destName) {
  return new Promise(function(resolve, reject) {
    const gbDir = path.join(DATA, "gb-photos");
    if (!fs.existsSync(gbDir)) fs.mkdirSync(gbDir, { recursive: true });
    const ext = path.extname(srcPath).toLowerCase();
    const destPath = path.join(gbDir, destName);

    // No transcode needed / possible → straight copy
    if (ext === ".mp4" || !_ffmpegAvailable()) {
      try { fs.copyFileSync(srcPath, destPath); return resolve("/gb-photos/" + destName); }
      catch (e) { return reject(e); }
    }

    // Transcode to web-friendly MP4 (same recipe as TV video ingest)
    const { spawn } = require("child_process");
    const ff = spawn("ffmpeg", [
      "-i", srcPath,
      "-c:v", "libx264", "-preset", "fast", "-crf", "23",
      "-vf", "scale=trunc(iw/2)*2:trunc(ih/2)*2",
      "-c:a", "aac", "-b:a", "128k",
      "-movflags", "+faststart",
      "-y", destPath
    ]);
    ff.stderr.on("data", function() {});
    ff.on("close", function(code) {
      if (code === 0 && fs.existsSync(destPath)) return resolve("/gb-photos/" + destName);
      // Transcode failed → fall back to copying the raw file
      try { fs.copyFileSync(srcPath, destPath); resolve("/gb-photos/" + destName); }
      catch (e) { reject(new Error("ffmpeg kode " + code + " og kopi feilet: " + e.message)); }
    });
    ff.on("error", function() {
      try { fs.copyFileSync(srcPath, destPath); resolve("/gb-photos/" + destName); }
      catch (e) { reject(e); }
    });
  });
}

// GET /api/recordings — list recording files on disk (survives restart)
app.get("/api/recordings", auth, managerOrAdmin, function(req, res) {
  try {
    if (!fs.existsSync(RECORDINGS_DIR)) return res.json({ recordings: [], dir: RECORDINGS_DIR, available: false });
    const files = fs.readdirSync(RECORDINGS_DIR)
      .filter(function(f) { return _VIDEO_EXTS.indexOf(path.extname(f).toLowerCase()) !== -1; })
      .map(function(f) {
        var st = {};
        try { st = fs.statSync(path.join(RECORDINGS_DIR, f)); } catch (e) {}
        // nginx record_unique names look like cam1-20260607-101500.flv
        var cam = (f.split(/[-_.]/)[0]) || "";
        return { file: f, cam: cam, sizeBytes: st.size || 0, mtime: st.mtimeMs || 0 };
      })
      .sort(function(a, b) { return b.mtime - a.mtime; });
    res.json({ recordings: files, dir: RECORDINGS_DIR, available: true });
  } catch (e) {
    res.status(500).json({ error: st("recording_read_failed_prefix", req) + e.message });
  }
});

// POST /api/events/:id/save-recording  { file, gbId? }
// Ingests a recording into the event as a backup video. If gbId is given and
// is an existing stream-recording group, the camera is ADDED as another angle
// to that group; otherwise a new grouped entry is created.
app.post("/api/events/:id/save-recording", auth, managerOrAdmin, async function(req, res) {
  const fileName = path.basename(req.body.file || ""); // prevent path traversal
  if (!fileName) return res.status(400).json({ error: st("missing_filename", req) });
  const srcPath = path.join(RECORDINGS_DIR, fileName);
  if (!fs.existsSync(srcPath)) return res.status(404).json({ error: st("recording_not_found", req) });

  const events = readJSON(EVENTS_FILE);
  const ev = events.find(function(e) { return e.id === req.params.id; });
  if (!ev) return res.status(404).json({ error: st("event_not_found", req) });

  const destName = "rec_" + ev.id + "_" + Date.now() + ".mp4";
  let url;
  try { url = await _ingestRecordingToGbPhotos(srcPath, destName); }
  catch (e) { return res.status(500).json({ error: st("save_failed_prefix", req) + e.message }); }

  const cam = _cameraNameFor(fileName);
  const angle = {
    url: url,
    camKey: cam.key,
    camName: cam.name,
    origFile: fileName,
    isStreamBackup: true,
    previewSeconds: 20,            // intended TV per-angle preview length
    takenAt: new Date().toISOString(),
  };

  ev.guestbook = ev.guestbook || [];

  // Add to an existing group if a valid gbId for a stream-recording group is given
  let entry = req.body.gbId ? (ev.guestbook.find(function(g){ return g.id === req.body.gbId && g.isStreamRecording; })) : null;

  if (entry) {
    entry.angles = entry.angles || [];
    // Avoid duplicate of the same source file
    if (!entry.angles.some(function(a){ return a.origFile === fileName; })) {
      entry.angles.push(angle);
      entry.photos = entry.angles.map(function(a){ return a.url; }); // keep gallery in sync
    }
  } else {
    entry = {
      id: uuid(),
      isStreamRecording: true,
      name: "📹 Turopptak (backup)",
      message: "Stream recording from the trip. More camera angles can be added, and each can be replaced with the camera's original file.",
      approved: true,
      createdAt: new Date().toISOString(),
      angles: [angle],
      photos: [url],
    };
    ev.guestbook.push(entry);
  }

  writeJSON(EVENTS_FILE, events);
  res.json({ ok: true, url: url, gbId: entry.id, angleCount: entry.angles.length, camName: cam.name, transcoded: _ffmpegAvailable() });
});

// POST /api/events/:id/guestbook/:gid/replace-angle  (multipart: video, field: camKey)
// Replaces ONE camera angle's stream backup with the real camera file.
app.post("/api/events/:id/guestbook/:gid/replace-angle", auth, managerOrAdmin,
  recordingUpload.single("video"), async function(req, res) {
  if (!req.file) return res.status(400).json({ error: st("no_file", req) });
  const camKey = String(req.body.camKey || "").replace(/[^a-z0-9_-]/gi, "");
  const events = readJSON(EVENTS_FILE);
  const ev = events.find(function(e) { return e.id === req.params.id; });
  if (!ev) { try { fs.unlinkSync(req.file.path); } catch(e){} return res.status(404).json({ error: st("event_not_found", req) }); }
  const entry = (ev.guestbook || []).find(function(g) { return g.id === req.params.gid; });
  if (!entry || !entry.angles) { try { fs.unlinkSync(req.file.path); } catch(e){} return res.status(404).json({ error: st("recording_group_not_found", req) }); }
  const angle = entry.angles.find(function(a){ return a.camKey === camKey; });
  if (!angle) { try { fs.unlinkSync(req.file.path); } catch(e){} return res.status(404).json({ error: st("camera_angle_not_found", req) }); }

  const destName = "rec_" + ev.id + "_" + Date.now() + ".mp4";
  let url;
  try { url = await _ingestRecordingToGbPhotos(req.file.path, destName); }
  catch (e) { try { fs.unlinkSync(req.file.path); } catch(_){} return res.status(500).json({ error: st("replace_failed_prefix", req) + e.message }); }
  try { fs.unlinkSync(req.file.path); } catch(e) {}

  // Delete the old backup file for this angle, then swap
  try {
    var old = path.join(DATA, "gb-photos", path.basename(angle.url));
    if (fs.existsSync(old) && path.basename(angle.url) !== path.basename(url)) fs.unlinkSync(old);
  } catch (e) {}
  angle.url = url;
  angle.isStreamBackup = false;
  angle.takenAt = new Date().toISOString();
  entry.photos = entry.angles.map(function(a){ return a.url; });
  // If every angle is now an original, reflect that in the label
  if (entry.angles.every(function(a){ return !a.isStreamBackup; })) {
    entry.name = "📹 Turopptak (original)";
    entry.message = "Originalfiler fra kamera.";
  }
  writeJSON(EVENTS_FILE, events);
  res.json({ ok: true, url: url, allOriginal: entry.angles.every(function(a){ return !a.isStreamBackup; }) });
});


// ── Hardware file generator API ──────────────────────────────────
// These endpoints generate config files server-side and serve them
// as downloads — avoids putting large template literals in the browser JS.

function _hwSettings(req) {
  const s = getSettings();
  return {
    adminDomain:  s.adminDomain  || req.hostname || "admin.example.com",
    siteName:     s.siteName     || "Event-Admin",
    deviceId:     (req.query.deviceId     || "tracker-01").replace(/[^a-z0-9_-]/gi, ""),
    apn:          (req.query.apn          || "telenor.smart").replace(/[^a-z0-9._-]/gi, ""),
    fixInterval:  Math.max(5,  parseInt(req.query.fixInterval  || "30"))  * 1000,
    idleInterval: Math.max(30, parseInt(req.query.idleInterval || "300")) * 1000,
    wifiSsid:     (req.query.wifiSsid || "TurTracker").slice(0, 32),
    wifiPass:     (req.query.wifiPass  || "Tur2026!").slice(0, 63),
    certOrg:      (req.query.certOrg     || s.siteName || "MyOrg").slice(0, 64),
    certCountry:  (req.query.certCountry || "NO").slice(0, 2).toUpperCase(),
    camCount:     Math.min(10, Math.max(1, parseInt(req.query.camCount  || "3"))),
    camRotate:    Math.max(5,  parseInt(req.query.camRotate || "30")),
  };
}

// GET /api/hardware/firmware — Arduino .ino file
app.get("/api/hardware/firmware", auth, function(req, res) {
  const c = _hwSettings(req);
  const code = [
    `// GPS Tracker Firmware — auto-generated by ${c.siteName}`,
    `// Generated: ${new Date().toLocaleString("nb-NO")}`,
    `// Device: ${c.deviceId}  Server: ${c.adminDomain}`,
    `//`,
    `// SETUP:`,
    `// 1. Install libraries: TinyGSM, ArduinoJson (Arduino Library Manager)`,
    `// 2. Run: sudo bash generate-certs.sh ${c.deviceId}`,
    `// 3. Copy ${c.deviceId}_certs.h into this sketch folder`,
    `// 4. Board: ESP32S3 Dev Module`,
    `// 5. Flash via USB-C, open Serial Monitor @ 115200`,
    ``,
    `#include "${c.deviceId}_certs.h"`,
    ``,
    `#define TINY_GSM_MODEM_SIM7670`,
    `#include <TinyGsmClient.h>`,
    `#include <ArduinoJson.h>`,
    `#include <WiFi.h>`,
    `#include <esp_netif.h>`,
    `#include <lwip/ip4_addr.h>`,
    ``,
    `// CONFIG`,
    `#define SERVER_HOST      "${c.adminDomain}"`,
    `#define SERVER_PORT      443`,
    `#define SERVER_PATH      "/api/tracker/location"`,
    `#define DEVICE_ID        "${c.deviceId}"`,
    `#define APN              "${c.apn}"`,
    `#define WIFI_AP_SSID     "${c.wifiSsid}"`,
    `#define WIFI_AP_PASSWORD "${c.wifiPass}"`,
    `#define WIFI_AP_CHANNEL  6`,
    `#define WIFI_AP_MAX_CONN 8`,
    `#define FIX_INTERVAL_MS  ${c.fixInterval}`,
    `#define IDLE_INTERVAL_MS ${c.idleInterval}`,
    `#define IDLE_THRESHOLD_M 5.0`,
    ``,
    `#define MODEM_TX 17`,
    `#define MODEM_RX 18`,
    `#define MODEM_PWRKEY 41`,
    `#define MODEM_POWER_ON 12`,
    `#define LED_PIN 37`,
    `#define BAT_ADC_PIN 4`,
    ``,
    `HardwareSerial modemSerial(1);`,
    `TinyGsm modem(modemSerial);`,
    `TinyGsmClientSecure client(modem);`,
    `struct GnssFix { float lat,lng,alt,speed,hdop; int satellites; bool valid; };`,
    `GnssFix lastFix={0}; uint32_t lastSendTime=0; int wifiClients=0;`,
    ``,
    `void setup() {`,
    `  Serial.begin(115200); delay(500);`,
    `  Serial.println("\\n[boot] ${c.siteName} Tracker — ${c.deviceId}");`,
    `  pinMode(LED_PIN,OUTPUT); pinMode(MODEM_POWER_ON,OUTPUT); pinMode(MODEM_PWRKEY,OUTPUT);`,
    `  digitalWrite(MODEM_POWER_ON,HIGH); delay(100);`,
    `  digitalWrite(MODEM_PWRKEY,HIGH); delay(100); digitalWrite(MODEM_PWRKEY,LOW); delay(1000); digitalWrite(MODEM_PWRKEY,HIGH);`,
    `  modemSerial.begin(115200,SERIAL_8N1,MODEM_RX,MODEM_TX); delay(3000);`,
    `  if(!modem.restart()) modem.init();`,
    `  Serial.println("[modem] "+modem.getModemInfo());`,
    `  client.setCACert(CA_CERT); client.setCertificate(DEVICE_CERT); client.setPrivateKey(DEVICE_KEY);`,
    `  Serial.println("[tls] Certificates loaded");`,
    `  modem.enableGPS();`,
    `  if(!modem.waitForNetwork(60000L)) Serial.println("[gprs] No network!");`,
    `  else if(modem.gprsConnect(APN,"","")) Serial.println("[gprs] Connected: "+modem.localIP().toString());`,
    `  WiFi.mode(WIFI_AP);`,
    `  WiFi.softAPConfig(IPAddress(192,168,4,1),IPAddress(192,168,4,1),IPAddress(255,255,255,0));`,
    `  if(WiFi.softAP(WIFI_AP_SSID,WIFI_AP_PASSWORD,WIFI_AP_CHANNEL,0,WIFI_AP_MAX_CONN))`,
    `    Serial.println("[wifi] AP: " + String(WIFI_AP_SSID) + "  IP: " + WiFi.softAPIP().toString());`,
    `  #ifdef CONFIG_LWIP_IP_FORWARD`,
    `    ip_napt_enable(ipaddr_addr("192.168.4.1"),1);`,
    `    Serial.println("[nat] LTE bridge active");`,
    `  #endif`,
    `  for(int i=0;i<3;i++){digitalWrite(LED_PIN,HIGH);delay(100);digitalWrite(LED_PIN,LOW);delay(100);}`,
    `  Serial.println("[boot] Ready");`,
    `}`,
    ``,
    `void loop() {`,
    `  if(!modem.isGprsConnected()) { modem.waitForNetwork(30000L); modem.gprsConnect(APN,"",""); }`,
    `  uint32_t now=millis();`,
    `  uint32_t interval=FIX_INTERVAL_MS;`,
    `  if(lastFix.valid) {`,
    `    GnssFix cur=getGnssFix();`,
    `    if(cur.valid) { float d=haversineM(lastFix.lat,lastFix.lng,cur.lat,cur.lng); interval=(d>IDLE_THRESHOLD_M)?FIX_INTERVAL_MS:IDLE_INTERVAL_MS; }`,
    `  }`,
    `  if(now-lastSendTime>=interval) {`,
    `    GnssFix fix=getGnssFix();`,
    `    if(fix.valid) { int bat=readBattery(); if(sendFix(fix,bat)){lastFix=fix;lastSendTime=now;digitalWrite(LED_PIN,HIGH);delay(50);digitalWrite(LED_PIN,LOW);Serial.printf("[ok] %.6f,%.6f bat=%d%%\\n",fix.lat,fix.lng,bat);}else lastSendTime=now; }`,
    `    else { Serial.printf("[gps] sats=%d hdop=%.1f\\n",fix.satellites,fix.hdop); lastSendTime=now; }`,
    `  }`,
    `  int cur2=WiFi.softAPgetStationNum(); if(cur2!=wifiClients){wifiClients=cur2;Serial.printf("[wifi] %d connected\\n",wifiClients);}`,
    `  delay(1000);`,
    `}`,
    ``,
    `GnssFix getGnssFix(){`,
    `  GnssFix fix={0}; float lat,lng,spd,alt,acc; int vs,us,yr,mo,dy,hr,mn,sc;`,
    `  if(modem.getGPS(&lat,&lng,&spd,&alt,&vs,&us,&acc,&yr,&mo,&dy,&hr,&mn,&sc)&&us>=4&&acc<3.0)`,
    `    fix={lat,lng,alt,spd,acc,us,true};`,
    `  else{fix.satellites=us;fix.hdop=acc;}`,
    `  return fix;`,
    `}`,
    ``,
    `bool sendFix(const GnssFix& fix,int battery){`,
    `  StaticJsonDocument<256> doc;`,
    `  doc["deviceId"]=DEVICE_ID; doc["lat"]=serialized(String(fix.lat,6)); doc["lng"]=serialized(String(fix.lng,6));`,
    `  doc["alt"]=serialized(String(fix.alt,1)); doc["speed"]=serialized(String(fix.speed,1));`,
    `  doc["battery"]=battery; doc["satellites"]=fix.satellites; doc["hdop"]=serialized(String(fix.hdop,2)); doc["clients"]=wifiClients;`,
    `  String body; serializeJson(doc,body);`,
    `  if(!client.connect(SERVER_HOST,SERVER_PORT)){Serial.println("[tls] connect failed");return false;}`,
    `  client.println("POST " + String(SERVER_PATH) + " HTTP/1.1");`,
    `  client.println("Host: " + String(SERVER_HOST));`,
    `  client.println("Content-Type: application/json");`,
    `  client.println("Content-Length: " + String(body.length()));`,
    `  client.println("Connection: close"); client.println(); client.print(body);`,
    `  uint32_t t=millis(); while(!client.available()&&millis()-t<10000)delay(10);`,
    `  String resp=""; while(client.available())resp+=(char)client.read(); client.stop();`,
    `  return resp.indexOf("200")>0||resp.indexOf("201")>0;`,
    `}`,
    ``,
    `int readBattery(){float v=(analogRead(BAT_ADC_PIN)/4095.0)*3.3*2.0;return constrain((int)(((v-3.0)/1.2)*100.0),0,100);}`,
    `float haversineM(float la1,float lo1,float la2,float lo2){const float R=6371000.0;float dLa=radians(la2-la1),dLo=radians(lo2-lo1),a=sin(dLa/2)*sin(dLa/2)+cos(radians(la1))*cos(radians(la2))*sin(dLo/2)*sin(dLo/2);return R*2*atan2(sqrt(a),sqrt(1-a));}`,
  ].join("\n");

  res.setHeader("Content-Disposition", `attachment; filename="${c.deviceId}_firmware.ino"`);
  res.setHeader("Content-Type", "text/plain");
  res.send(code);
});

