app.get("/api/tracker-position", rateLimit(20, 60000), async function(req, res) {
  const url = (req.query.url || "").trim();
  if (!url) return res.status(400).json({ err: "No URL" });

  try {
    // Try fetching the page and extracting lat/lon from JSON-LD or meta tags
    const r = await fetch(url, {
      headers: { "User-Agent": "Mozilla/5.0 (compatible; Event-Admin/1.0)" },
      signal: AbortSignal.timeout(8000)
    });
    const html = await r.text();

    // Try Sizzapp JSON pattern: {"lat":59.123,"lng":10.456} or {"latitude":...}
    let lat = null, lon = null;

    // Pattern 1: Sizzapp / common JSON in script tags
    const jsonPat = /"lat(?:itude)?"\s*:\s*([-\d.]+).*?"l(?:ng|on)(?:gitude)?"\s*:\s*([-\d.]+)/s;
    const m1 = html.match(jsonPat);
    if (m1) { lat = parseFloat(m1[1]); lon = parseFloat(m1[2]); }

    // Pattern 2: geo meta tags
    if (!lat) {
      const geoM = html.match(/geo\.position.*?content="([-\d.]+);([-\d.]+)"/);
      if (geoM) { lat = parseFloat(geoM[1]); lon = parseFloat(geoM[2]); }
    }

    // Pattern 3: OpenGraph / JSON-LD coordinates
    if (!lat) {
      const ogM = html.match(/"longitude"\s*:\s*([-\d.]+).*?"latitude"\s*:\s*([-\d.]+)/s)
               || html.match(/"latitude"\s*:\s*([-\d.]+).*?"longitude"\s*:\s*([-\d.]+)/s);
      if (ogM) {
        // determine which is lat vs lon
        if (html.indexOf('"latitude"') < html.indexOf('"longitude"')) {
          lat = parseFloat(ogM[1]); lon = parseFloat(ogM[2]);
        } else {
          lon = parseFloat(ogM[1]); lat = parseFloat(ogM[2]);
        }
      }
    }

    if (lat && lon && !isNaN(lat) && !isNaN(lon)) {
      return res.json({ ok: true, lat, lon });
    }
    return res.json({ ok: false, err: "Could not extract position from page" });
  } catch(e) {
    return res.json({ ok: false, err: e.message });
  }
});

// ── AI emoji suggestion (proxied to avoid CSP issues) ──────────
// GET /api/ai/config — provider, model, masked key, configured flag (admin)
app.get("/api/ai/config", auth, adminOnly, function(req, res) {
  const s = getSettings();
  const ai = s.ai || {};
  const cfg = getAIConfig();
  function mask(k){ if(!k) return ""; if(k.length<=8) return "••••"; return k.slice(0,5) + "…" + k.slice(-4); }
  res.json({
    provider: cfg.provider,
    model: ai.model || "",
    openrouterKeyMasked: mask(ai.openrouterKey || ""),
    anthropicKeyMasked: mask(ai.anthropicKey || ""),
    hasOpenrouterKey: !!ai.openrouterKey,
    hasAnthropicKey: !!(ai.anthropicKey),
    envKeyPresent: !!process.env.ANTHROPIC_API_KEY,
    configured: cfg.configured
  });
});

// PUT /api/ai/config — save provider/model/keys (admin). A blank or masked
// key is ignored so saving other fields doesn't wipe the stored key.
app.put("/api/ai/config", auth, adminOnly, function(req, res) {
  const s = getSettings();
  const ai = Object.assign({}, s.ai || {});
  const b = req.body || {};
  if (b.provider === "anthropic" || b.provider === "openrouter") ai.provider = b.provider;
  if (b.model !== undefined) ai.model = String(b.model || "").slice(0, 80);
  // Only update a key if a real new value is provided (not blank, not the mask)
  function isRealKey(k){ return k && k.indexOf("…") === -1 && k.indexOf("•") === -1; }
  if (b.openrouterKey !== undefined) {
    if (b.openrouterKey === "") ai.openrouterKey = "";           // explicit clear
    else if (isRealKey(b.openrouterKey)) ai.openrouterKey = String(b.openrouterKey).slice(0, 200);
  }
  if (b.anthropicKey !== undefined) {
    if (b.anthropicKey === "") ai.anthropicKey = "";
    else if (isRealKey(b.anthropicKey)) ai.anthropicKey = String(b.anthropicKey).slice(0, 200);
  }
  s.ai = ai;
  saveSettings(s);
  res.json({ ok: true, provider: getAIConfig().provider, configured: getAIConfig().configured });
});

