app.post("/api/ai/suggest-emoji", auth, rateLimit(20, 60000), async function(req, res) {
  const label = (req.body.label || "").trim().slice(0, 60);
  if (!label) return res.json({ emoji: "📋" });
  try {
    const { text } = await aiComplete({
      tier: "fast", max_tokens: 10,
      messages: [{ role: "user", content: "Reply with ONLY a single emoji for this event type: " + label + ". Only the emoji, nothing else." }]
    });
    const match = (text||"").match(/\p{Emoji_Presentation}|\p{Extended_Pictographic}/u);
    res.json({ emoji: match ? match[0] : "📋" });
  } catch(e) {
    res.json({ emoji: "📋" });  // graceful fallback whether unconfigured or error
  }
});

// AI route search: natural language → { location, filters[], label }
// e.g. "Trip to a sandy beach around Drammen" →
//   { location:"Drammen", filters:['node["natural"="beach"]'], label:"Sandstrender" }

// ── Robust JSON extraction from a model response ──────────────────
// Models frequently wrap JSON in prose ("Here is the JSON:"), markdown
// fences, or a trailing explanation. Parsing the whole reply then fails
// even though a perfectly good object is sitting inside it. This pulls
// out the first balanced {...} or [...] and parses that, ignoring
// braces that appear inside strings.
function extractJson(raw) {
  if (!raw) return null;
  let text = String(raw).trim()
    .replace(/^```[a-z]*\s*/i, "")
    .replace(/```\s*$/, "")
    .replace(/```/g, "")
    .trim();

  try { return JSON.parse(text); } catch (e) {}

  const start = text.search(/[\{\[]/);
  if (start < 0) return null;
  const open = text[start];
  const close = open === "{" ? "}" : "]";
  let depth = 0, inStr = false, esc = false;
  for (let i = start; i < text.length; i++) {
    const c = text[i];
    if (inStr) {
      if (esc) esc = false;
      else if (c === "\\") esc = true;
      else if (c === '"') inStr = false;
      continue;
    }
    if (c === '"') { inStr = true; continue; }
    if (c === open) depth++;
    else if (c === close) {
      depth--;
      if (depth === 0) {
        const slice = text.slice(start, i + 1);
        try { return JSON.parse(slice); } catch (e) { return null; }
      }
    }
  }
  // Unbalanced (truncated reply): close whatever is still open, innermost
  // first. A single-character repair is not enough - a cut-off reply can
  // leave both an array and an object open, in that order.
  const stack = [];
  inStr = false; esc = false;
  for (let i = start; i < text.length; i++) {
    const c = text[i];
    if (inStr) {
      if (esc) esc = false;
      else if (c === "\\") esc = true;
      else if (c === '"') inStr = false;
      continue;
    }
    if (c === '"') { inStr = true; continue; }
    if (c === "{" || c === "[") stack.push(c === "{" ? "}" : "]");
    else if (c === "}" || c === "]") stack.pop();
  }
  let repaired = text.slice(start);
  if (inStr) repaired += '"';                       // reply cut mid-string
  repaired = repaired.replace(/,\s*$/, "");
  while (stack.length) repaired += stack.pop();
  try { return JSON.parse(repaired); } catch (e) { return null; }
}

app.post("/api/ai/route-search", auth, rateLimit(20, 60000), async function(req, res) {
  const query = (req.body.query || "").trim().slice(0, 200);
  if (!query) return res.status(400).json({ error: st("empty_request", req) });
  if (!getAIConfig().configured) return res.status(503).json({ error: st("ai_not_configured_setup", req) });

  const sys = "You convert a natural-language trip search, written in Norwegian, Swedish, Danish or English, into a structured OpenStreetMap query. "
    + "Return ONLY valid JSON, no prose, no markdown. Schema: "
    + '{"location": string, "radiusKm": number, "filters": string[], "label": string}. '
    + "\"location\" is a place name to geocode (city/area mentioned, e.g. 'Drammen'). "
    + "\"radiusKm\" is how far around it to search (default 25, max 60). "
    + "\"filters\" is 1-4 Overpass QL element filters matching what the user wants, using real OSM tags. "
    + "Examples of valid filters: node[\"natural\"=\"beach\"], node[\"leisure\"=\"beach_resort\"], "
    + "node[\"natural\"=\"peak\"], node[\"historic\"], node[\"amenity\"~\"restaurant|cafe\"], "
    + "node[\"leisure\"~\"nature_reserve|park\"], node[\"tourism\"=\"museum\"], node[\"tourism\"=\"viewpoint\"], "
    + "node[\"natural\"=\"water\"], way[\"natural\"=\"beach\"]. "
    + "\"label\" is a short human label in Norwegian for what was found (e.g. 'Sandstrender'). "
    + "If no clear location is named, set location to empty string.";

  try {
    const { text: rawText } = await aiComplete({
      tier: "fast", max_tokens: 300, system: sys,
      messages: [{ role: "user", content: query }]
    });
    var text = (rawText || "").trim();
    var parsed = extractJson(text);
    if (!parsed || typeof parsed !== "object") {
      console.error("[route-search] Unparseable AI reply for query " + JSON.stringify(query) + ": " + text.slice(0, 300));
      return res.status(502).json({ error: st("ai_parse_failed_dot", req), raw: text.slice(0, 200) });
    }
    // Sanitize
    var out = {
      location: String(parsed.location || "").slice(0, 120),
      radiusKm: Math.min(60, Math.max(1, parseInt(parsed.radiusKm, 10) || 25)),
      filters: Array.isArray(parsed.filters) ? parsed.filters.filter(function(f){ return typeof f === "string" && /^(node|way|relation)\[/.test(f); }).slice(0, 4) : [],
      label: String(parsed.label || "Søkeresultat").slice(0, 60)
    };
    if (!out.filters.length) return res.status(422).json({ error: st("no_matching_category", req) });
    res.json(out);
  } catch(e) {
    res.status(502).json({ error: st("ai_unavailable", req) });
  }
});

// LAB: Publish to production – updates manifest.json on GitHub
app.post("/api/update/publish", auth, adminOnly, async function(req, res) {
  if (!IS_LAB) return res.status(400).json({ err: "Only available on the lab instance" });
  const token = req.body.githubToken || GITHUB_TOKEN;
  if (!token) return res.status(400).json({ err: "GIT_TOKEN / GITHUB_TOKEN ikke konfigurert – sett i docker-compose eller lim inn token" });

  const version = req.body.version || APP_VERSION;
  const changelog = req.body.changelog || [];

  // Helper: upload a single file to GitHub
  async function githubUpload(filePath, content, commitMsg) {
    // check about file finnes (trenger SHA for update)
    const checkR = await httpGet(
      "https://api.github.com/repos/" + GITHUB_REPO + "/contents/" + filePath,
      { "Authorization": "token " + token, "Accept": "application/vnd.github.v3+json" }
    );
    let sha = "";
    if (checkR.status === 200) {
      try { sha = JSON.parse(checkR.body.toString()).sha || ""; } catch(e) {}
    }

    const body = JSON.stringify({
      message: commitMsg,
      content: Buffer.from(content).toString("base64"),
      sha: sha || undefined
    });

    return new Promise(function(resolve, reject) {
      const https = require("https");
      const opts = {
        hostname: GIT_API_HOST,
        path: GIT_API_PREFIX + "/" + GITHUB_REPO + "/contents/" + filePath,
        method: "PUT",
        headers: {
          "Authorization": GIT_IS_GITEA ? "token " + token : "token " + token,
          "Accept": "application/vnd.github.v3+json",
          "Content-Type": "application/json",
          "Content-Length": Buffer.byteLength(body),
          "User-Agent": "Event-Admin/" + APP_VERSION
        }
      };
      const req2 = https.request(opts, function(r) {
        const chunks = [];
        r.on("data", function(c) { chunks.push(c); });
        r.on("end",  function()  {
          if (r.statusCode === 200 || r.statusCode === 201) resolve(true);
          else {
            let raw = Buffer.concat(chunks).toString();
            let msg = "HTTP " + r.statusCode;
            try { msg = JSON.parse(raw).message || msg; } catch(e) {}
            console.error("[git] " + r.statusCode + ":", raw.slice(0, 300));
            reject(new Error("GitHub: " + msg));
          }
        });
      });
      req2.on("error", reject);
      req2.write(body);
      req2.end();
    });
  }

  try {
    const crypto = require("crypto");
    const releaseDir = "releases/v" + version;
    const appFiles   = ["server.js", "index.html", "package.json"];
    const hashes     = {};
    const steps      = [];

    // 1. Upload the code files to releases/vX.X.X/
    for (const name of appFiles) {
      const localPath = path.join(process.cwd(), name);
      if (!fs.existsSync(localPath)) throw new Error("Cannot find " + name + " in /app");
      const content = fs.readFileSync(localPath);
      hashes[name] = crypto.createHash("sha256").update(content).digest("hex");
      await githubUpload(releaseDir + "/" + name, content, "v" + version + ": " + name);
      steps.push("✅ " + releaseDir + "/" + name);
      console.log("[publish] Lastet opp " + releaseDir + "/" + name);
    }

    // 2. build manifest-objekt
    const manifest = {
      version,
      released: new Date().toISOString().slice(0, 10),
      changelog: changelog.length ? changelog : ["v" + version],
      files: appFiles.map(function(name) {
        return {
          name,
          url: "https://raw.githubusercontent.com/" + GITHUB_REPO + "/main/" + releaseDir + "/" + name,
          sha256: hashes[name]
        };
      })
    };

    const manifestJson = JSON.stringify(manifest, null, 2);

    // 3. Oppdater manifest-lab.json
    const labManifestFile = UPDATE_MANIFEST;
    await githubUpload(labManifestFile, manifestJson, "v" + version + " lab-manifest");
    steps.push("✅ " + labManifestFile);

    // 4. update manifest.json (prod) only if req.body.publishProd
    if (req.body.publishProd) {
      await githubUpload("manifest.json", manifestJson, "Publiser v" + version + " til produksjon");
      steps.push("✅ manifest.json (prod)");
    }

    console.log("[publish] Ferdig:", steps.join(", "));
    res.json({
      ok: true,
      version,
      steps,
      hashes,
      prodPublished: !!req.body.publishProd,
      message: req.body.publishProd
        ? "v" + version + " er lastet opp og tilgjengelig for alle instanser!"
        : "v" + version + " er lastet opp til GitHub og tilgjengelig for lab-testing. Klikk 'Godkjenn til produksjon' når du er klar."
    });

  } catch(e) {
    console.error("[publish] Feil:", e.message);
    res.status(500).json({ err: e.message });
  }
});

// Hjelpefunksjon: pakk out ZIP and returner file
function extractZip(zipBuf) {
  const files = {};
  let i = 0;
  while (i < zipBuf.length - 4) {
    // Local file header: PK\x03\x04
    if (zipBuf[i]===0x50 && zipBuf[i+1]===0x4b && zipBuf[i+2]===0x03 && zipBuf[i+3]===0x04) {
      const compression  = zipBuf.readUInt16LE(i+8);
      const compSize     = zipBuf.readUInt32LE(i+18);
      const uncompSize   = zipBuf.readUInt32LE(i+22);
      const fnLen        = zipBuf.readUInt16LE(i+26);
      const extraLen     = zipBuf.readUInt16LE(i+28);
      const filename     = zipBuf.slice(i+30, i+30+fnLen).toString("utf8");
      const dataStart    = i+30+fnLen+extraLen;
      const dataBuf      = zipBuf.slice(dataStart, dataStart+compSize);

      // Only fetch the files we need (handles both root level and subdirectories)
      const basename = filename.split("/").pop();
      if (["server.js","index.html","package.json","CONTRIBUTING.md","README.md"].includes(basename) && uncompSize > 0) {
        if (compression === 0) {
          // Stored (none/no komprimering)
          files[basename] = dataBuf;
        } else if (compression === 8) {
          // Deflate
          try {
            files[basename] = require("zlib").inflateRawSync(dataBuf);
          } catch(e) {}
        }
      }
      i = dataStart + compSize;
    } else {
      i++;
    }
  }
  return files;
}

// LAB: Upload new app files directly via GUI (supports single files and ZIP)
// user multer (allerede installert) istedet for busboy
const labUploadMulter = multer({
  storage: multer.memoryStorage(),
  limits: { fileSize: 250 * 1024 * 1024 }
}).any();

app.post("/api/update/upload", auth, adminOnly, function(req, res) {
  // Run multer first to consume the multipart body — rejecting early causes browser hang
  labUploadMulter(req, res, function(err) {
    if (err) return res.status(400).json({ err: "Opplasting feilet: " + err.message });
    if (!IS_LAB) return res.status(400).json({ err: "Only available on the lab instance" });

    const crypto = require("crypto");
    const allowedFiles = ["server.js", "index.html", "package.json", "CONTRIBUTING.md", "README.md"];
    const uploaded = [];
    const errors   = [];

    function saveFile(filename, buf) {
      const hash = crypto.createHash("sha256").update(buf).digest("hex");
      const dest = path.join(process.cwd(), filename);
      const backupDir = path.join(DATA, "_lab_upload_backup");
      try {
        fs.mkdirSync(backupDir, { recursive: true });
        if (fs.existsSync(dest)) fs.copyFileSync(dest, path.join(backupDir, filename));
      } catch(e) {}
      try {
        fs.writeFileSync(dest, buf);
        uploaded.push({ name: filename, size: buf.length, sha256: hash });
      } catch(e) {
        errors.push("Kunne ikke skrive " + filename + ": " + e.message);
      }
    }

    const files = req.files || [];
    if (!files.length) return res.status(400).json({ err: "Ingen filer mottatt" });

    files.forEach(function(f) {
      const filename = f.originalname;
      const buf = f.buffer;

      if (filename.toLowerCase().endsWith(".zip")) {
        try {
          const zipFiles = extractZip(buf);
          const names = Object.keys(zipFiles);
          if (!names.length) {
            errors.push("ZIP inneholder ingen kjente filer");
          } else {
            names.forEach(function(name) { saveFile(name, zipFiles[name]); });
          }
        } catch(e) {
          errors.push("ZIP-feil: " + e.message);
        }
      } else if (allowedFiles.includes(filename)) {
        saveFile(filename, buf);
      } else {
        errors.push("Ugyldig filnavn: " + filename);
      }
    });

    if (uploaded.length === 0 && errors.length > 0)
      return res.status(400).json({ err: errors.join(", ") });

    console.log("[lab-upload] Lastet opp:", uploaded.map(function(f) { return f.name; }).join(", "));
    res.json({ ok: true, uploaded, errors, message: "Files uploaded! Restart to apply." });
  });
});

