// POST /api/invites — manager sends invite
app.post("/api/invites", auth, managerOrAdmin, async function(req, res) {
  const me       = req.session.user;
  const email    = (req.body.email || "").toLowerCase().trim();
  const role     = req.body.role     || "event_manager";
  const dept     = req.body.department || null;
  const subgroups  = req.body.subgroups  || [];
  const eventTypes = req.body.eventTypes || [];
  const assignType = req.body.assignmentType || "primary";
  const message    = (req.body.message || "").trim();

  if (!email) return res.status(400).json({ error: st("email_required", req) });
  if (!dept)  return res.status(400).json({ error: deptWordCap() + " er påkrevd" });

  // Check manager has access to this dept
  if (me.role !== "admin") {
    const myDepts = getUserDepartments(me);
    if (!myDepts.includes(dept)) return res.status(403).json({ error: st("no_access_department", req) });
  }

  const settings   = getSettings();
  const depts      = settings.departments || [];
  const deptObj    = depts.find(function(d) { return d.id === dept; });
  const deptName   = deptObj ? (deptObj.displayName || deptObj.name) : dept;
  const inviterName = me.name || me.email;
  const siteName   = settings.siteName || "Event-Admin";
  const siteUrl    = (settings.siteUrl || ("https://" + (process.env.ADMIN_DOMAIN || "localhost")));

  // Check for existing pending invite for same email+dept
  const invites = readInvites();
  const existing = invites.find(function(i) {
    return i.email === email && i.department === dept && i.status === "pending";
  });
  if (existing) {
    return res.status(409).json({ error: st("invite_already_open", req), inviteId: existing.id });
  }

  // Role labels
  const roleLabels = { department_manager:"Avdelingsleder", subgroup_manager:"Undergruppeansvarlig", event_manager:"Arrangementsansvarlig" };
  const roleLabel  = roleLabels[role] || role;

  // Create invite record
  const token  = require("crypto").randomBytes(32).toString("hex");
  const invite = {
    id:          uuid(),
    token:       token,
    email:       email,
    department:  dept,
    role:        role,
    subgroups:   subgroups,
    eventTypes:  eventTypes,
    assignmentType: assignType,
    invitedBy:   me.id,
    inviterName: inviterName,
    inviterEmail: me.email,
    message:     message,
    status:      "pending",
    createdAt:   new Date().toISOString(),
    expiresAt:   new Date(Date.now() + 14 * 86400000).toISOString(), // 14 days
  };
  invites.push(invite);
  writeInvites(invites);

  // Build invite link
  const inviteUrl = siteUrl + "/invite/" + token;

  // Send invitation email
  const html = `<div style="font-family:sans-serif;max-width:600px">
    <div style="background:#1a1a1a;padding:1.5rem;border-radius:12px 12px 0 0;text-align:center">
      <div style="font-size:2rem;margin-bottom:.5rem">🎉</div>
      <h2 style="color:#FFD100;margin:0;font-size:1.3rem">${escHtml(siteName)}</h2>
    </div>
    <div style="background:#fff;padding:2rem;border:1px solid #e5e7eb;border-top:none;border-radius:0 0 12px 12px">
      <h3 style="color:#111;margin:0 0 1rem">Du er invitert!</h3>
      <p style="color:#374151;margin-bottom:1rem">
        <strong>${escHtml(inviterName)}</strong> inviterer deg til å ta rollen som
        <strong>${escHtml(roleLabel)}</strong> i <strong>${escHtml(deptName)}</strong>.
      </p>
      ${message ? `<div style="background:#f9fafb;border-left:3px solid #FFD100;padding:.75rem 1rem;margin-bottom:1rem;font-size:.9rem;color:#374151;font-style:italic">${escHtml(message)}</div>` : ''}
      <p style="color:#6b7280;font-size:.88rem;margin-bottom:1.5rem">
        Klikk knappen nedenfor for å godta invitasjonen, fylle inn din informasjon og aktivere kontoen din.
        Lenken er gyldig i 14 dager.
      </p>
      <div style="text-align:center;margin:1.5rem 0">
        <a href="${escHtml(inviteUrl)}"
          style="display:inline-block;background:#FFD100;color:#111;font-weight:800;font-size:1rem;padding:.85rem 2rem;border-radius:8px;text-decoration:none">
          ✅ Godta invitasjon →
        </a>
      </div>
      <p style="color:#9ca3af;font-size:.78rem;text-align:center">
        Hvis du ikke kjenner til denne invitasjonen kan du ignorere denne e-posten.<br>
        Lenke: <a href="${escHtml(inviteUrl)}" style="color:#6b7280">${escHtml(inviteUrl)}</a>
      </p>
    </div>
  </div>`;

  try {
    await sendEmail({ to: email, subject: "Invitasjon til " + siteName + " – " + deptName, html, department: dept, category: "invite" });
  } catch(e) {
    console.error("[invite] email failed:", e && e.message);
    return res.status(500).json({ error: st("email_send_failed_prefix", req) + (e.message||"ukjent feil") });
  }

  res.json({ ok: true, inviteId: invite.id, expiresAt: invite.expiresAt });
});

// GET /api/invites — list invites (manager sees own dept, admin sees all)
app.get("/api/invites", auth, managerOrAdmin, function(req, res) {
  const me      = req.session.user;
  const invites = readInvites();
  const myDepts = me.role === "admin" ? null : getUserDepartments(me);
  res.json(invites.filter(function(i) {
    return myDepts === null || myDepts.includes(i.department);
  }).map(function(i) {
    return { id:i.id, email:i.email, department:i.department, role:i.role, status:i.status,
             inviterName:i.inviterName, createdAt:i.createdAt, expiresAt:i.expiresAt, message:i.message };
  }));
});

// DELETE /api/invites/:id — cancel invite
app.delete("/api/invites/:id", auth, managerOrAdmin, function(req, res) {
  const invites = readInvites();
  const idx     = invites.findIndex(function(i){ return i.id === req.params.id; });
  if (idx < 0) return res.status(404).json({ error: st("not_found_generic", req) });
  invites[idx].status = "cancelled";
  writeInvites(invites);
  res.json({ ok: true });
});

