// \u2500\u2500 Plan items (calendar/tasks) \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500
app.put("/api/events/:id/plan-items", auth, managerOrAdmin, function(req, res) {
  var events = readJSON(EVENTS_FILE);
  var idx    = events.findIndex(function(e) { return e.id === req.params.id; });
  if (idx < 0) return res.status(404).json({ error: st("not_found_generic", req) });
  events[idx].planItems = req.body.planItems || [];
  writeJSON(EVENTS_FILE, events);
  res.json({ ok: true });
});

// \u2500\u2500 Cancel / uncancel event \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500
app.put("/api/events/:id/cancel", auth, managerOrAdmin, async function(req, res) {
  const events = readJSON(EVENTS_FILE);
  const idx    = events.findIndex(function(e) { return e.id === req.params.id; });
  if (idx < 0) return res.status(404).json({ error: st("not_found_generic", req) });
  const ev        = events[idx];
  const cancelled = !!req.body.cancelled;
  const reason    = (req.body.cancelReason || "").trim();

  ev.cancelled    = cancelled;
  ev.cancelReason = reason;
  ev.cancelledAt  = cancelled ? new Date().toISOString() : null;

  // When reverting a "cancelled and moved" event, undo the move too:
  // remove the auto-created replacement event (unless it has diverged with
  // its own new registrations) and clear the cross-links.
  let removedReschedule = false;
  let keptReschedule    = false;
  if (!cancelled && ev.rescheduledTo) {
    const newIdx = events.findIndex(function(e) { return e.id === ev.rescheduledTo; });
    if (newIdx >= 0) {
      const newEv = events[newIdx];
      const carried = (ev.registrations || []).length;
      const nowOnNew = (newEv.registrations || []).length;
      // Diverged if the replacement gained registrations beyond what was carried over
      if (nowOnNew > carried) {
        keptReschedule = true;
        delete newEv.rescheduledFrom; // unlink but keep the event (has its own data)
      } else {
        events.splice(newIdx, 1);     // safe to remove the untouched clone
        removedReschedule = true;
      }
    }
    delete ev.rescheduledTo;
    delete ev.rescheduledToUrl;
    delete ev.rescheduledToDate;
    if (ev.status === "postponed") delete ev.status;
  }

  writeJSON(EVENTS_FILE, events);
  broadcastEventUpdate(ev.department);

  // \u2500\u2500 Dept banner announcement \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500
  if (ev.department) {
    const s     = getSettings();
    const depts = s.departments || [];
    const dIdx  = depts.findIndex(function(d) { return d.id === ev.department; });
    if (dIdx >= 0) {
      const dept = depts[dIdx];
      if (cancelled) {
        // Save previous banner so we can restore it later
        dept._preCancelBanner = dept.bannerText || "";
        const dateStr = ev.date
          ? new Date(ev.date).toLocaleDateString('nb-NO', { day:'numeric', month:'long' })
          : '';
        dept.bannerText = '\ud83d\udeab AVLYST' + (ev.title ? ': ' + ev.title : '') + (dateStr ? ' (' + dateStr + ')' : '') + (reason ? ' \u2013 ' + reason : '');
        dept._cancelBannerEvId   = ev.id;
        dept._cancelBannerExpiry = ev.date || null; // restore after event date
      } else {
        // Restore previous banner only if the stored evId matches
        if (dept._cancelBannerEvId === ev.id) {
          dept.bannerText = dept._preCancelBanner || "";
          delete dept._preCancelBanner;
          delete dept._cancelBannerEvId;
          delete dept._cancelBannerExpiry;
        }
      }
      s.departments = depts;
      saveSettings(s);
    }
  }

  // Send cancellation emails to all confirmed registrants
  if (cancelled && (ev.registrations||[]).length) {
    const settings  = getSettings();
    const dateStr   = ev.date ? new Date(ev.date).toLocaleDateString('nb-NO',{weekday:'long',day:'numeric',month:'long',year:'numeric'}) : '';
    const fromName  = getEvSenderInfo(ev).name;
    const regs      = (ev.registrations||[]).filter(function(r){ return r.email && !r.anonymized && !r.cancelledAt && !r.waitlist; });

    regs.forEach(function(reg) {
      const html = `<div style="font-family:sans-serif;max-width:600px">
        <div style="background:#ef4444;padding:1.25rem;border-radius:10px 10px 0 0;text-align:center">
          <div style="font-size:2.5rem">\ud83d\udeab</div>
          <h2 style="color:#fff;margin:.5rem 0 0;font-size:1.3rem">Arrangementet er avlyst</h2>
        </div>
        <div style="background:#fff;padding:1.5rem;border:1px solid #fecaca;border-top:none;border-radius:0 0 10px 10px">
          <p style="color:#111;font-size:1rem;margin-bottom:1rem">Hei ${escHtml(reg.name||'')},</p>
          <p style="color:#374151">Vi m\u00e5 dessverre informere om at <strong>${escHtml(ev.title||'')}</strong>${dateStr ? ' (' + escHtml(dateStr) + ')' : ''} er avlyst.</p>
          ${reason ? `<div style="background:#fef2f2;border:1px solid #fecaca;border-radius:8px;padding:1rem;margin:1.25rem 0;color:#dc2626;font-size:.95rem"><strong>\u00c5rsak:</strong> ${escHtml(reason)}</div>` : ''}
          <p style="color:#6b7280;font-size:.9rem;margin-top:1rem">Beklager ulempene dette medf\u00f8rer. Ta gjerne kontakt med oss dersom du har sp\u00f8rsm\u00e5l.</p>
          ${((settings.departments||[]).find(function(d){return d.id===ev.department;})||{}).contactEmail||settings.contactEmail ? `<p style="color:#6b7280;font-size:.85rem">Kontakt: <a href="mailto:${escHtml(((settings.departments||[]).find(function(d){return d.id===ev.department;})||{}).contactEmail||settings.contactEmail)}" style="color:#ef4444">${escHtml(((settings.departments||[]).find(function(d){return d.id===ev.department;})||{}).contactEmail||settings.contactEmail)}</a></p>` : ''}
        </div>
      </div>`;
      sendEmail({ to: reg.email, subject: '\ud83d\udeab Avlyst: ' + (ev.title||'Arrangement'), html, fromName, department: ev.department, eventId: ev.id, category: "registration" }).catch(function(){});
    });
    return res.json({ ok: true, notified: regs.length });
  }

  res.json({ ok: true, notified: 0, removedReschedule: removedReschedule, keptReschedule: keptReschedule });
});

// PUT /api/events/:id/reset-status \u2014 clear all cancel/move/reschedule flags,
// returning the event to an ordinary, active state. Also unlinks any partner
// event (e.g. after the linked event was deleted, leaving a dangling pointer).
app.put("/api/events/:id/reset-status", auth, managerOrAdmin, function(req, res) {
  const events = readJSON(EVENTS_FILE);
  const ev = events.find(function(e) { return e.id === req.params.id; });
  if (!ev) return res.status(404).json({ error: st("not_found_generic", req) });

  // If a partner event still exists, unlink it too (clear its back-reference)
  if (ev.rescheduledTo) {
    const partner = events.find(function(e) { return e.id === ev.rescheduledTo; });
    if (partner && partner.rescheduledFrom === ev.id) delete partner.rescheduledFrom;
  }
  if (ev.rescheduledFrom) {
    const src = events.find(function(e) { return e.id === ev.rescheduledFrom; });
    if (src && src.rescheduledTo === ev.id) {
      delete src.rescheduledTo;
      delete src.rescheduledToUrl;
      delete src.rescheduledToDate;
      if (src.status === "postponed" || src.status === "moved") delete src.status;
      src.cancelled = false; // a source that only existed as "cancelled+moved" is restored
    }
  }

  // Clear every cancel/move field on this event
  ev.cancelled = false;
  delete ev.cancelReason;
  delete ev.cancelledAt;
  delete ev.status;
  delete ev.rescheduledTo;
  delete ev.rescheduledToUrl;
  delete ev.rescheduledToDate;
  delete ev.rescheduledFrom;
  delete ev.movedNote;
  delete ev.movedAt;
  delete ev.movedFromDate;

  writeJSON(EVENTS_FILE, events);
  broadcastEventUpdate(ev.department);
  res.json({ ok: true });
});

// PUT /api/events/:id/postpone  { newDate, newTime?, newEndDate?, newEndTime?, note? }
// Weather/other postponement: mark the old event as postponed (cancelled +
// status), create a linked NEW event on the new date with registrations
// carried over and the guestbook shared, and email registrants that their
// spot is kept.
app.put("/api/events/:id/postpone", auth, managerOrAdmin, async function(req, res) {
  const events = readJSON(EVENTS_FILE);
  const idx    = events.findIndex(function(e) { return e.id === req.params.id; });
  if (idx < 0) return res.status(404).json({ error: st("not_found_generic", req) });
  const oldEv = events[idx];

  const newDate = (req.body.newDate || "").trim();
  if (!newDate) return res.status(400).json({ error: st("missing_new_date", req) });
  const note = (req.body.note || "").trim();
  const mode = req.body.mode || "cancel-move";

  // \u2500\u2500 MODE: move in place (not cancelled) \u2014 just change the date + notify \u2500\u2500
  if (mode === "move") {
    const newTimeM = req.body.newTime || (oldEv.date && oldEv.date.length >= 16 ? oldEv.date.slice(11,16) : (oldEv.time || "00:00"));
    const oldDateStrM = oldEv.date ? new Date(oldEv.date).toLocaleDateString("nb-NO",{weekday:"long",day:"numeric",month:"long",year:"numeric"}) : "";
    oldEv.movedFromDate = oldEv.date || null;       // remember where it moved FROM
    oldEv.date    = newDate + "T" + newTimeM;
    oldEv.time    = newTimeM;
    oldEv.status  = "moved";
    oldEv.movedNote = note || null;
    oldEv.movedAt = new Date().toISOString();
    oldEv.rescheduledToDate = newDate + "T" + newTimeM; // new date, for banners/rows
    // not cancelled \u2014 clear any stale cancel flags
    oldEv.cancelled = false;
    writeJSON(EVENTS_FILE, events);
    broadcastEventUpdate(oldEv.department);

    let notifiedM = 0;
    const newDateStrM = new Date(newDate + "T" + newTimeM).toLocaleDateString("nb-NO",{weekday:"long",day:"numeric",month:"long",year:"numeric"});
    const fromNameM = getEvSenderInfo(oldEv).name;
    (oldEv.registrations||[]).filter(function(r){ return r.email && !r.anonymized && !r.waitlist; }).forEach(function(reg) {
      const html = `<div style="font-family:sans-serif;max-width:600px">
        <div style="background:#f59e0b;padding:1.25rem;border-radius:10px 10px 0 0;text-align:center">
          <div style="font-size:2.5rem">\ud83d\udcc5</div>
          <h2 style="color:#fff;margin:.5rem 0 0;font-size:1.3rem">Ny dato for arrangementet</h2>
        </div>
        <div style="background:#fff;padding:1.5rem;border:1px solid #fde68a;border-top:none;border-radius:0 0 10px 10px">
          <p style="color:#111;margin-bottom:1rem">Hei ${escHtml(reg.name||"")},</p>
          <p style="color:#374151"><strong>${escHtml(oldEv.title||"")}</strong> har f\u00e5tt ny dato.</p>
          ${oldDateStrM ? `<p style="color:#6b7280;font-size:.9rem;margin:.25rem 0">Tidligere: <s>${escHtml(oldDateStrM)}</s></p>` : ""}
          <div style="background:#ecfdf5;border:1px solid #a7f3d0;border-radius:8px;padding:1rem;margin:1rem 0;color:#065f46">
            <strong>Ny dato: ${escHtml(newDateStrM)}</strong><br>
            <span style="font-size:.9rem">Plassen din er beholdt \u2013 du trenger ikke gj\u00f8re noe.</span>
          </div>
          ${note ? `<div style="background:#fffbeb;border:1px solid #fde68a;border-radius:8px;padding:1rem;margin:1rem 0;color:#b45309;font-size:.95rem">${escHtml(note)}</div>` : ""}
        </div></div>`;
      sendEmail({ to: reg.email, subject: "\ud83d\udcc5 Ny dato: " + (oldEv.title||"Arrangement"), html, fromName: fromNameM, department: oldEv.department, eventId: oldEv.id, category: "registration" }).catch(function(){});
      notifiedM++;
    });
    return res.json({ ok: true, moved: true, notified: notifiedM });
  }

  // \u2500\u2500 MODE: cancel + create linked new event (default) \u2500\u2500
  const newId = uuid();
  const baseSlug = (oldEv.slug || (oldEv.title || "event").toLowerCase()
    .replace(/\u00e6/g,"ae").replace(/\u00f8/g,"o").replace(/\u00e5/g,"a")
    .replace(/[^a-z0-9]+/g,"-").replace(/^-|-$/g,"")).replace(/-\d{4}-\d{2}-\d{2}$/,"");
  const newSlug = baseSlug + "-" + newDate;
  // Derive the event domain from the old event's URL to build the new URL
  let evDomainPart = "";
  if (oldEv.url) { var m = oldEv.url.match(/^https?:\/\/[^.]+\.(.+)$/); if (m) evDomainPart = m[1]; }
  const newUrl = evDomainPart ? ("https://" + newSlug + "." + evDomainPart) : (oldEv.url || "");

  const newEv = Object.assign({}, oldEv, {
    id: newId,
    slug: newSlug,
    url: newUrl,
    date: newDate,
    time: req.body.newTime || oldEv.time || "",
    endDate: req.body.newEndDate || oldEv.endDate || null,
    endTime: req.body.newEndTime || oldEv.endTime || null,
    cancelled: false,
    cancelReason: "",
    cancelledAt: null,
    status: "rescheduled",
    createdAt: new Date().toISOString(),
    // Carry registrations over (fresh copies, clear any cancellation flags)
    registrations: (oldEv.registrations || []).map(function(r) {
      return Object.assign({}, r, { cancelledAt: null, movedFrom: oldEv.id });
    }),
    // Share the guestbook with the original (same array reference content)
    guestbook: oldEv.guestbook || [],
    // Cross-link
    rescheduledFrom: oldEv.id,
    rescheduledTo: null,
  });

  // Mark the old event postponed (cancelled flag drives existing banner/UI)
  oldEv.cancelled     = true;
  oldEv.status        = "postponed";
  oldEv.cancelReason  = note || ("Utsatt til " + new Date(newDate).toLocaleDateString("nb-NO", { day:"numeric", month:"long", year:"numeric" }));
  oldEv.cancelledAt   = new Date().toISOString();
  oldEv.rescheduledTo = newId;
  oldEv.rescheduledToUrl  = newUrl;
  oldEv.rescheduledToDate = newDate;

  events.push(newEv);
  writeJSON(EVENTS_FILE, events);
  broadcastEventUpdate(oldEv.department);

  // Email registrants: postponed, spot kept
  let notified = 0;
  const settings = getSettings();
  const oldDateStr = oldEv.date ? new Date(oldEv.date).toLocaleDateString("nb-NO",{weekday:"long",day:"numeric",month:"long",year:"numeric"}) : "";
  const newDateStr = new Date(newDate).toLocaleDateString("nb-NO",{weekday:"long",day:"numeric",month:"long",year:"numeric"});
  const fromName   = getEvSenderInfo(oldEv).name;
  const regs       = (oldEv.registrations||[]).filter(function(r){ return r.email && !r.anonymized && !r.waitlist; });

  regs.forEach(function(reg) {
    const html = `<div style="font-family:sans-serif;max-width:600px">
      <div style="background:#f59e0b;padding:1.25rem;border-radius:10px 10px 0 0;text-align:center">
        <div style="font-size:2.5rem">\ud83d\udcc5</div>
        <h2 style="color:#fff;margin:.5rem 0 0;font-size:1.3rem">Arrangementet er utsatt</h2>
      </div>
      <div style="background:#fff;padding:1.5rem;border:1px solid #fde68a;border-top:none;border-radius:0 0 10px 10px">
        <p style="color:#111;font-size:1rem;margin-bottom:1rem">Hei ${escHtml(reg.name||"")},</p>
        <p style="color:#374151"><strong>${escHtml(oldEv.title||"")}</strong>${oldDateStr ? " (" + escHtml(oldDateStr) + ")" : ""} er dessverre utsatt${note ? "" : " p\u00e5 grunn av forholdene"}.</p>
        ${note ? `<div style="background:#fffbeb;border:1px solid #fde68a;border-radius:8px;padding:1rem;margin:1rem 0;color:#b45309;font-size:.95rem">${escHtml(note)}</div>` : ""}
        <div style="background:#ecfdf5;border:1px solid #a7f3d0;border-radius:8px;padding:1rem;margin:1.25rem 0;color:#065f46;font-size:1rem">
          <strong>Ny dato: ${escHtml(newDateStr)}</strong><br>
          <span style="font-size:.9rem">Plassen din er beholdt \u2013 du trenger ikke melde deg p\u00e5 p\u00e5 nytt.</span>
        </div>
        <p style="color:#6b7280;font-size:.9rem">Kan du ikke den nye datoen? Ta kontakt s\u00e5 hjelper vi deg.</p>
        ${((settings.departments||[]).find(function(d){return d.id===ev.department;})||{}).contactEmail||settings.contactEmail ? `<p style="color:#6b7280;font-size:.85rem">Kontakt: <a href="mailto:${escHtml(((settings.departments||[]).find(function(d){return d.id===ev.department;})||{}).contactEmail||settings.contactEmail)}" style="color:#f59e0b">${escHtml(((settings.departments||[]).find(function(d){return d.id===ev.department;})||{}).contactEmail||settings.contactEmail)}</a></p>` : ""}
      </div>
    </div>`;
    sendEmail({ to: reg.email, subject: "\ud83d\udcc5 Utsatt \u2013 ny dato: " + (oldEv.title||"Arrangement"), html, fromName, department: oldEv.department, eventId: oldEv.id, category: "registration" }).catch(function(){});
    notified++;
  });

  res.json({ ok: true, newEventId: newId, newSlug: newSlug, notified: notified });
});

function readForms()       { return readJSON(FORMS_FILE); }
function writeForms(forms) { writeJSON(FORMS_FILE, forms); }
function formSlug(title)   { return title.toLowerCase().replace(/\u00e6/g,'ae').replace(/\u00f8/g,'oe').replace(/\u00e5/g,'aa').replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,50)+'-'+Date.now().toString(36); }

app.get("/api/forms", auth, managerOrAdmin, function(req, res) {
  var me = req.session.user;
  var forms = readForms();
  if (me.role !== "admin") {
    var myDepts = getUserDepartments(me);
    forms = forms.filter(function(f) { return myDepts.includes(f.department) || f.createdBy === me.email; });
  }
  res.json(forms.map(function(f) {
    return Object.assign({}, f, { responses: (f.responses||[]).map(function(r) { return { id:r.id, submittedAt:r.submittedAt }; }) });
  }));
});

app.get("/api/forms/:id", auth, managerOrAdmin, function(req, res) {
  var form = readForms().find(function(f) { return f.id === req.params.id; });
  if (!form) return res.status(404).json({ error: st("not_found_generic", req) });
  res.json(form);
});

app.post("/api/forms", auth, managerOrAdmin, function(req, res) {
  var me = req.session.user; var forms = readForms(); var body = req.body;
  var form = { id:uuid(), title:(body.title||"").trim(), slug:formSlug(body.title||"form"), eventId:body.eventId||null, department:body.department||null, recipientEmail:body.recipientEmail||null, outro:body.outro||"Takk for ditt svar!", slides:body.slides||[], formMode:body.formMode||"simple", volunteerSlides:body.volunteerSlides||[], responses:[], createdBy:me.email, createdAt:new Date().toISOString(), updatedAt:new Date().toISOString() };
  if (!form.title) return res.status(400).json({ error: st("title_required", req) });
  forms.push(form); writeForms(forms); res.json(form);
});

app.put("/api/forms/:id", auth, managerOrAdmin, function(req, res) {
  var forms = readForms(); var idx = forms.findIndex(function(f) { return f.id === req.params.id; });
  if (idx < 0) return res.status(404).json({ error: st("not_found_generic", req) });
  var body = req.body;
  forms[idx] = Object.assign(forms[idx], {
    title:           (body.title||"").trim()    || forms[idx].title,
    eventId:         body.eventId              !== undefined ? body.eventId        : forms[idx].eventId,
    department:      body.department           !== undefined ? body.department     : forms[idx].department,
    recipientEmail:  body.recipientEmail       !== undefined ? body.recipientEmail : forms[idx].recipientEmail,
    outro:           body.outro                !== undefined ? body.outro          : forms[idx].outro,
    slides:          body.slides               || forms[idx].slides,
    formMode:        body.formMode             !== undefined ? body.formMode       : forms[idx].formMode,
    volunteerSlides: body.volunteerSlides      !== undefined ? body.volunteerSlides: forms[idx].volunteerSlides,
    updatedAt:       new Date().toISOString(),
  });
  writeForms(forms); res.json(forms[idx]);
});

app.delete("/api/forms/:id", auth, managerOrAdmin, function(req, res) {
  writeForms(readForms().filter(function(f) { return f.id !== req.params.id; })); res.json({ ok: true });
});

app.post("/api/forms/upload-image", auth, managerOrAdmin, upload.single("image"), function(req, res) {
  if (!req.file) return res.status(400).json({ error: st("no_file", req) });
  var ext  = path.extname(req.file.originalname).toLowerCase() || '.jpg';
  var name = 'form-' + uuid() + ext;
  var dest = path.join(__dirname, "public", "form-images", name);
  if (!fs.existsSync(path.dirname(dest))) fs.mkdirSync(path.dirname(dest), { recursive: true });
  fs.renameSync(req.file.path, dest);
  res.json({ url: '/public/form-images/' + name });
});

app.post("/api/forms/:slug/submit", rateLimit(20, 60000), async function(req, res) {
  var forms = readForms();
  var form  = forms.find(function(f) { return f.slug === req.params.slug || f.id === req.params.slug; });
  if (!form) return res.status(404).json({ error: st("form_not_found", req) });
  var body = req.body;
  var response = { id:uuid(), name:(body.name||"").trim()||null, email:(body.email||"").trim()||null, answers:body.answers||{}, submittedAt:new Date().toISOString() };
  if (!form.responses) form.responses = [];
  form.responses.push(response);
  writeForms(forms);

  var settings = getSettings();
  var slides   = (form.slides||[]).filter(function(s){ return s.type!=='info'; });
  var rows     = slides.map(function(sl) {
    var ans = response.answers[sl.id];
    if (Array.isArray(ans)) ans = ans.join(', ');
    return '<tr><td style="padding:6px 12px;border-bottom:1px solid #eee;color:#888;font-size:.82rem">' + escHtml(sl.title) + '</td><td style="padding:6px 12px;border-bottom:1px solid #eee;font-size:.88rem">' + escHtml(String(ans||'\u2014')) + '</td></tr>';
  }).join('');
  var html = '<div style="font-family:sans-serif;max-width:600px"><h2>\ud83d\udccb Nytt skjemasvar: ' + escHtml(form.title) + '</h2><table style="width:100%;border-collapse:collapse;margin-top:1rem"><thead><tr style="background:#1a1a1a;color:#fff"><th style="padding:8px 12px;text-align:left">Sp\u00f8rsm\u00e5l</th><th style="padding:8px 12px;text-align:left">Svar</th></tr></thead><tbody>' + rows + '</tbody></table></div>';

  var recipients = [];
  var _formDeptId = null, _formEvId = null;
  if (form.recipientEmail) recipients.push(form.recipientEmail);
  if (form.eventId) {
    var ev = readJSON(EVENTS_FILE).find(function(e){ return e.id===form.eventId; });
    if (ev) { _formDeptId = ev.department || null; _formEvId = ev.id; }
    if (ev && ev.createdBy && recipients.indexOf(ev.createdBy)<0) recipients.push(ev.createdBy);
  }
  if (!recipients.length && form.createdBy) recipients.push(form.createdBy);
  recipients.forEach(function(to) {
    sendEmail({ to:to, subject:'\ud83d\udccb Nytt svar: '+form.title, html:html, department: _formDeptId, eventId: _formEvId, category: "form" }).catch(function(){});
  });
  res.json({ ok: true });
});

// Public form slideshow page
app.get("/form/:slug", function(req, res) {
  var form = readForms().find(function(f){ return f.slug===req.params.slug; });
  if (!form) return res.status(404).send("<h1>Skjema ikke funnet</h1>");
  var settings = getSettings();
  var y = (settings.colors && settings.colors.accent) || "#FFD100";
  var safeSiteName = escHtml(settings.siteName || "Event-Admin");
  var safeTitle    = escHtml(form.title);
  var formJson     = JSON.stringify({ id:form.id, slug:form.slug, title:form.title, outro:form.outro, slides:form.slides });

  res.setHeader("Content-Type","text/html;charset=utf-8");
  res.send('<!DOCTYPE html><html lang="no"><head>\n<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">\n<title>' + safeTitle + ' \u2013 ' + safeSiteName + '</title>\n<style>\n*{box-sizing:border-box;margin:0;padding:0}\n:root{--y:' + y + ';--g:#fff;--g2:#f5f5f5;--g3:#ddd;--text:#111;--text2:#555}\nbody{font-family:"Helvetica Neue",Arial,sans-serif;background:var(--g2);display:flex;align-items:center;justify-content:center;min-height:100vh;padding:0}\n#app{width:100%;max-width:600px;min-height:100vh;background:var(--g);display:flex;flex-direction:column}\n.form-input{width:100%;padding:14px 16px;font-size:1rem;border:2px solid var(--g3);border-radius:10px;background:var(--g);color:var(--text);outline:none;transition:border-color .15s;font-family:inherit}\n.form-input:focus{border-color:var(--y)}\n.opt-item{display:flex;align-items:center;gap:.85rem;padding:.85rem 1rem;border:2px solid var(--g3);border-radius:10px;cursor:pointer;margin-bottom:.5rem;transition:all .15s;background:var(--g)}\n.opt-item.sel{border-color:var(--y);background:rgba(255,209,0,.08)}\n.btn-next{padding:.75rem 1.75rem;border-radius:8px;border:none;background:var(--y);color:#111;font-size:.95rem;font-weight:800;cursor:pointer}\n.btn-back{padding:.75rem 1.25rem;border-radius:8px;border:2px solid var(--g3);background:var(--g);color:var(--text);font-size:.9rem;font-weight:600;cursor:pointer}\n@keyframes fi{from{opacity:0;transform:translateX(24px)}to{opacity:1;transform:none}}\n</style></head><body>\n<div id="app"><div id="root" style="flex:1;display:flex;flex-direction:column"></div></div>\n<script>\nvar FORM=' + formJson + ';\nvar ans={};\nvar cur=0;\nvar sls=FORM.slides||[];\nvar qsls=sls.filter(function(s){return s.type!=="info";});\n\nfunction esc(s){return String(s||"").replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;");}\n\nfunction render(){\n  var root=document.getElementById("root");\n  if(cur>=sls.length){root.innerHTML=\'<div style="flex:1;display:flex;flex-direction:column;align-items:center;justify-content:center;padding:2rem;text-align:center;min-height:100vh"><div style="font-size:4rem;margin-bottom:1rem">\ud83c\udf89</div><h2 style="font-size:1.5rem;font-weight:900;color:var(--text);margin-bottom:.75rem">\'+esc(FORM.outro||"Takk for ditt svar!")+"</h2><p style=\\"color:var(--text2)\\">Svaret ditt er registrert.</p></div>";return;}\n  var sl=sls[cur];\n  var qn=sls.slice(0,cur).filter(function(s){return s.type!=="info";}).length+1;\n  var pct=qsls.length?Math.round((qn-1)/qsls.length*100):0;\n  var isInfo=sl.type==="info";\n  var html="";\n  if(sl.image)html+=\'<div style="height:220px;flex-shrink:0;background:url(\'+JSON.stringify(sl.image)+\') center/cover no-repeat;position:relative"><div style="position:absolute;inset:0;background:linear-gradient(to bottom,transparent 40%,rgba(0,0,0,.5))"></div></div>\';\n  html+=\'<div style="height:4px;background:var(--g3)"><div style="height:100%;width:\'+pct+\'%;background:var(--y);transition:width .3s"></div></div>\';\n  html+=\'<div style="flex:1;overflow-y:auto;padding:1.75rem 1.5rem;animation:fi .2s;display:flex;flex-direction:column;gap:1rem">\';\n  if(!isInfo)html+=\'<div style="font-size:.72rem;color:var(--text2);font-weight:700;text-transform:uppercase;letter-spacing:.05em">Sp\u00f8rsm\u00e5l \'+qn+" av "+qsls.length+(sl.required?\' <span style="color:#ef4444">*</span>\':"")+"</div>";\n  html+=\'<h2 style="font-size:1.3rem;font-weight:900;color:var(--text);line-height:1.3">\'+esc(sl.title||"")+\'</h2>\';\n  if(sl.description)html+=\'<p style="font-size:.9rem;color:var(--text2);line-height:1.6">\'+esc(sl.description).replace(/\\n/g,"<br>")+\'</p>\';\n  if(!isInfo)html+=buildInput(sl);\n  html+=\'<div id="err" style="color:#ef4444;font-size:.82rem;display:none">Dette feltet er obligatorisk</div>\';\n  html+=\'</div>\';\n  html+=\'<div style="flex-shrink:0;padding:1rem 1.5rem;border-top:1px solid var(--g3);display:flex;align-items:center;justify-content:space-between;background:var(--g)">\';\n  html+=cur>0?\'<button class="btn-back" onclick="go(-1)">\u2190 Tilbake</button>\':\'<div></div>\';\n  html+=\'<button class="btn-next" onclick="go(1)">\'+( cur===sls.length-1?"\u2705 Send inn":"Neste \u2192")+\'</button>\';\n  html+=\'</div>\';\n  root.innerHTML=html;\n}\n\nfunction buildInput(sl){\n  var prev=ans[sl.id];\n  var sid=JSON.stringify(sl.id);\n  if(sl.type==="text"||sl.type==="email"||sl.type==="phone")return \'<input id="fi" class="form-input" type="\'+( sl.type==="email"?"email":sl.type==="phone"?"tel":"text")+\'" placeholder="\'+esc(sl.placeholder||"Ditt svar...")+\'" value="\'+esc(prev||"")+\'" oninput="ans[\'+sid+\']=this.value"/>\';\n  if(sl.type==="textarea")return \'<textarea id="fi" class="form-input" rows="4" placeholder="\'+esc(sl.placeholder||"")+\'" oninput="ans[\'+sid+\']=this.value">\'+esc(prev||"")+"</textarea>";\n  if(sl.type==="date")return \'<input id="fi" type="date" class="form-input" value="\'+esc(prev||"")+\'" oninput="ans[\'+sid+\']=this.value"/>\';\n  if(sl.type==="dropdown")return \'<select id="fi" class="form-input" onchange="ans[\'+sid+\']=this.value"><option value="">Velg...</option>\'+(sl.options||[]).map(function(o){return\'<option value="\'+esc(o)+\'" \'+(prev===o?"selected":"")+\'>\'+esc(o)+"</option>";}).join("")+"</select>";\n  if(sl.type==="radio")return(sl.options||[]).map(function(o,i){var sel=prev===o;return\'<div class="opt-item\'+(sel?" sel":"")+\'" onclick="selR(\'+sid+","+JSON.stringify(o)+","+i+","+(sl.options.length)+\')">\'+\'<div style="width:20px;height:20px;border-radius:50%;border:2px solid \'+(sel?"var(--y)":"var(--g3)")+\';display:flex;align-items:center;justify-content:center;flex-shrink:0" id="rb\'+i+\'"><div style="width:10px;height:10px;border-radius:50%;background:var(--y);display:\'+(sel?"block":"none")+\'" id="ri\'+i+\'"></div></div>\'+\'<span>\'+esc(o)+"</span></div>";}).join("");\n  if(sl.type==="checkbox"){var pa=Array.isArray(prev)?prev:[];return(sl.options||[]).map(function(o,i){var sel=pa.indexOf(o)>=0;return\'<div class="opt-item\'+(sel?" sel":"")+\'" onclick="selC(\'+sid+","+JSON.stringify(o)+","+i+\')">\'+\'<div style="width:20px;height:20px;border-radius:4px;border:2px solid \'+(sel?"var(--y)":"var(--g3)")+\';background:\'+(sel?"var(--y)":"transparent")+\';display:flex;align-items:center;justify-content:center;flex-shrink:0" id="cb\'+i+\'"><span style="color:#111;font-weight:900;font-size:.8rem;display:\'+(sel?"block":"none")+\'" id="ci\'+i+\'">\u2713</span></div>\'+\'<span>\'+esc(o)+"</span></div>";}).join("");}\n  if(sl.type==="scale"){var pa2=prev||0;return\'<div style="text-align:center"><div style="display:flex;justify-content:space-between;margin-bottom:1rem"><span style="font-size:.8rem;color:var(--text2)">\'+esc(sl.scaleLow||"Sv\u00e6rt uenig")+"</span><span style=\\"font-size:.8rem;color:var(--text2)\\">"+ esc(sl.scaleHigh||"Sv\u00e6rt enig")+"</span></div><div style=\\"display:flex;gap:.5rem;justify-content:center\\">"+ [1,2,3,4,5].map(function(n){var sel=pa2===n;return\'<button onclick="selS(\'+sid+","+n+\')" id="sc\'+n+\'" style="width:54px;height:54px;border-radius:50%;font-size:1.2rem;font-weight:700;border:2px solid \'+(sel?"var(--y)":"var(--g3)")+\';background:\'+(sel?"var(--y)":"var(--g)")+\';color:\'+(sel?"#111":"var(--text)")+\';cursor:pointer">\'+ n+"</button>";}).join("")+"</div></div>";}\n  return"";\n}\n\nfunction selR(sid,val,i,n){ans[sid]=val;for(var j=0;j<n;j++){var el=document.getElementById("rb"+j);var ri=document.getElementById("ri"+j);var oi=document.querySelector(\'.opt-item:nth-child(\'+(j+1)+\')\');if(el)el.style.borderColor=j===i?"var(--y)":"var(--g3)";if(ri)ri.style.display=j===i?"block":"none";}document.querySelectorAll(".opt-item").forEach(function(el,j){el.classList.toggle("sel",j===i);});}\nfunction selC(sid,val,i){if(!Array.isArray(ans[sid]))ans[sid]=[];var arr=ans[sid];var j=arr.indexOf(val);if(j>=0)arr.splice(j,1);else arr.push(val);var sel=arr.indexOf(val)>=0;var el=document.getElementById("cb"+i);if(el){el.style.borderColor=sel?"var(--y)":"var(--g3)";el.style.background=sel?"var(--y)":"transparent";}var ci=document.getElementById("ci"+i);if(ci)ci.style.display=sel?"block":"none";var oi=document.querySelectorAll(".opt-item")[i];if(oi)oi.classList.toggle("sel",sel);}\nfunction selS(sid,n){ans[sid]=n;[1,2,3,4,5].forEach(function(v){var el=document.getElementById("sc"+v);if(el){el.style.borderColor=v===n?"var(--y)":"var(--g3)";el.style.background=v===n?"var(--y)":"var(--g)";el.style.color=v===n?"#111":"var(--text)";}});}\n\nfunction go(dir){\n  if(dir===1){\n    var sl=sls[cur];\n    if(sl&&sl.required&&sl.type!=="info"){var a=ans[sl.id];if(!a||(Array.isArray(a)&&!a.length)||a===""){var err=document.getElementById("err");if(err)err.style.display="block";return;}}\n    if(cur===sls.length-1){submit();return;}\n  }\n  cur=Math.max(0,Math.min(sls.length,cur+dir));\n  render();\n}\n\nasync function submit(){\n  try{var r=await fetch("/api/forms/"+FORM.slug+"/submit",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({answers:ans})});if(r.ok){cur=sls.length;render();}else{alert("Noe gikk galt, pr\u00f8v igjen.");}}\n  catch(e){alert("Nettverksfeil, pr\u00f8v igjen.");}\n}\n\nrender();\n</script></body></html>');
});

// GET /api/deltagere \u2014 aggregated participant view
app.get("/api/deltagere", auth, managerOrAdmin, function(req, res) {
  var user   = req.session.user;
  var myAvds = getUserDepartments(user);
  var events = readJSON(EVENTS_FILE).filter(function(e) {
    if (user.role === "admin") return true;
    if (!myAvds.length) return false;
    return e.department && myAvds.includes(e.department);
  });

  var map = {};
  events.forEach(function(ev) {
    var evDate = ev.date ? new Date(ev.date) : null;
    var type   = ev.eventType || "stand";
    (ev.registrations || []).forEach(function(r) {
      if (r.anonymized) return;
      var key = (r.email || "").toLowerCase().trim();
      if (!key) return;
      if (!map[key]) {
        map[key] = { name:r.name||"", email:key, phone:r.phone||"",
          totalCount:0, checkedIn:0, lotteryWins:0,
          types:{}, lastEventDate:null, lastEventLabel:"", events:[] };
      }
      var d = map[key];
      if (r.name && r.name !== "[slettet]") d.name = r.name;
      d.totalCount++;
      if (r.checkedIn) d.checkedIn++;
      d.types[type] = (d.types[type]||0) + 1;
      if (!d.lastEventDate || (evDate && evDate > new Date(d.lastEventDate))) {
        d.lastEventDate  = ev.date;
        d.lastEventLabel = ev.title;
      }
      var wonLottery = !!(ev.lottery && ev.lottery.winners &&
        ev.lottery.winners.some(function(w){ return (w.email||"").toLowerCase()===key || w.regId===r.id; }));
      if (wonLottery) d.lotteryWins++;
      d.events.push({ evId:ev.id, evTitle:ev.title, evDate:ev.date, evType:type,
        checkedIn:!!r.checkedIn, checkedInAt:r.checkedInAt||null,
        lottery:wonLottery, pin:r.checkinPin||null });
    });
  });

  res.json(Object.values(map).sort(function(a,b){
    if (!a.lastEventDate) return 1;
    if (!b.lastEventDate) return -1;
    return new Date(b.lastEventDate) - new Date(a.lastEventDate);
  }));
});

app.get("/api/debug/event/:slug", auth, adminOnly, function(req, res) {
  const events = readJSON(EVENTS_FILE);
  const ev = events.find(function(e) {
    return e.slug === req.params.slug
      || e.id === req.params.slug
      || (e.title||'').toLowerCase().includes(req.params.slug.toLowerCase());
  });
  if (!ev) return res.status(404).json({ error: "Not found", search: req.params.slug });
  const settings    = getSettings();
  const dept        = (settings.departments||[]).find(function(d){ return d.id === ev.department; });
  const historyDays = dept && dept.historyDays ? parseInt(dept.historyDays) : 14;
  const now         = Date.now();
  const cutoff      = now - historyDays * 86400000;
  let endMs = null;
  if (ev.endDate) { const e=new Date(ev.endDate); e.setHours(23,59,59,999); endMs=e.getTime(); }
  else if (ev.date) { const e=new Date(ev.date); e.setHours(23,59,59,999); endMs=e.getTime(); }
  res.json({
    title: ev.title, slug: ev.slug, date: ev.date, endDate: ev.endDate,
    departmentName: dept ? dept.name : ev.department,
    subgroup: ev.subgroup,
    isPublic: ev.isPublic, isPublicSetByUser: ev.isPublicSetByUser,
    hideFromList: ev.hideFromList, isInternal: ev.isInternal,
    isPublished: ev.isPublished, isFinalized: ev.isFinalized,
    endMs: endMs ? new Date(endMs).toISOString() : null,
    cutoff: new Date(cutoff).toISOString(),
    passesDateFilter: endMs ? endMs >= cutoff : true,
    wouldShowOnDeptPage: !ev.hideFromList && !ev.isInternal && (endMs ? endMs >= cutoff : true),
    wouldShowOnEventPage: ev.isPublic !== false,
  });
});

app.get("/api/stats/visits", auth, managerOrAdmin, function(req, res) {
  try {
    const me   = req.session.user;
    const p    = buildPermissions(me, getSettings());
    const evId = req.query.evId || null;
    const days = Math.min(parseInt(req.query.days) || 30, 365);
    const since = new Date(Date.now() - days * 86400000).toISOString();

    const allVisits = readJSON(VISITS_FILE);
    const events    = readJSON(EVENTS_FILE);

    // Filter to own dept events if not global admin
    const allowedEvIds = p.isAdmin
      ? null
      : new Set(events.filter(function(e) {
          return e.department === p.myDepartment || e.createdBy === me.name;
        }).map(function(e) { return e.id; }));

    const visits = allVisits.filter(function(v) {
      if (v.ts < since) return false;
      if (allowedEvIds && !allowedEvIds.has(v.evId)) return false;
      if (evId && v.evId !== evId) return false;
      return true;
    });

    // Group by day \u2014 total visits AND unique visitors
    const byDay = {};
    const uniqueByDay = {};
    visits.forEach(function(v) {
      const day = v.ts.slice(0, 10);
      byDay[day] = (byDay[day] || 0) + 1;
      // Unique: count distinct vid per day
      if (v.vid) {
        if (!uniqueByDay[day]) uniqueByDay[day] = new Set();
        uniqueByDay[day].add(v.vid);
      }
    });
    // Convert Sets to counts
    const uniqueByDayCount = {};
    Object.keys(uniqueByDay).forEach(function(day) {
      uniqueByDayCount[day] = uniqueByDay[day].size;
    });

    // Total unique visitors in period
    const allVids = new Set(visits.filter(function(v){ return v.vid; }).map(function(v){ return v.vid; }));
    const totalUnique = allVids.size;

    // Group by event \u2014 only count visits that have an evId
    const byEvent = {};
    const uniqueByEvent = {};
    visits.forEach(function(v) {
      if (!v.evId) return; // skip dept-level visits \u2014 they have deptId not evId
      byEvent[v.evId] = (byEvent[v.evId] || 0) + 1;
      if (v.vid) {
        if (!uniqueByEvent[v.evId]) uniqueByEvent[v.evId] = new Set();
        uniqueByEvent[v.evId].add(v.vid);
      }
    });

    // Sparkline data per event (last 14 days)
    const sparkSince = new Date(Date.now() - 14 * 86400000).toISOString();
    const sparkByEvent = {};
    allVisits.filter(function(v) { return v.ts >= sparkSince; }).forEach(function(v) {
      if (allowedEvIds && !allowedEvIds.has(v.evId)) return;
      if (!sparkByEvent[v.evId]) sparkByEvent[v.evId] = {};
      const day = v.ts.slice(0, 10);
      sparkByEvent[v.evId][day] = (sparkByEvent[v.evId][day] || 0) + 1;
    });

    // Enrich with event titles
    const eventMap = {};
    events.forEach(function(e) { eventMap[e.id] = e; });

    const topEvents = Object.entries(byEvent)
      .map(function(entry) {
        const ev = eventMap[entry[0]] || {};
        return {
          evId:              entry[0],
          title:             ev.title || entry[0],
          slug:              ev.slug  || null,
          unique:            uniqueByEvent[entry[0]] ? uniqueByEvent[entry[0]].size : 0,
          eventType:         ev.eventType || 'stand',
          date:              ev.date || null,
          registrationCount: (ev.registrations || []).filter(function(r) { return !r.anonymized; }).length,
          count:             entry[1],
        };
      })
      .sort(function(a, b) { return b.count - a.count; })
      .slice(0, 20);

    res.json({ total: visits.length, totalUnique, byDay, uniqueByDay: uniqueByDayCount, topEvents, sparkByEvent, days });
  } catch(e) {
    console.error("[/api/stats/visits]", e);
    res.status(500).json({ error: "Internal error: " + e.message });
  }
});

app.delete("/api/email-log", auth, adminOnly, function(req, res) {
  writeJSON(EMAIL_LOG_FILE, []);
  res.json({ ok: true });
});

app.post("/api/email-log/test", auth, adminOnly, async function(req, res) {
  const to = (req.body.to || "").trim();
  if (!to) return res.status(400).json({ error: st("email_missing", req) });
  const s = getSettings();

  // Test SMTP directly \u2013 bypasses emailEnabled so we can diagnose problems
  console.log("[email-test] Attempting to send test to:", to);
  console.log("[email-test] SMTP_HOST:", process.env.SMTP_HOST || "(ikke satt)");
  console.log("[email-test] SMTP_USER:", process.env.SMTP_USER || "(ikke satt)");
  console.log("[email-test] SMTP_FROM:", process.env.SMTP_FROM || "(ikke satt)");

  const transport = getTransporter();
  if (!transport) {
    console.error("[email-test] Ingen transport \u2013 SMTP ikke konfigurert");
    return res.status(500).json({
      ok: false,
      error: st("smtp_not_configured_portainer", req)
    });
  }

  const fromAddr = process.env.SMTP_FROM || s.emailFrom || ("noreply@" + (s.eventDomain || DOMAIN));
  const siteName = s.siteName || "Event-Admin";
  const sentAt   = new Date().toLocaleString("nb-NO");

  try {
    const info = await transport.sendMail({
      from:    (s.emailFromName || siteName) + " <" + fromAddr + ">",
      to,
      subject: "\u2705 Test-e-post fra " + siteName,
      html: "<div style=\"font-family:sans-serif;padding:2rem;max-width:480px;color:#1a1a1a\">" +
            "<div style=\"background:#FFD100;padding:1rem 1.5rem;border-radius:8px 8px 0 0\">" +
            "<strong>" + siteName + "</strong></div>" +
            "<div style=\"background:var(--ev-surface);padding:1.5rem;border-radius:0 0 8px 8px;border:1px solid #e0e0e0\">" +
            "<h2 style=\"margin-top:0\">SMTP fungerer! \ud83c\udf89</h2>" +
            "<p>Denne e-posten bekrefter at konfigurasjonen er korrekt.</p>" +
            "<table style=\"font-size:.85rem;color:#555\"><tr><td><strong>Til:&nbsp;</strong></td><td>" + to + "</td></tr>" +
            "<tr><td><strong>Fra:&nbsp;</strong></td><td>" + fromAddr + "</td></tr>" +
            "<tr><td><strong>Sendt:&nbsp;</strong></td><td>" + sentAt + "</td></tr></table>" +
            "</div></div>",
      text: "SMTP fungerer! Sendt fra " + siteName + " til " + to + " kl. " + sentAt,
    });
    writeEmailLog({ status: "sent", to, subject: "\u2705 Test-e-post fra " + siteName, msgId: info.messageId });
    res.json({ ok: true, to, id: info.messageId });
  } catch(e) {
    console.error("[email-test] Sendingsfeil:", e.message);
    writeEmailLog({ status: "error", to, subject: "\u2705 Test-e-post fra " + siteName, error: e.message });
    res.status(500).json({ ok: false, error: e.message });
  }
});

// \u2500\u2500 Glemt password \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500
app.post("/api/forgot-password", rateLimit(3, 900000), function(req, res) { // 3 per 15min
  const email = (req.body.email || "").toLowerCase().trim();
  if (!email) return res.json({ ok: true }); // Always OK to avoid enumeration
  const users = readJSON(USERS_FILE);
  const user  = users.find(function(u) { return u.email === email; });
  if (!user) return res.json({ ok: true });
  const tmp = require("crypto").randomBytes(6).toString("base64").replace(/[^a-zA-Z0-9]/g,"").slice(0,10);
  const hash = bcrypt.hashSync(tmp, 10);
  user.hash = hash;
  delete user.password; // remove stale field if present
  delete user.resetToken;
  delete user.resetTokenExpiry;
  writeJSON(USERS_FILE, users);
  const s    = getSettings();
  const name = user.name || user.email;
  const adminUrl = "https://admin." + (s.eventDomain || DOMAIN);
  const subject  = "\ud83d\udd11 Nytt midlertidig passord \u2013 " + (s.siteName || "Event-Admin");
  const html = `<div style="font-family:sans-serif;max-width:520px;margin:0 auto">
    <div style="background:#FFD100;padding:1rem 1.5rem;border-radius:8px 8px 0 0">
      <strong>${s.siteName || "Event-Admin"}</strong></div>
    <div style="background:var(--ev-surface);padding:1.5rem;border-radius:0 0 8px 8px;border:1px solid #e0e0e0">
      <p>Hei ${name}!</p>
      <p>Ditt midlertidige passord er: <strong style="font-size:1.2rem;letter-spacing:.05em">${tmp}</strong></p>
      <p><a href="${adminUrl}" style="background:#FFD100;color:#1a1a1a;padding:.6rem 1.25rem;border-radius:6px;text-decoration:none;font-weight:700">Logg inn \u2192</a></p>
      <p style="color:#999;font-size:.8rem">Bytt passord under Innstillinger etter innlogging.</p>
    </div></div>`;
  const text = `Hei ${name}!\n\nMidlertidig passord: ${tmp}\nLogg inn: ${adminUrl}\n\nBytt passord etter innlogging.`;
  sendEmail({ to: email, subject, html, text, category: "auth" }).catch(function(e) { console.error('[email] catch:', e && e.message); });
  res.json({ ok: true });
});

