app.put("/api/camera-names", auth, managerOrAdmin, function(req, res) {
  const s = getSettings();
  const incoming = (req.body && req.body.cameraNames) || {};
  const clean = {};
  Object.keys(incoming).forEach(function(key) {
    const k = String(key).replace(/[^a-z0-9_-]/gi, "").slice(0, 40);
    const v = String(incoming[key] || "").slice(0, 60).trim();
    if (k && v) clean[k] = v;
  });
  s.cameraNames = clean;
  saveSettings(s);
  res.json({ ok: true, cameraNames: clean });
});

// Resolve a recording filename to its camera key + friendly name
function _cameraNameFor(fileName) {
  const key = (String(fileName).split(/[-_.]/)[0]) || "kamera";
  const names = (getSettings().cameraNames) || {};
  return { key: key, name: names[key] || key };
}


