// \u2500\u2500 Spond integration \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500
// Uses the unofficial Spond API (reverse-engineered, may change without notice)
const SPOND_API = "https://api.spond.com/core/v1";

async function spondRequest(method, path, token, body) {
  var https = require("https");
  var url = require("url");
  return new Promise(function(resolve, reject) {
    var parsed = url.parse(SPOND_API + path);
    var data = body ? JSON.stringify(body) : null;
    var headers = {
      "Content-Type": "application/json",
      "Accept": "application/json",
      "Authorization": "Bearer " + token,
    };
    if (data) headers["Content-Length"] = Buffer.byteLength(data);
    var opts = { hostname: parsed.hostname, path: parsed.path, method: method, headers: headers };
    var req = https.request(opts, function(r) {
      var chunks = [];
      r.on("data", function(c) { chunks.push(c); });
      r.on("end", function() {
        try { resolve({ status: r.statusCode, body: JSON.parse(Buffer.concat(chunks).toString()) }); }
        catch(e) { resolve({ status: r.statusCode, body: {} }); }
      });
    });
    req.on("error", reject);
    if (data) req.write(data);
    req.end();
  });
}

async function spondLogin(email, password) {
  var https = require("https");
  return new Promise(function(resolve, reject) {
    var data = JSON.stringify({ email: email, password: password });
    var opts = {
      hostname: "api.spond.com",
      path: "/core/v1/login",
      method: "POST",
      headers: { "Content-Type": "application/json", "Content-Length": Buffer.byteLength(data) }
    };
    var req = https.request(opts, function(r) {
      var chunks = [];
      r.on("data", function(c) { chunks.push(c); });
      r.on("end", function() {
        try {
          var parsed = JSON.parse(Buffer.concat(chunks).toString());
          resolve({ status: r.statusCode, token: parsed.loginToken || parsed.token || null, body: parsed });
        } catch(e) { resolve({ status: r.statusCode, token: null, body: {} }); }
      });
    });
    req.on("error", reject);
    req.write(data);
    req.end();
  });
}

// POST /api/spond/sync  \u2013 sync all events to Spond, skip dates with conflicts
app.post("/api/spond/sync", auth, managerOrAdmin, async function(req, res) {
  var settings = getSettings();
  var deptId = (req.body && req.body.deptId) || req.query.deptId || null;
  if (deptId && !hasDeptAccess(req.session.user, deptId)) {
    return res.status(403).json({ error: st("no_access_department", req) });
  }
  if (!deptId && req.session.user.role !== "admin") {
    return res.status(403).json({ error: st("admin_only", req) });
  }
  // Department account first, global as fallback
  var spond = deptId ? (getDeptConnections(deptId).spond || {}) : {};
  if (!spond.email || !spond.password || !spond.groupId) spond = settings.spond || {};
  if (!spond.email || !spond.password || !spond.groupId) {
    return res.status(400).json({ error: st("spond_settings_missing", req) });
  }

  // 1. Login to Spond
  var login;
  try { login = await spondLogin(spond.email, spond.password); }
  catch(e) { return res.status(502).json({ error: st("spond_unreachable_prefix", req) + e.message }); }
  if (!login.token) {
    return res.status(401).json({ error: st("spond_login_failed", req) });
  }
  var token = login.token;

  // 2. Fetch existing Spond events for this group (next 12 months)
  var now = new Date();
  var future = new Date(now); future.setFullYear(future.getFullYear() + 1);
  var spondEventsRes;
  try {
    spondEventsRes = await spondRequest("GET",
      "/sponds?groupId=" + encodeURIComponent(spond.groupId)
      + "&minEndTimestamp=" + now.toISOString()
      + "&maxStartTimestamp=" + future.toISOString()
      + "&scheduled=true&max=100",
      token);
  } catch(e) { return res.status(502).json({ error: st("spond_fetch_failed_prefix", req) + e.message }); }

  var spondEvents = Array.isArray(spondEventsRes.body) ? spondEventsRes.body : [];

  // Build a set of dates that already have Spond events (date string YYYY-MM-DD)
  var spondDates = new Set();
  var spondByDate = {}; // date -> array of spond event headings for conflict reporting
  spondEvents.forEach(function(se) {
    var d = (se.startTimestamp || "").substring(0, 10);
    if (d) {
      spondDates.add(d);
      if (!spondByDate[d]) spondByDate[d] = [];
      spondByDate[d].push(se.heading || "Ukjent");
    }
    // Also mark end date if multi-day
    var ed = (se.endTimestamp || "").substring(0, 10);
    if (ed && ed !== d) {
      spondDates.add(ed);
      if (!spondByDate[ed]) spondByDate[ed] = [];
      spondByDate[ed].push((se.heading || "Ukjent") + " (endDate)");
    }
  });

  // 3. Get our local events (upcoming only)
  var localEvents = readJSON(EVENTS_FILE).filter(function(ev) {
    if (!ev.date || ev.hideFromList) return false;
    // A department syncs only its own events into its own Spond group
    if (deptId && ev.department !== deptId) return false;
    var evDate = new Date(ev.date);
    return evDate >= now;
  });

  var synced = [], skipped = [], conflicts = [], errors = [];

  for (var i = 0; i < localEvents.length; i++) {
    var ev = localEvents[i];
    var evDateStr = (ev.date || "").substring(0, 10);
    if (!evDateStr) continue;

    // Check if already synced to Spond (we store spondId on the event)
    var alreadySynced = !!ev.spondId;
    if (alreadySynced) {
      // Update existing Spond event
      try {
        var startTs = new Date(ev.date + (ev.startTime ? "T" + ev.startTime : "T10:00")).toISOString();
        var endTs   = new Date((ev.endDate || ev.date) + (ev.endTime ? "T" + ev.endTime : "T16:00")).toISOString();
        await spondRequest("PUT", "/sponds/" + ev.spondId, token, {
          heading: ev.title,
          description: ev.description || "",
          startTimestamp: startTs,
          endTimestamp: endTs,
          location: ev.location ? { feature: ev.location } : undefined,
        });
        synced.push({ id: ev.id, title: ev.title, date: evDateStr, action: "updated" });
      } catch(e) {
        errors.push({ id: ev.id, title: ev.title, date: evDateStr, error: e.message });
      }
      continue;
    }

    // New event: check for date conflict
    if (spondDates.has(evDateStr)) {
      conflicts.push({
        id: ev.id, title: ev.title, date: evDateStr,
        conflictsWith: spondByDate[evDateStr] || []
      });
      skipped.push({ id: ev.id, title: ev.title, date: evDateStr, reason: "Dato opptatt i Spond" });
      continue;
    }

    // Create new Spond event
    try {
      var startTs2 = new Date(ev.date + (ev.startTime ? "T" + ev.startTime : "T10:00")).toISOString();
      var endTs2   = new Date((ev.endDate || ev.date) + (ev.endTime ? "T" + ev.endTime : "T16:00")).toISOString();
      var payload = {
        heading: ev.title,
        description: ev.description || "",
        startTimestamp: startTs2,
        endTimestamp: endTs2,
        groupId: spond.groupId,
        location: ev.location ? { feature: ev.location } : undefined,
        rsvpDate: startTs2,
        commentsDisabled: false,
        hidden: false,
        type: "EVENT",
      };
      var createRes = await spondRequest("POST", "/sponds", token, payload);
      if (createRes.status === 200 || createRes.status === 201) {
        var spondId = createRes.body.id || createRes.body.uid;
        // Store spondId on the local event for future updates
        if (spondId) {
          var allEvs = readJSON(EVENTS_FILE);
          var idx = allEvs.findIndex(function(e) { return e.id === ev.id; });
          if (idx >= 0) { allEvs[idx].spondId = spondId; writeJSON(EVENTS_FILE, allEvs); }
        }
        synced.push({ id: ev.id, title: ev.title, date: evDateStr, action: "created", spondId: spondId });
        spondDates.add(evDateStr); // prevent double-booking if two local events share a date
      } else {
        errors.push({ id: ev.id, title: ev.title, date: evDateStr, error: "Spond svarte: " + createRes.status });
      }
    } catch(e) {
      errors.push({ id: ev.id, title: ev.title, date: evDateStr, error: e.message });
    }
  }

  res.json({ synced, skipped, conflicts, errors, spondEventCount: spondEvents.length });
});

