// \u2500\u2500 department API \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500
function slugify(str) {
  return str.toLowerCase()
    .replace(/\u00e6/g,"ae").replace(/\u00f8/g,"o").replace(/\u00e5/g,"a")
    .replace(/[^a-z0-9]+/g,"-").replace(/(^-|-$)/g,"");
}

