// \u2500\u2500 Department directory \u2014 contact info + managers, for cross-department
// collaboration. Available to any manager (not just admins): the whole
// point is letting managers find who to reach out to at other departments.
app.get("/api/departments/directory", auth, managerOrAdmin, function(req, res) {
  const depts = getSettings().departments || [];
  const users = readJSON(USERS_FILE);

  const directory = depts.map(function(d) {
    const managers = users
      .filter(function(u) {
        return getAccessList(u).some(function(a) {
          return a.department === d.id && (a.role === "department_manager" || a.role === "deptManager" || a.role === "dept_manager");
        });
      })
      .map(function(u) { return { name: u.name || u.email, email: u.email }; });

    return {
      id: d.id,
      name: d.displayName || d.name,
      contactEmail: d.contactEmail || null,
      phone: d.phone || null,
      website: d.website || null,
      address: d.address || null,
      managers: managers,
    };
  });

  directory.sort(function(a, b) { return (a.name || "").localeCompare(b.name || "", "nb"); });
  res.json(directory);
});

app.post("/api/departments", auth, adminOnly, function(req, res) {
  const deptName    = sanitizeInput((req.body.name || "").trim());
  const customSlug  = (req.body.customSlug || "").trim().toLowerCase().replace(/[^a-z0-9-]/g, '') || null;
  const displayName = sanitizeInput((req.body.displayName || "").trim()) || null;
  if (!deptName) return res.status(400).json({ error: "Name is required" });
  const s = getSettings();
  if (!s.departments) s.departments = [];
  if (s.departments.find(function(a) { return a.name.toLowerCase() === deptName.toLowerCase(); }))
    return res.status(409).json({ error: deptWordCap() + " finnes allerede" });
  const slug = customSlug || slugify(deptName);
  if (s.departments.find(function(a) { return a.slug === slug; }))
    return res.status(409).json({ error: "Subdomenet '" + slug + "' er allerede i bruk" });
  s.departments.push({
    id:          uuid(),
    name:        deptName,
    slug:        slug,
    displayName: displayName,
    subgroups:   []
  });
  saveSettings(s);
  broadcastEventUpdate(null);
  res.json(s.departments);
});

// \u2500\u2500 Department appearance \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500
// PUT /api/departments/:id/settings \u2014 update department-level config fields
// PUT /api/departments/:id/member-count \u2014 dedicated endpoint for the manual
// member-count "Oppdater" button. Unlike the general settings save, this one
// archives the previous value into memberCountHistory before overwriting it,
// so the public department page can show a historic trend.
app.put("/api/departments/:id/member-count", auth, managerOrAdmin, function(req, res) {
  var s = getSettings();
  var depts = s.departments || [];
  var idx = depts.findIndex(function(d) { return d.id === req.params.id; });
  if (idx < 0) return res.status(404).json({ error: "Department not found" });

  var newCount = parseInt(req.body.count, 10);
  if (isNaN(newCount) || newCount < 0) return res.status(400).json({ error: st("invalid_member_count", req) });

  var dept = depts[idx];
  var hadManualValue = dept.memberCount != null && dept.memberCount !== "";
  var prevCount = hadManualValue
    ? (parseInt(dept.memberCount, 10) || 0)
    : (readJSON(MEMBERS_FILE) || []).filter(function(m) { return m.department === dept.id; }).length;

  if (!Array.isArray(dept.memberCountHistory)) dept.memberCountHistory = [];
  // Only archive a history point if a manual value was already on record \u2014
  // otherwise the "previous" number is just the auto-count fallback, not a
  // real tracked data point, and would create a misleading first entry.
  if (hadManualValue) {
    dept.memberCountHistory.push({ date: new Date().toISOString(), count: prevCount });
    if (dept.memberCountHistory.length > 200) dept.memberCountHistory = dept.memberCountHistory.slice(-200);
  }
  dept.memberCount = newCount;
  dept.memberCountUpdatedAt = new Date().toISOString();
  depts[idx] = dept;
  s.departments = depts;
  saveSettings(s);
  res.json({ ok: true, memberCount: newCount, previous: prevCount, updatedAt: dept.memberCountUpdatedAt, history: dept.memberCountHistory });
});

// Auto-tracking for departments that DON'T have a manual member count set.
// A manually-entered total (e.g. the real NAF membership figure) always wins
// and is never touched here \u2014 this only tracks the *live* roster count
// (Folk \u2192 Medlemmer) over time for departments still relying on that
// fallback, so the public graph has data even before anyone sets a manual
// number. Call after any change to the real member list (import/delete).
function syncDeptMemberCountFromRoster(deptId) {
  if (!deptId) return; // e.g. admin-level imports aren't tied to one department
  var s = getSettings();
  var depts = s.departments || [];
  var idx = depts.findIndex(function(d) { return d.id === deptId; });
  if (idx < 0) return;
  var dept = depts[idx];

  // A manual override always takes priority \u2014 never let a roster change
  // clobber the real, deliberately-entered number.
  if (dept.memberCount != null && dept.memberCount !== "") return;

  var liveCount = (readJSON(MEMBERS_FILE) || []).filter(function(m) { return m.department === deptId; }).length;
  if (!Array.isArray(dept.memberCountHistory)) dept.memberCountHistory = [];
  var lastEntry = dept.memberCountHistory[dept.memberCountHistory.length - 1];
  var lastKnown = lastEntry ? lastEntry.count : null;
  if (lastKnown === liveCount) return; // no real change to log

  // Archive the previous known value; if this is the very first time we've
  // observed this department's roster, just establish a baseline instead.
  dept.memberCountHistory.push({ date: new Date().toISOString(), count: (lastKnown != null ? lastKnown : liveCount) });
  if (dept.memberCountHistory.length > 200) dept.memberCountHistory = dept.memberCountHistory.slice(-200);
  dept.memberCountUpdatedAt = new Date().toISOString();
  depts[idx] = dept;
  s.departments = depts;
  saveSettings(s);
}

app.put("/api/departments/:id/settings", auth, managerOrAdmin, function(req, res) {
  var s    = getSettings();
  var depts = s.departments || [];
  var idx  = depts.findIndex(function(d) { return d.id === req.params.id; });
  if (idx < 0) return res.status(404).json({ error: "Department not found" });

  // Whitelist of per-dept config fields
  var allowed = ["historyDays", "showEventTypes", "showSubgroupFilter", "showCountdown", "accountLink", "accountLabel", "bannerText", "bannerUntil"];
  allowed.forEach(function(key) {
    if (req.body[key] !== undefined) depts[idx][key] = req.body[key];
  });

  // About page fields
  var aboutFields = ["about", "mission", "phone", "website", "address", "plans"];
  aboutFields.forEach(function(key) {
    if (req.body[key] !== undefined) depts[idx][key] = (req.body[key] || "").trim() || null;
  });

  // Roles \u2014 array of { title, name, email, phone }
  if (req.body.roles !== undefined) {
    try { depts[idx].roles = JSON.parse(req.body.roles); } catch(e) {}
  }

  saveSettings(s);
  res.json(depts[idx]);
});

app.put("/api/departments/:id/appearance", auth, function(req, res) {
  const u = req.session.user;
  const s = getSettings();
  const depts = s.departments || [];
  const idx = depts.findIndex(function(d) { return d.id === req.params.id; });
  if (idx < 0) return res.status(404).json({ error: "Department not found" });

  // Allow admin, department manager, or group manager of this dept
  if (u.role !== "admin") {
    const al = getAccessList(readJSON(USERS_FILE).find(function(x){ return x.id === u.id; }) || {});
    const hasAccess = al.some(function(a) {
      return a.department === req.params.id &&
        (a.role === "department_manager" || a.role === "deptManager" ||
         a.role === "group_manager" || a.role === "gruppeansvarlig");
    });
    if (!hasAccess) return res.status(403).json({ error: st("access_denied", req) });
  }

  const app = req.body || {};
  const globalPalette = (getSettings().colors && getSettings().colors.palette) || [];

  // Validate accent \u2014 must be from global palette (or null to use global accent)
  let accent = (app.accent || "").trim() || null;
  if (accent && globalPalette.length > 0) {
    const normalized = accent.toLowerCase();
    if (!globalPalette.map(function(c){ return c.toLowerCase(); }).includes(normalized)) {
      // Not in palette \u2014 reject and use closest or null
      accent = null;
    }
  }

  var validThemes = ["dark","light"];
  depts[idx].appearance = {
    accent:       accent,
    theme:        validThemes.includes(app.theme)        ? app.theme        : "dark",
    themeDept:    validThemes.includes(app.themeDept)    ? app.themeDept    : null,
    themeEvent:   validThemes.includes(app.themeEvent)   ? app.themeEvent   : null,
    themeTV:      validThemes.includes(app.themeTV)      ? app.themeTV      : null,
    themeDisplay: validThemes.includes(app.themeDisplay) ? app.themeDisplay : null,
    logo:         (app.logo || "").trim() || null,
  };
  if (app.displayName !== undefined)
    depts[idx].displayName = (app.displayName || "").trim() || null;
  if (app.alias !== undefined && app.alias !== null) {
    const newSlug = (app.alias || "").trim().toLowerCase().replace(/[^a-z0-9-]/g, '');
    if (newSlug) {
      // Check uniqueness
      const conflict = depts.find(function(d, di) { return di !== idx && d.slug === newSlug; });
      if (conflict) return res.status(409).json({ error: "Subdomenet '" + newSlug + "' er allerede i bruk av " + conflict.name });
      depts[idx].slug = newSlug;
    }
  }
  if (app.contactEmail !== undefined)
    depts[idx].contactEmail = (app.contactEmail || "").trim().toLowerCase() || null;
  if (app.publicColors && typeof app.publicColors === 'object')
    depts[idx].publicColors = app.publicColors;
  s.departments = depts;
  saveSettings(s);
  res.json({ ok: true, appearance: depts[idx].appearance });
});

app.delete("/api/departments/:id", auth, managerOrAdmin, function(req, res) {
  const s = getSettings();
  s.departments = (s.departments || []).filter(function(a) { return a.id !== req.params.id; });
  saveSettings(s);
  broadcastEventUpdate(null);
  res.json(s.departments);
});

// \u2500\u2500 Undergrupper API \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500
// Department manager can administer subgroups in their own department
function ugGuard(req, res, next) {
  const u = req.session.user;
  if (!u) return res.status(401).json({ error: st("not_logged_in", req) });
  if (u.role === "admin") return next();
  var myAccessList = getAccessList(readJSON(USERS_FILE).find(function(x){ return x.id === u.id; }) || {});
  var harAvdTilgang = myAccessList.some(function(t){
    return t.department === req.params.deptId && (t.role === "department_manager" || t.role === "deptManager" || t.role === "dept_manager");
  });
  if (harAvdTilgang) return next();
  res.status(403).json({ error: st("access_denied", req) });
}

// Any access-list entry for a department (department manager, subgroup
// manager, event manager, etc.) is enough to see/manage that department's
// TV screens and guestbook media \u2014 this is department-wide content, not
// something gated to full department managers only. Used both as a
// middleware (for routes with :deptId in the URL) and as a plain function
// (for routes that look a record up by :id first and need to check the
// department it belongs to).
function hasDeptAccess(user, deptId) {
  if (!user) return false;
  if (user.role === "admin") return true;
  if (!deptId) return false;
  const acc = getAccessList(readJSON(USERS_FILE).find(function(x){ return x.id === user.id; }) || {});
  return acc.some(function(a) { return a.department === deptId; });
}
function deptGuard(req, res, next) {
  const u = req.session.user;
  if (!u) return res.status(401).json({ error: st("not_logged_in", req) });
  if (hasDeptAccess(u, req.params.deptId)) return next();
  res.status(403).json({ error: st("no_access_department", req) });
}

// \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550
// Per-department connections (email / Spond / Facebook)
// ------------------------------------------------------------------
// Departments run their own accounts. Each department stores its own
// connection config under dept.connections; anything not configured
// falls back to the global settings, so existing installs keep working.
//
// Credentials never leave the server. Reads return "is it configured"
// flags only, and the whole connections block is stripped out of
// GET /api/settings. Department managers may manage their own
// department; admins may manage any.
// \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550

function getDept(deptId) {
  return (getSettings().departments || []).find(function(d) { return d.id === deptId; }) || null;
}

function getDeptConnections(deptId) {
  const d = getDept(deptId);
  const c = (d && d.connections) || {};
  return {
    email:    c.email    || {},
    spond:    c.spond    || {},
    facebook: c.facebook || {},
  };
}

// What the browser is allowed to see: never a secret, only whether one is set.
function maskedConnections(deptId) {
  return maskConnectionsObj(getDeptConnections(deptId));
}

// NOTE: getSettings() reads SETTINGS_FILE straight from disk while writeJSON
// buffers writes until a setImmediate flush, so a read directly after a save
// returns stale data. Always mask the object we just wrote rather than
// re-reading it.
function maskConnectionsObj(conn) {
  const c    = conn || {};
  const e    = c.email || {}, sp = c.spond || {}, fb = c.facebook || {};
  const smtp = e.smtp || {};
  return {
    email: {
      fromAddress: e.fromAddress || "",
      replyTo:     e.replyTo     || "",
      smtp: {
        host:    smtp.host || "",
        port:    smtp.port || 587,
        secure:  !!smtp.secure,
        user:    smtp.user || "",
        passSet: !!smtp.pass,
      },
    },
    spond:    { email: sp.email || "", groupId: sp.groupId || "", passwordSet: !!sp.password },
    facebook: { pageId: fb.pageId || "", autoPost: !!fb.autoPost, tokenSet: !!fb.pageToken },
  };
}

// Writes merge into what is already stored. An omitted or empty secret
// leaves the stored one alone; an explicit null clears it.
function mergeSecret(current, incoming) {
  if (incoming === null) return "";
  if (incoming === undefined || incoming === "") return current || "";
  return String(incoming).slice(0, 400);
}

function saveDeptConnections(deptId, body) {
  const s    = getSettings();
  const idx  = (s.departments || []).findIndex(function(d) { return d.id === deptId; });
  if (idx < 0) return null;
  const dept = s.departments[idx];
  const cur  = dept.connections || {};
  const curE = cur.email || {}, curSmtp = curE.smtp || {}, curSp = cur.spond || {}, curFb = cur.facebook || {};
  const b    = body || {};
  const e    = b.email || {}, smtp = e.smtp || {}, sp = b.spond || {}, fb = b.facebook || {};

  dept.connections = {
    email: {
      fromAddress: (e.fromAddress !== undefined ? String(e.fromAddress || "").trim().slice(0, 120) : (curE.fromAddress || "")),
      replyTo:     (e.replyTo     !== undefined ? String(e.replyTo     || "").trim().slice(0, 120) : (curE.replyTo     || "")),
      smtp: {
        host:   (smtp.host !== undefined ? String(smtp.host || "").trim().slice(0, 120) : (curSmtp.host || "")),
        port:   (smtp.port !== undefined ? (parseInt(smtp.port, 10) || 587)             : (curSmtp.port || 587)),
        secure: (smtp.secure !== undefined ? !!smtp.secure                              : !!curSmtp.secure),
        user:   (smtp.user !== undefined ? String(smtp.user || "").trim().slice(0, 120) : (curSmtp.user || "")),
        pass:   mergeSecret(curSmtp.pass, smtp.pass),
      },
    },
    spond: {
      email:    (sp.email   !== undefined ? String(sp.email   || "").trim().slice(0, 120) : (curSp.email   || "")),
      groupId:  (sp.groupId !== undefined ? String(sp.groupId || "").trim().slice(0, 80)  : (curSp.groupId || "")),
      password: mergeSecret(curSp.password, sp.password),
    },
    facebook: {
      pageId:    (fb.pageId   !== undefined ? String(fb.pageId || "").trim().replace(/[^0-9]/g, "").slice(0, 32) : (curFb.pageId || "")),
      autoPost:  (fb.autoPost !== undefined ? !!fb.autoPost : !!curFb.autoPost),
      pageToken: mergeSecret(curFb.pageToken, fb.pageToken),
    },
  };
  saveSettings(s);
  invalidateDeptTransporter(deptId);
  return maskConnectionsObj(dept.connections);
}

// Access: admins anywhere, department managers on their own department.
function connectionsGuard(req, res, next) {
  const u = req.session.user;
  if (!u) return res.status(401).json({ error: st("not_logged_in", req) });
  if (!getDept(req.params.id)) return res.status(404).json({ error: st("department_missing", req) });
  if (hasDeptAccess(u, req.params.id)) return next();
  res.status(403).json({ error: st("no_access_department", req) });
}

app.get("/api/departments/:id/connections", auth, connectionsGuard, function(req, res) {
  const s = getSettings();
  res.json({
    connections: maskedConnections(req.params.id),
    fallback: {
      // shown so a manager can see what happens when nothing is set here
      emailFrom:     process.env.SMTP_FROM || s.emailFrom || "",
      emailFromName: s.emailFromName || s.siteName || "",
      globalSmtp:    !!(process.env.SMTP_HOST && process.env.SMTP_USER && process.env.SMTP_PASS),
    },
  });
});

app.put("/api/departments/:id/connections", auth, connectionsGuard, function(req, res) {
  const out = saveDeptConnections(req.params.id, req.body || {});
  if (!out) return res.status(404).json({ error: st("department_missing", req) });
  console.log("[connections] " + (req.session.user.name || req.session.user.id) + " updated " + req.params.id);
  res.json({ ok: true, connections: out });
});

// \u2500\u2500 Per-department mail transport \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500
const _deptTransporters = new Map();

function invalidateDeptTransporter(deptId) {
  Array.from(_deptTransporters.keys()).forEach(function(k) {
    if (k.indexOf(deptId + "|") === 0) _deptTransporters.delete(k);
  });
}

// A department with its own mailbox sends through it; everyone else uses
// the shared relay. This matters for SPF/DKIM \u2014 sending as a different
// domain through the global relay usually lands in spam.
function getTransporterForDept(deptId) {
  if (!deptId) return getTransporter();
  const smtp = (getDeptConnections(deptId).email || {}).smtp || {};
  if (!smtp.host || !smtp.user || !smtp.pass) return getTransporter();

  const key = deptId + "|" + smtp.host + "|" + (smtp.port || 587) + "|" + smtp.user;
  if (_deptTransporters.has(key)) return _deptTransporters.get(key);
  try {
    const nodemailer = require("nodemailer");
    const port = parseInt(smtp.port, 10) || 587;
    const t = nodemailer.createTransport({
      host: smtp.host,
      port: port,
      secure: smtp.secure !== undefined ? !!smtp.secure : port === 465,
      auth: { user: smtp.user, pass: smtp.pass },
      tls: { rejectUnauthorized: false },
    });
    _deptTransporters.set(key, t);
    return t;
  } catch(e) {
    console.error("[email] Could not build transport for " + deptId + ": " + e.message);
    return getTransporter();
  }
}

// From address / reply-to for a department, falling back to global.
function getDeptMailIdentity(deptId) {
  const s    = getSettings();
  const dept = getDept(deptId);
  const e    = (getDeptConnections(deptId).email) || {};
  const smtp = e.smtp || {};
  return {
    fromAddress: e.fromAddress || process.env.SMTP_FROM || s.emailFrom || ("noreply@" + (s.eventDomain || DOMAIN)),
    fromName:    (dept && (dept.displayName || dept.name)) || s.emailFromName || s.siteName || "Event-Admin",
    replyTo:     e.replyTo || (dept && dept.contactEmail) || s.contactEmail || "",
    ownSmtp:     !!(smtp.host && smtp.user && smtp.pass),
  };
}

app.post("/api/departments/:id/connections/email/test", auth, connectionsGuard, async function(req, res) {
  const to = (req.body && req.body.to || "").trim();
  if (!to) return res.status(400).json({ error: "Oppgi en mottakeradresse" });
  const ident = getDeptMailIdentity(req.params.id);
  const r = await sendEmail({
    to: to,
    subject: "Testmelding fra " + ident.fromName,
    html: "<p>Denne testmeldingen bekrefter at e-postoppsettet for <strong>" + escHtml(ident.fromName) + "</strong> virker.</p>"
        + "<p style='color:#666;font-size:13px'>Avsender: " + escHtml(ident.fromAddress)
        + (ident.ownSmtp ? " (avdelingens egen e-postkonto)" : " (felles utsending)") + "</p>",
    department: req.params.id,
    category: "test",
  });
  if (!r.ok) return res.status(502).json({ error: st("sending_failed_prefix", req) + (r.reason || "ukjent") });
  res.json({ ok: true, from: ident.fromAddress, ownSmtp: ident.ownSmtp });
});

// \u2500\u2500 Facebook page posting \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500
const FB_GRAPH = "https://graph.facebook.com/v21.0";

function graphRequest(method, urlPath, params, cb) {
  const https = require("https");
  const body  = new URLSearchParams(params || {}).toString();
  const isGet = method === "GET";
  const url   = FB_GRAPH + urlPath + (isGet ? "?" + body : "");
  const opts  = require("url").parse(url);
  opts.method = method;
  opts.timeout = 20000;
  opts.headers = isGet ? {} : {
    "Content-Type": "application/x-www-form-urlencoded",
    "Content-Length": Buffer.byteLength(body),
  };
  let done = false;
  function once(err, data) { if (done) return; done = true; cb(err, data); }
  const r = https.request(opts, function(resp) {
    let raw = "";
    resp.on("data", function(d) { raw += d; });
    resp.on("end", function() {
      let parsed = null;
      try { parsed = JSON.parse(raw); } catch(e) {}
      if (parsed && parsed.error) return once(new Error(parsed.error.message || "Graph API-feil"));
      if (resp.statusCode !== 200) return once(new Error("HTTP " + resp.statusCode));
      once(null, parsed || {});
    });
  });
  r.on("error", once);
  r.on("timeout", function() { r.destroy(); once(new Error("Tidsavbrudd mot Facebook")); });
  if (!isGet) r.write(body);
  r.end();
}

app.post("/api/departments/:id/connections/facebook/test", auth, connectionsGuard, function(req, res) {
  const fb = getDeptConnections(req.params.id).facebook || {};
  if (!fb.pageId || !fb.pageToken) return res.status(400).json({ error: st("page_id_token_missing", req) });
  graphRequest("GET", "/" + fb.pageId, { fields: "name,id", access_token: fb.pageToken }, function(err, data) {
    if (err) return res.status(502).json({ error: err.message });
    res.json({ ok: true, pageName: data.name, pageId: data.id });
  });
});

function eventPublicUrl(ev) {
  const s = getSettings();
  const domain = s.eventDomain || DOMAIN;
  const proto = /^(localhost|127\.)/.test(domain) ? "http://" : "https://";
  return proto + (ev.slug || "") + "." + domain;
}

function buildFacebookMessage(ev, dept) {
  const lines = [];
  lines.push(ev.title || "Nytt arrangement");
  if (ev.date) {
    const d = new Date(ev.date);
    const dateStr = d.toLocaleDateString("nb-NO", { weekday: "long", day: "numeric", month: "long" });
    lines.push("\ud83d\uddd3 " + dateStr + (ev.time ? " kl. " + String(ev.time).slice(0, 5) : ""));
  }
  if (ev.location) lines.push("\ud83d\udccd " + ev.location);
  if (ev.description) lines.push("", String(ev.description).slice(0, 600));
  lines.push("", "P\u00e5melding: " + eventPublicUrl(ev));
  return lines.join("\n");
}

function postEventToFacebook(ev, cb) {
  const dept = getDept(ev.department);
  const fb   = getDeptConnections(ev.department).facebook || {};
  if (!fb.pageId || !fb.pageToken) return cb(new Error("Facebook er ikke satt opp for denne avdelingen"));
  graphRequest("POST", "/" + fb.pageId + "/feed", {
    message: buildFacebookMessage(ev, dept),
    link: eventPublicUrl(ev),
    access_token: fb.pageToken,
  }, function(err, data) {
    if (err) return cb(err);
    // Record the post id so the event is never posted twice
    const events = readJSON(EVENTS_FILE);
    const i = events.findIndex(function(e) { return e.id === ev.id; });
    if (i >= 0) {
      events[i].facebookPostId = (data && data.id) || "posted";
      events[i].facebookPostedAt = new Date().toISOString();
      writeJSON(EVENTS_FILE, events);
    }
    cb(null, data);
  });
}

// Manual "post now" \u2014 same permission model as the rest of the event API
app.post("/api/events/:id/facebook-post", auth, managerOrAdmin, function(req, res) {
  const ev = readJSON(EVENTS_FILE).find(function(e) { return e.id === req.params.id; });
  if (!ev) return res.status(404).json({ error: st("event_not_found_msg", req) });
  if (!canEditEvent(ev, req.session.user)) return res.status(403).json({ error: st("no_access", req) });
  if (ev.facebookPostId && !(req.body && req.body.force)) {
    return res.status(409).json({ error: st("already_posted_facebook", req) });
  }
  postEventToFacebook(ev, function(err, data) {
    if (err) return res.status(502).json({ error: err.message });
    res.json({ ok: true, postId: data && data.id });
  });
});

// \u2500\u2500 Auto-post sweep \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500
// Runs on a timer rather than hooking event creation, so events that
// arrive by any route are covered and failures retry on the next pass.
let _fbSweepRunning = false;

function facebookAutoPostSweep() {
  if (_fbSweepRunning) return;
  const depts = (getSettings().departments || []).filter(function(d) {
    const fb = (d.connections && d.connections.facebook) || {};
    return fb.autoPost && fb.pageId && fb.pageToken;
  });
  if (!depts.length) return;

  const deptIds = depts.map(function(d) { return d.id; });
  const now = Date.now();
  const due = readJSON(EVENTS_FILE).filter(function(ev) {
    if (ev.facebookPostId) return false;
    if (deptIds.indexOf(ev.department) === -1) return false;
    if (ev.hideFromList || ev.isInternal || ev.cancelled) return false;
    if (!ev.date) return false;
    const end = new Date(ev.endDate || ev.date);
    end.setHours(23, 59, 59, 999);
    return end.getTime() >= now; // never post events that already happened
  });
  if (!due.length) return;

  _fbSweepRunning = true;
  let i = 0;
  (function next() {
    if (i >= due.length) { _fbSweepRunning = false; return; }
    const ev = due[i++];
    postEventToFacebook(ev, function(err, data) {
      if (err) console.warn("[facebook] " + (ev.title || ev.id) + ": " + err.message);
      else     console.log("[facebook] Posted " + (ev.title || ev.id) + " \u2192 " + (data && data.id));
      setTimeout(next, 3000); // stay well inside Graph API rate limits
    });
  })();
}

setTimeout(facebookAutoPostSweep, 90 * 1000);
setInterval(facebookAutoPostSweep, 5 * 60 * 1000);

// \u2500\u2500 Undergruppe-utseende \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500
app.put("/api/departments/:deptId/subgroups/:sgId/appearance", auth, function(req, res) {
  const u = req.session.user;
  const s = getSettings();
  const depts = s.departments || [];
  const deptIdx = depts.findIndex(function(d) { return d.id === req.params.deptId; });
  if (deptIdx < 0) return res.status(404).json({ error: "Department not found" });
  const sgIdx = (depts[deptIdx].subgroups || []).findIndex(function(sg) { return sg.id === req.params.sgId; });
  if (sgIdx < 0) return res.status(404).json({ error: "Subgroup not found" });

  // Allow admin, dept manager, or group manager of this dept
  if (u.role !== "admin") {
    const al = getAccessList(readJSON(USERS_FILE).find(function(x){ return x.id === u.id; }) || {});
    const hasAccess = al.some(function(a) {
      return a.department === req.params.deptId &&
        (a.role === "department_manager" || a.role === "deptManager" ||
         a.role === "group_manager" || a.role === "gruppeansvarlig");
    });
    if (!hasAccess) return res.status(403).json({ error: st("access_denied", req) });
  }

  const app = req.body || {};
  const globalPalette = (s.colors && s.colors.palette) || [];
  let accent = (app.accent || "").trim() || null;
  // Validate accent against global palette
  if (accent && globalPalette.length > 0) {
    if (!globalPalette.map(function(c){ return c.toLowerCase(); }).includes(accent.toLowerCase())) {
      accent = null;
    }
  }

  if (!depts[deptIdx].subgroups[sgIdx].appearance) depts[deptIdx].subgroups[sgIdx].appearance = {};
  var validThemes2 = ["dark","light"];
  depts[deptIdx].subgroups[sgIdx].appearance = {
    accent:       accent,
    theme:        validThemes2.includes(app.theme)        ? app.theme        : "dark",
    themeEvent:   validThemes2.includes(app.themeEvent)   ? app.themeEvent   : null,
    themeTV:      validThemes2.includes(app.themeTV)      ? app.themeTV      : null,
    themeDisplay: validThemes2.includes(app.themeDisplay) ? app.themeDisplay : null,
    logo:         (app.logo || "").trim() || null,
  };
  // Also persist displayName and contactEmail on the subgroup
  if (app.displayName !== undefined)
    depts[deptIdx].subgroups[sgIdx].displayName = (app.displayName || "").trim() || null;
  if (app.contactEmail !== undefined)
    depts[deptIdx].subgroups[sgIdx].contactEmail = (app.contactEmail || "").trim().toLowerCase() || null;

  // About page fields for subgroup
  var sgAboutFields = ["about", "mission", "phone", "website", "address", "plans"];
  sgAboutFields.forEach(function(key) {
    if (app[key] !== undefined) depts[deptIdx].subgroups[sgIdx][key] = (app[key] || "").trim() || null;
  });
  if (app.roles !== undefined) {
    try { depts[deptIdx].subgroups[sgIdx].roles = JSON.parse(app.roles); } catch(e) {}
  }

  s.departments = depts;
  saveSettings(s);
  res.json({ ok: true, appearance: depts[deptIdx].subgroups[sgIdx].appearance });
});

app.post("/api/departments/:deptId/subgroups", auth, ugGuard, function(req, res) {
  const sgName  = (req.body.name || "").trim();
  const _rawColor = (req.body.color || "#7dff7d").trim();
  const color = /^#[0-9a-fA-F]{3}([0-9a-fA-F]{3})?$/.test(_rawColor) ? _rawColor : "#888888";
  if (!sgName) return res.status(400).json({ error: "Name is required" });
  const s = getSettings();
  const dept = (s.departments || []).find(function(a) { return a.id === req.params.deptId; });
  if (!dept) return res.status(404).json({ error: "Department not found" });
  if (!dept.subgroups) dept.subgroups = [];
  if (dept.subgroups.find(function(u) { return u.name.toLowerCase() === sgName.toLowerCase(); }))
    return res.status(409).json({ error: st("subgroup_exists", req) });
  dept.subgroups.push({ id: uuid(), name: sgName, color: color });
  saveSettings(s);
  broadcastEventUpdate(req.params.deptId);
  res.json(dept);
});

