// \u2500\u2500 Guestbook API \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500
app.post("/api/events/:id/guestbook", rateLimit(5, 60000), function(req, res) {
  const name    = sanitizeInput((req.body.name || "").trim().slice(0, 100));
  const phone   = sanitizeInput((req.body.phone || "").trim().slice(0, 30));
  const message = sanitizeInput((req.body.message || "").trim().slice(0, 1000));
  if (!name) return res.status(400).json({ error: "Name is required" });
  const events = readJSON(EVENTS_FILE);
  const ev = events.find(function(e) { return e.id === req.params.id || e.slug === req.params.id; });
  if (!ev) return res.status(404).json({ error: "Not found" });
  if (!ev.guestbook) ev.guestbook = [];
  const gbId = uuid();
  ev.guestbook.push({ id: gbId, name: name, phone: phone, message: message, approved: false, createdAt: new Date().toISOString() });
  writeJSON(EVENTS_FILE, events);
  broadcastEventUpdate(ev.department);
  res.json({ ok: true, id: gbId });

  // Notify event creator
  notifyCreator(ev, 'Ny gjestebokmelding \u2013 ' + ev.title, `
    <p>\u270d\ufe0f <strong>${escHtml(name)}</strong> har lagt inn en gjestebokmelding p\u00e5 <strong>${escHtml(ev.title)}</strong>.</p>
    <blockquote style="border-left:3px solid #ccc;padding:.75rem 1rem;margin:1rem 0;color:var(--text2);font-style:italic">${escHtml(message)}</blockquote>
    <p style="font-size:.85rem;color:#888">Meldingen er til godkjenning og vises ikke offentlig f\u00f8r du godkjenner den.</p>`);

  // send e-postnotifikasjon to avdelingsledere and admins
  try {
    const settings = getSettings();
    const users    = readJSON(USERS_FILE);
    const evUrl    = "https://" + ADMIN_DOMAIN + "/#ev-" + ev.id;
    const managers = users.filter(function(u) {
      if (!u.email || u.disabled) return false;
      if (u.role === "admin") return true;
      if (u.role === "manager" || u.role === "deptManager") {
        // check about user has access to denne avdelingen
        const access = getAccessList(u);
        return !access.length || access.includes(ev.department);
      }
      return false;
    });
    if (managers.length && SMTP_HOST) {
      const subject = "Ny gjestebokmelding p\u00e5 " + (ev.title || "arrangement");
      const html = "<p>Hei!</p>"
        + "<p><strong>" + escHtml(name) + "</strong> har lagt inn en kommentar i gjesteboken for <strong>" + escHtml(ev.title || "") + "</strong>:</p>"
        + "<blockquote style=\"border-left:3px solid #ccc;padding-left:1rem;margin:1rem 0;color:#555\">" + escHtml(message) + "</blockquote>"
        + "<p>Kommentaren m\u00e5 godkjennes f\u00f8r den vises offentlig.</p>"
        + "<p><a href=\"" + evUrl + "\" style=\"background:" + ((settings.colors && settings.colors.accent) || "#FFD100") + ";color:#111;padding:.5rem 1rem;border-radius:6px;text-decoration:none;font-weight:700\">G\u00e5 til arrangementet</a></p>"
        + "<p style=\"color:#999;font-size:.85em\">Sendt fra " + (settings.siteName || "Event-Admin") + "</p>";
      managers.forEach(function(u) {
        sendMail({ to: u.email, subject: subject, html: html }).catch(function(){});
      });
    }
  } catch(e) { /* e-post er ikke kritisk */ }
});

// \u2500\u2500 Gjestebok bilde-opplasting via QR \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500
// In-memory token store: token -> { evId, gbId, expires, photoUrl }
const _gbPhotoTokens = new Map();
const _gbPhotoSSE    = new Map(); // token -> res

// create token for bildeupplasting
app.post("/api/events/:id/guestbook/:gid/photo-token", rateLimit(50, 60000), function(req, res) {
  const evId = req.params.id;
  const gbId = req.params.gid;
  const ev   = readJSON(EVENTS_FILE).find(function(e) { return e.id === evId || e.slug === evId; });
  if (!ev) return res.status(404).json({ error: "Not found" });
  const entry = (ev.guestbook || []).find(function(g) { return g.id === gbId; });
  if (!entry) return res.status(404).json({ error: "Not found" });
  const token   = require("crypto").randomBytes(16).toString("hex");
  const expires = Date.now() + 10 * 60 * 1000; // 10 min
  var tags = req.body.tags || [];
  if (typeof tags === "string") tags = tags.split(",").map(function(t) { return t.trim(); }).filter(Boolean);
  _gbPhotoTokens.set(token, { evId: ev.id, gbId, expires, tags: tags });
  res.json({ token, url: "/gb-photo/" + token });
});

// SSE \u2013 wait for image (used by QR modal on event page)
app.get("/api/gb-photo-wait/:token", function(req, res) {
  const token = req.params.token;
  if (!_gbPhotoTokens.has(token)) return res.status(404).json({ error: "Invalid token" });
  res.setHeader("Content-Type", "text/event-stream");
  res.setHeader("Cache-Control", "no-cache");
  res.setHeader("Connection", "keep-alive");
  res.flushHeaders();
  _gbPhotoSSE.set(token, res);
  req.on("close", function() { _gbPhotoSSE.delete(token); });
});

// Mobilside for bildevalg

// Signal from mobile that all photos are uploaded
app.post("/api/gb-photo-done/:token", function(req, res) {
  var token = req.params.token;
  var sseRes = _gbPhotoSSE.get(token);
  if (sseRes) {
    sseRes.write("data: " + JSON.stringify({ done: true }) + "\n\n");
    sseRes.end();
    _gbPhotoSSE.delete(token);
  }
  res.json({ ok: true });
});

app.get("/gb-photo/:token", function(req, res) {
  const token = req.params.token;
  const info  = _gbPhotoTokens.get(token);
  if (!info || Date.now() > info.expires) {
    return res.send('<!DOCTYPE html><html><head><meta charset="UTF-8"/><meta name="viewport" content="width=device-width,initial-scale=1"/><title>Utl\u00f8pt</title><style>body{font-family:sans-serif;background:#1a1a1a;color:#fff;display:flex;align-items:center;justify-content:center;min-height:100vh;text-align:center;padding:2rem}</style></head><body><h2>\u23f0 Lenken er utl\u00f8pt</h2><p>G\u00e5 tilbake til event-siden og pr\u00f8v igjen.</p></body></html>');
  }
  const s = getSettings();
  const siteName  = s.siteName || "Event-Admin";
  const logoUrl   = s.logoUrl  || "";
  const accentCol = (s.colors && s.colors.accent) || "#FFD100";
  const logoHtml  = logoUrl
    ? `<img src="${escHtml(logoUrl)}" alt="${escHtml(siteName)}" style="height:40px;object-fit:contain;margin-bottom:1.5rem"/>`
    : `<div style="background:${escHtml(accentCol)};color:#111;font-weight:900;font-size:1.2rem;padding:5px 16px;border-radius:6px;margin-bottom:1.5rem;display:inline-block">${escHtml(siteName.split(" ")[0])}</div>`;

  res.send(`<!DOCTYPE html>
<html lang="no">
<head>
<meta charset="UTF-8"/>
<meta name="viewport" content="width=device-width,initial-scale=1"/>
<script>
// Auto-scale for 4K / high-res displays
// Detects actual window size and scales up if running below native resolution
(function(){
  var w = window.screen.width;
  var h = window.screen.height;
  // If screen reports 4K+ but window is 1080p (common Pi setup), apply scale
  if ((w >= 3840 || h >= 2160) && window.innerWidth <= 1920) {
    var s = w / window.innerWidth;
    document.documentElement.style.transform = 'scale(' + s + ')';
    document.documentElement.style.transformOrigin = '0 0';
    document.documentElement.style.width = (100/s) + '%';
    document.documentElement.style.height = (100/s) + '%';
  }
})();
</script>
<title>Last opp bilder – ${escHtml(siteName)}</title>
<style>
*{box-sizing:border-box;margin:0;padding:0}
body{font-family:"Helvetica Neue",Arial,sans-serif;background:#1a1a1a;color:#fff;min-height:100vh;display:flex;flex-direction:column;align-items:center;padding:2rem 1.25rem;text-align:center}
h1{font-size:1.25rem;margin-bottom:.4rem}
.sub{color:#888;font-size:.88rem;margin-bottom:1.75rem;line-height:1.5}
.pick-zone{border:2px dashed #444;border-radius:12px;padding:2rem 1rem;cursor:pointer;width:100%;max-width:420px;margin-bottom:1.25rem;transition:border-color .2s}
.pick-zone:hover,.pick-zone:active{border-color:${escHtml(accentCol)}}
.pick-icon{font-size:2.5rem;margin-bottom:.5rem}
.pick-label{font-size:.95rem;color:#888}
.thumb-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:.5rem;width:100%;max-width:420px;margin-bottom:1.25rem}
.thumb-wrap{position:relative;aspect-ratio:1;border-radius:8px;overflow:hidden;background:#2a2a2a}
.thumb-wrap img{width:100%;height:100%;object-fit:cover}
.thumb-del{position:absolute;top:4px;right:4px;background:rgba(0,0,0,.7);border:none;color:#fff;border-radius:50%;width:22px;height:22px;font-size:.75rem;cursor:pointer;display:flex;align-items:center;justify-content:center;line-height:1}
.thumb-status{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;font-size:1.4rem;background:rgba(0,0,0,.45)}
.btn{background:${escHtml(accentCol)};color:#111;font-weight:700;padding:.9rem 1.5rem;border-radius:8px;font-size:1rem;border:none;cursor:pointer;width:100%;max-width:420px;margin-bottom:.75rem}
.btn:disabled{opacity:.5;cursor:not-allowed}
.btn.secondary{background:#2a2a2a;color:#fff;border:1px solid #444}
.status{font-size:.9rem;min-height:1.4rem;margin-bottom:.5rem;max-width:420px}
.ok{color:#4ade80}.err{color:#f87171}
input[type=file]{display:none}
</style>
</head>
<body>
${logoHtml}
<h1>📸 Legg ved bilder</h1>
<p class="sub">Velg ett eller flere bilder fra kamera eller galleri.<br>De knyttes til kommentaren din i gjesteboken.</p>

<div class="pick-zone" id="pickZone" onclick="document.getElementById('fileInput').click()">
  <div class="pick-icon">🖼️</div>
  <div class="pick-label">Trykk for å velge bilder</div>
</div>

<!-- Ingen capture-attributt = brukeren velger selv kamera eller galleri -->
<input type="file" id="fileInput" accept="image/*" multiple onchange="onFilesChange(this)"/>

<div class="thumb-grid" id="thumbGrid" style="display:none"></div>

<div class="status" id="status"></div>

<button class="btn" id="addMoreBtn" style="display:none" onclick="document.getElementById('fileInput').click()">➕ Legg til flere bilder</button>
<button class="btn" id="sendBtn" style="display:none" onclick="sendAllPhotos()">✅ Send alle bilder (<span id="sendCount">0</span>)</button>

<script>
var selectedFiles = [];
var token = "${token}";

function onFilesChange(input) {
  var files = Array.from(input.files);
  if (!files.length) return;
  var remaining = 300 - selectedFiles.length;
  if (remaining <= 0) { alert('Maks 300 bilder per opplasting'); input.value = ''; return; }
  files.slice(0, remaining).forEach(function(f) { selectedFiles.push({ file: f, status: 'pending' }); });
  if (files.length > remaining) alert('Maks 300 bilder \u2013 ' + (files.length - remaining) + ' bilder ble ikke lagt til.');
  input.value = "";
  renderThumbs();
}

function renderThumbs() {
  var grid = document.getElementById("thumbGrid");
  var zone = document.getElementById("pickZone");
  var sendBtn = document.getElementById("sendBtn");
  var addBtn  = document.getElementById("addMoreBtn");
  var countEl = document.getElementById("sendCount");

  if (!selectedFiles.length) {
    grid.style.display = "none";
    zone.style.display = "block";
    sendBtn.style.display = "none";
    addBtn.style.display  = "none";
    return;
  }

  zone.style.display = "none";
  grid.style.display = "grid";
  addBtn.style.display  = "block";

  var pending = selectedFiles.filter(function(f){ return f.status === "pending"; }).length;
  countEl.textContent = pending;
  sendBtn.style.display = pending > 0 ? "block" : "none";

  grid.innerHTML = "";
  selectedFiles.forEach(function(item, i) {
    var wrap = document.createElement("div");
    wrap.className = "thumb-wrap";

    var img = document.createElement("img");
    var reader = new FileReader();
    reader.onload = function(e){ img.src = e.target.result; };
    reader.readAsDataURL(item.file);
    wrap.appendChild(img);

    if (item.status === "pending") {
      var del = document.createElement("button");
      del.className = "thumb-del";
      del.textContent = "\u00d7";
      del.onclick = function(e) {
        e.stopPropagation();
        selectedFiles.splice(i, 1);
        renderThumbs();
      };
      wrap.appendChild(del);
    } else if (item.status === "done") {
      var ov = document.createElement("div");
      ov.className = "thumb-status";
      ov.textContent = "\u2705";
      wrap.appendChild(ov);
    } else if (item.status === "error") {
      var ov2 = document.createElement("div");
      ov2.className = "thumb-status";
      ov2.style.color = "#f87171";
      ov2.textContent = "\u274c";
      wrap.appendChild(ov2);
    } else if (item.status === "sending") {
      var ov3 = document.createElement("div");
      ov3.className = "thumb-status";
      ov3.textContent = "\u23f3";
      wrap.appendChild(ov3);
    }

    grid.appendChild(wrap);
  });
}

async function sendAllPhotos() {
  var pending = selectedFiles.filter(function(f){ return f.status === "pending"; });
  if (!pending.length) return;

  document.getElementById("sendBtn").disabled = true;
  document.getElementById("addMoreBtn").disabled = true;

  var ok = 0, fail = 0;
  var total = pending.length;
  var CONCURRENCY = 6; // upload 6 photos simultaneously

  function updateStatus() {
    var done = ok + fail;
    var pct = Math.round(done / total * 100);
    document.getElementById("status").innerHTML =
      "\u23f3 " + done + "/" + total + " bilder ("+pct+"%)" +
      (fail > 0 ? " \u00b7 <span style='color:#f87171'>" + fail + " feil</span>" : "");
  }

  updateStatus();

  async function uploadOne(item) {
    item.status = "sending";
    renderThumbs();
    var fd = new FormData();
    fd.append("photo", item.file);
    try {
      var r = await fetch("/api/gb-photo/" + token, { method: "POST", body: fd });
      if (r.ok) { item.status = "done"; ok++; }
      else { item.status = "error"; fail++; }
    } catch(e) {
      item.status = "error"; fail++;
    }
    renderThumbs();
    updateStatus();
  }

  // Process in parallel batches of CONCURRENCY
  var queue = selectedFiles.filter(function(f){ return f.status === "pending"; });
  for (var i = 0; i < queue.length; i += CONCURRENCY) {
    var batch = queue.slice(i, i + CONCURRENCY);
    await Promise.all(batch.map(uploadOne));
  }

  var st = document.getElementById("status");
  if (fail === 0) {
    // Show thank you screen
    // Signal desktop that upload is done (closes SSE cleanly)
    fetch('/api/gb-photo-done/'+token, {method:'POST'}).catch(function(){});
    document.body.innerHTML = '<div style="display:flex;flex-direction:column;align-items:center;justify-content:center;min-height:100vh;padding:2rem;text-align:center;font-family:Helvetica Neue,Arial,sans-serif;background:#1a1a1a;color:#fff">'
      + '<div style="font-size:4rem;margin-bottom:1.5rem">\ud83c\udf89</div>'
      + '<h1 style="font-size:1.5rem;font-weight:900;margin-bottom:.75rem">Tack f\u00f6r ditt bidrag!</h1>'
      + '<p style="font-size:.95rem;color:var(--ev-muted);max-width:320px;line-height:1.6">' + ok + ' bilde' + (ok > 1 ? 'r' : '') + ' er mottatt og vil vises i gjesteboken etter godkjenning.</p>'
      + '</div>';
  } else {
    st.innerHTML = '<span class="ok">' + ok + ' sendt</span> \u00b7 <span class="err">' + fail + ' feilet</span>';
    document.getElementById("sendBtn").disabled = false;
    document.getElementById("sendBtn").textContent = "\ud83d\udd04 Pr\u00f8v feilede bilder";
    // Reset failed to pending so they can be retried
    selectedFiles.forEach(function(f){ if(f.status === "error") f.status = "pending"; });
    renderThumbs();
  }
  document.getElementById("addMoreBtn") && (document.getElementById("addMoreBtn").disabled = false);
}
</script>
</body>
</html>`);
});

// Motta bilde fra mobil
const photoUpload = multer({
  storage: multer.diskStorage({
    destination: function(req, file, cb) {
      const dir = path.join(DATA, "gb-photos");
      if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });
      cb(null, dir);
    },
    filename: function(req, file, cb) {
      const ext = path.extname(file.originalname).toLowerCase() || ".jpg";
      cb(null, req.params.token + "_" + Date.now() + ext);
    }
  }),
  fileFilter: function(req, file, cb) {
    // Support both image and video
    const ok = /^image\//.test(file.mimetype) || /^video\//.test(file.mimetype);
    cb(null, ok);
  },
  limits: { fileSize: 50 * 1024 * 1024 * 1024 } // 50GB
});

// ══════════════════════════════════════════════════════════════════
// Inventory photos from a phone (QR hand-off)
// ------------------------------------------------------------------
// The admin UI has offered "Last opp fra mobil" on inventory items for a
// while, but the three endpoints it calls were never implemented. The
// POST for a token fell through to the catch-all, so `r.url` came back
// undefined and the QR encoded "<origin>undefined" - which resolved to a
// non-existent host on the phone (DNS_PROBE_FINISHED_NXDOMAIN), and the
// SSE channel then reported "Tilkobling avbrutt".
//
// This mirrors the guestbook photo hand-off, which is the same flow and
// is known to work: token -> QR -> phone uploads -> SSE pushes the URL
// back to the desktop form.
// ══════════════════════════════════════════════════════════════════

const _invPhotoTokens = new Map(); // token -> { itemId, expires }
const _invPhotoSSE    = new Map(); // token -> res

function _cleanInvPhotoTokens() {
  const now = Date.now();
  for (const [t, info] of _invPhotoTokens) if (now > info.expires) _invPhotoTokens.delete(t);
}

// Reuse the guestbook upload directory and multer instance - same file
// shapes, same lifecycle, and it is already wired up for static serving.
const _invPhotoUpload = multer({
  storage: multer.diskStorage({
    destination: function(req, file, cb) {
      const dir = path.join(DATA, "gb-photos");
      if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });
      cb(null, dir);
    },
    filename: function(req, file, cb) {
      const ext = path.extname(file.originalname).toLowerCase() || ".jpg";
      cb(null, "inv_" + req.params.token + "_" + Date.now() + ext);
    }
  }),
  fileFilter: function(req, file, cb) { cb(null, /^image\//.test(file.mimetype)); },
  limits: { fileSize: 25 * 1024 * 1024 },
});

// 1. Desktop asks for a token. ":id" may be "new" for an item that has not
//    been saved yet - the photo is returned to the form, not written to the
//    item, so an id is not required to exist.
app.post("/api/inventory/:id/photo-token", auth, managerOrAdmin, function(req, res) {
  _cleanInvPhotoTokens();
  const token   = require("crypto").randomBytes(16).toString("hex");
  const expires = Date.now() + 10 * 60 * 1000; // 10 min
  _invPhotoTokens.set(token, { itemId: String(req.params.id || "new"), expires: expires });
  res.json({ token: token, url: "/inv-photo/" + token });
});

// 2. Desktop holds an SSE channel open, waiting for the phone.
app.get("/api/inv-photo-wait/:token", function(req, res) {
  const token = req.params.token;
  if (!_invPhotoTokens.has(token)) return res.status(404).json({ error: "Invalid token" });
  res.setHeader("Content-Type", "text/event-stream");
  res.setHeader("Cache-Control", "no-cache");
  res.setHeader("Connection", "keep-alive");
  res.flushHeaders();
  // A comment frame defeats proxy buffering so the browser sees the stream open
  res.write(": connected\n\n");
  _invPhotoSSE.set(token, res);
  const keepAlive = setInterval(function() { try { res.write(": ping\n\n"); } catch(e) {} }, 25000);
  req.on("close", function() { clearInterval(keepAlive); _invPhotoSSE.delete(token); });
});

// 3. The page the phone opens after scanning the QR.
app.get("/inv-photo/:token", function(req, res) {
  const token = req.params.token;
  const info  = _invPhotoTokens.get(token);
  const s     = getSettings();
  const accent = (s.colors && s.colors.accent) || "#FFD100";
  const siteName = s.siteName || "Event-Admin";

  if (!info || Date.now() > info.expires) {
    return res.send('<!DOCTYPE html><html lang="no"><head><meta charset="UTF-8"/>'
      + '<meta name="viewport" content="width=device-width,initial-scale=1"/><title>Utløpt</title>'
      + '<style>body{font-family:system-ui,sans-serif;background:#1a1a1a;color:#fff;display:flex;'
      + 'align-items:center;justify-content:center;min-height:100vh;text-align:center;padding:2rem}</style>'
      + '</head><body><div><h2>Lenken er utløpt</h2>'
      + '<p>Gå tilbake til utstyrsskjemaet og lag en ny QR-kode.</p></div></body></html>');
  }

  res.send('<!DOCTYPE html><html lang="no"><head><meta charset="UTF-8"/>'
    + '<meta name="viewport" content="width=device-width,initial-scale=1"/>'
    + '<title>' + escHtml(siteName) + ' – last opp bilde</title><style>'
    + '*{box-sizing:border-box}body{font-family:system-ui,-apple-system,sans-serif;background:#f3f4f6;'
    + 'margin:0;padding:1.5rem;display:flex;flex-direction:column;align-items:center;justify-content:center;min-height:100vh}'
    + '.card{background:#fff;border-radius:14px;padding:1.5rem;width:100%;max-width:420px;'
    + 'box-shadow:0 2px 12px rgba(0,0,0,.08);text-align:center}'
    + 'h1{font-size:1.1rem;margin:0 0 1rem}'
    + '.btn{display:block;width:100%;background:' + escHtml(accent) + ';color:#111;border:none;border-radius:10px;'
    + 'padding:1rem;font-size:1rem;font-weight:800;cursor:pointer;margin-top:.75rem}'
    + '.btn[disabled]{opacity:.5}'
    + '.btn-alt{background:#fff;color:#111;border:2px solid #d1d5db}'
    + '#prev{max-width:100%;border-radius:10px;margin-top:1rem;display:none}'
    + '#msg{margin-top:.9rem;font-size:.9rem;color:#6b7280;min-height:1.2rem}'
    + '</style></head><body><div class="card">'
    + '<h1>Ta bilde av utstyret</h1>'
    // Two inputs, not one. `capture` forces the camera and removes the gallery
    // option altogether, so a single button could never offer both - it just
    // opened the camera while the label promised a choice.
    + '<input id="fCam" type="file" accept="image/*" capture="environment" style="display:none"/>'
    + '<input id="fLib" type="file" accept="image/*" style="display:none"/>'
    + '<button class="btn" id="pickCam">\ud83d\udcf7 Ta bilde</button>'
    + '<button class="btn btn-alt" id="pickLib">🖼 Velg fra galleri</button>'
    + '<img id="prev" alt=""/>'
    + '<button class="btn" id="send" style="display:none">Send til PC-en</button>'
    + '<div id="msg"></div>'
    + '</div><script>'
    + 'var TOKEN=' + JSON.stringify(token) + ';'
    + 'var fCam=document.getElementById("fCam"),fLib=document.getElementById("fLib"),'
    + 'pickCam=document.getElementById("pickCam"),pickLib=document.getElementById("pickLib"),'
    + 'prev=document.getElementById("prev"),send=document.getElementById("send"),msg=document.getElementById("msg");'
    + 'var chosen=null;'
    + 'pickCam.onclick=function(){fCam.click();};'
    + 'pickLib.onclick=function(){fLib.click();};'
    + 'function onPicked(inp){return function(){if(!inp.files||!inp.files[0])return;'
    + 'chosen=inp.files[0];prev.src=URL.createObjectURL(chosen);prev.style.display="block";'
    + 'send.style.display="block";msg.textContent="";};}'
    + 'fCam.onchange=onPicked(fCam);fLib.onchange=onPicked(fLib);'
    + 'send.onclick=async function(){'
    + 'if(!chosen){msg.textContent="Velg et bilde først";return;}'
    + 'send.disabled=true;pickCam.disabled=true;pickLib.disabled=true;msg.textContent="Sender…";'
    + 'try{var fd=new FormData();fd.append("photo",chosen);'
    + 'var r=await fetch("/api/inv-photo/"+TOKEN,{method:"POST",body:fd});'
    + 'var d=await r.json().catch(function(){return {};});'
    + 'if(r.ok){msg.textContent="Bildet er sendt. Du kan lukke denne siden.";'
    + 'send.style.display="none";pickCam.style.display="none";pickLib.style.display="none";}'
    + 'else{msg.textContent=d.error||("Feil ("+r.status+")");send.disabled=false;pickCam.disabled=false;pickLib.disabled=false;}'
    + '}catch(e){msg.textContent="Nettverksfeil: "+e.message;send.disabled=false;pickCam.disabled=false;pickLib.disabled=false;}'
    + '};'
    + '</script></body></html>');
});

// 4. The phone posts the file; the URL is pushed back over the SSE channel.
app.post("/api/inv-photo/:token", rateLimit(60, 60000), _invPhotoUpload.single("photo"), function(req, res) {
  const token = req.params.token;
  const info  = _invPhotoTokens.get(token);
  if (!info || Date.now() > info.expires) return res.status(410).json({ error: "Token expired" });
  if (!req.file) return res.status(400).json({ error: st("no_file", req) });

  const photoUrl = "/gb-photos/" + req.file.filename;
  const sseRes = _invPhotoSSE.get(token);
  if (sseRes) {
    try {
      sseRes.write("data: " + JSON.stringify({ photoUrl: photoUrl }) + "\n\n");
      sseRes.write("data: " + JSON.stringify({ done: true }) + "\n\n");
    } catch (e) {}
  }
  res.json({ ok: true, photoUrl: photoUrl });
});

app.post("/api/gb-photo/:token", rateLimit(600, 60000), photoUpload.single("photo"), async function(req, res) {
  const token = req.params.token;
  const info  = _gbPhotoTokens.get(token);
  if (!info || Date.now() > info.expires) return res.status(410).json({ error: "Token expired" });
  if (!req.file) return res.status(400).json({ error: st("no_file", req) });

  const photoUrl = "/gb-photos/" + req.file.filename;
  const filePath = path.join(DATA, "gb-photos", req.file.filename);
  const isVideo  = /^video\//.test(req.file.mimetype);

  // Always re-encode (not just remux) — matches the TV-kanal video uploader,
  // which is the one upload path that's been reliable in production.
  // Re-encoding (rather than a conditional -c copy fast-path) guarantees:
  //  - faststart (moov atom at the front, so playback can start progressively)
  //  - rotation baked into the actual pixels instead of left as a
  //    displaymatrix side-data tag (some players, notably Firefox's <video>
  //    element, can flat-out refuse files that rely on that tag)
  //  - even dimensions (some encoders reject odd width/height)
  // Slower than a plain remux, but correctness over speed here — uploads
  // already run in the background after the response is sent.
  if (isVideo && _ffmpegAvailable()) {
    try {
      const tmpPath = filePath + ".faststart.mp4";
      await new Promise(function(resolve, reject) {
        const { spawn } = require("child_process");
        const ff = spawn("ffmpeg", [
          "-i", filePath,
          "-map_metadata", "-1",
          "-c:v", "libx264",
          "-preset", "fast",
          "-crf", "23",
          "-vf", "scale=trunc(iw/2)*2:trunc(ih/2)*2",
          "-c:a", "aac",
          "-b:a", "128k",
          "-movflags", "+faststart",
          "-y",
          tmpPath
        ]);
        ff.stderr.on("data", function(){});
        ff.on("close", function(code) { code === 0 ? resolve() : reject(new Error("ffmpeg exit " + code)); });
        ff.on("error", reject);
      });
      // Swap in the fixed file only if it was actually produced successfully
      if (fs.existsSync(tmpPath) && fs.statSync(tmpPath).size > 0) {
        fs.renameSync(tmpPath, filePath);
      }
    } catch (e) {
      // If fixing fails for any reason, fall back to serving the original
      // upload as-is rather than failing the whole upload — better a
      // maybe-broken video than none.
      try { fs.unlinkSync(filePath + ".faststart.mp4"); } catch (e2) {}
    }
  }

  // ── Extract EXIF DateTime from JPEG/HEIC ──────────────────────
  function readExifDate(filePath) {
    try {
      const buf = fs.readFileSync(filePath);
      // Only JPEG has EXIF in APP1 marker (FF E1)
      if (buf[0] !== 0xFF || buf[1] !== 0xD8) return null;
      let i = 2;
      while (i < buf.length - 4) {
        if (buf[i] !== 0xFF) break;
        const marker = buf[i + 1];
        const segLen = buf.readUInt16BE(i + 2);
        if (marker === 0xE1) { // APP1 – may contain EXIF
          if (buf.slice(i + 4, i + 10).toString('ascii') === 'Exif\0\0') {
            const exif   = buf.slice(i + 10, i + 2 + segLen);
            const isLE   = exif[0] === 0x49; // 'II' = little-endian
            const rd16   = (o) => isLE ? exif.readUInt16LE(o) : exif.readUInt16BE(o);
            const rd32   = (o) => isLE ? exif.readUInt32LE(o) : exif.readUInt32BE(o);
            const ifd0   = rd32(4);
            const count  = rd16(ifd0);
            for (let t = 0; t < count; t++) {
              const off = ifd0 + 2 + t * 12;
              const tag = rd16(off);
              // Tag 0x0132 = DateTime, 0x9003 = DateTimeOriginal (preferred)
              if (tag === 0x9003 || tag === 0x0132) {
                const valOff = rd32(off + 8);
                // ASCII string: "YYYY:MM:DD HH:MM:SS"
                const str = exif.slice(valOff, valOff + 19).toString('ascii');
                if (/^\d{4}:\d{2}:\d{2} \d{2}:\d{2}:\d{2}$/.test(str)) {
                  const iso = str.slice(0,4)+'-'+str.slice(5,7)+'-'+str.slice(8,10)
                            + 'T'+str.slice(11,13)+':'+str.slice(14,16)+':'+str.slice(17,19);
                  if (tag === 0x9003) return iso; // DateTimeOriginal — stop immediately
                  return iso;
                }
              }
            }
          }
        }
        if (marker === 0xDA) break; // Start of scan — no more metadata
        i += 2 + segLen;
      }
    } catch(e) {}
    return null;
  }

  const exifDate   = readExifDate(filePath);

  // Attach image to guestbook entry
  const events = readJSON(EVENTS_FILE);
  const ev = events.find(function(e) { return e.id === info.evId; });
  if (ev) {
    const entry = (ev.guestbook || []).find(function(g) { return g.id === info.gbId; });
    if (entry) {
      entry.photos = entry.photos || [];
      entry.photos.push(photoUrl);
      // Store photo metadata (exif date if available, else upload time)
      entry.photoMeta = entry.photoMeta || [];
      var photoTags = (info.tags && info.tags.length) ? info.tags : [];
      entry.photoMeta.push({
        url:      photoUrl,
        takenAt:  exifDate || new Date().toISOString(),
        exif:     !!exifDate,
        tags:     photoTags,
      });
      writeJSON(EVENTS_FILE, events);
    }
  }

  // Varsle SSE-klient about every image (not delete SSE, can komme flere)
  const sseRes = _gbPhotoSSE.get(token);
  if (sseRes) {
    sseRes.write("data: " + JSON.stringify({ ok: true, photoUrl, count: (ev && ev.guestbook && ev.guestbook.find(function(g){return g.id===info.gbId;})) ? ((ev.guestbook.find(function(g){return g.id===info.gbId;})).photos||[]).length : 1 }) + "\n\n");
  }

  // Token persists – not deleted after first image
  // Expires automatically after 10 min (checked on next request)
  res.json({ ok: true, photoUrl });
});

