app.post("/api/admin/email/test", auth, adminOnly, async function(req, res) {
  const s = getSettings();
  if (!s.emailEnabled) return res.status(400).json({ error: st("email_not_enabled", req) });
  const transport = getTransporter();
  if (!transport) return res.status(400).json({ error: st("smtp_not_configured_check", req) });
  const to = req.body.to || req.session.user.email;
  const r = await sendEmail({
    to,
    subject: "✅ Test – " + (s.siteName || "Event-Admin"),
    html: `<div style="font-family:sans-serif;padding:2rem"><h2>E-postutsending fungerer! 🎉</h2><p>Denne testen ble sendt fra <strong>${s.siteName || "Event-Admin"}</strong>.</p><p style="color:#999;font-size:.85rem">Avsender: ${s.emailFrom || "noreply@" + s.eventDomain}</p></div>`,
    text: "E-postutsending fungerer! Sendt fra " + (s.siteName || "Event-Admin"),
    category: "system",
  });
  if (!r.ok) return res.status(500).json({ error: r.reason });
  res.json({ ok: true, to, id: r.id });
});
app.get("/api/stats", auth, function(req, res) {
  const user = req.session.user;
  let events = readJSON(EVENTS_FILE);
  if (user.role !== "admin") {
    const myDeptIds = getAccessList(readJSON(USERS_FILE).find(function(u){ return u.id === user.id; }) || {})
      .map(function(a){ return a.department; }).filter(Boolean);
    events = events.filter(function(e){ return myDeptIds.includes(e.department); });
  }
  const now      = Date.now();
  const yearStart     = new Date(new Date().getFullYear(), 0, 1).getTime();
  const lastYearStart = new Date(new Date().getFullYear() - 1, 0, 1).getTime();
  const monthStart= new Date(new Date().getFullYear(), new Date().getMonth(), 1).getTime();
  const sorted   = events.slice().sort(function(a,b){ return new Date(b.date)-new Date(a.date); });

  // Last year comparison
  const evLastYear  = events.filter(function(e){ return e.date && new Date(e.date).getTime() >= lastYearStart && new Date(e.date).getTime() < yearStart; });
  const regsLastYear = evLastYear.reduce(function(s,e){ return s+(e.registrations||[]).length; }, 0);

  // Volunteer stats
  const volunteerMap = new Map();
  events.forEach(function(ev) {
    if (!ev.date || new Date(ev.date).getTime() < yearStart) return;
    (ev.staff || []).forEach(function(s) {
      if (s.checkedIn && s.name && s.name !== "[slettet]") {
        const key = s.name.trim().toLowerCase();
        volunteerMap.set(key, (volunteerMap.get(key) || 0) + 1);
      }
    });
  });
  const totalAppearances = Array.from(volunteerMap.values()).reduce(function(s,n){ return s+n; }, 0);

  // Event counts by type
  const evByType = { mote:0, stand:0, kurs:0, tur:0 };
  events.forEach(function(ev){ const t=ev.eventType||"stand"; if(evByType[t]!==undefined) evByType[t]++; });

  // This year / this month
  const evThisYear  = events.filter(function(e){ return e.date && new Date(e.date).getTime() >= yearStart; });
  const evThisMonth = events.filter(function(e){ return e.date && new Date(e.date).getTime() >= monthStart; });

  // Upcoming events
  const upcoming = events.filter(function(e){ return e.date && new Date(e.date).getTime() > now; });
  upcoming.sort(function(a,b){ return new Date(a.date)-new Date(b.date); });

  // Registration stats
  const totalRegs   = events.reduce(function(s,e){ return s+(e.registrations||[]).length; },0);
  const regsYear    = evThisYear.reduce(function(s,e){ return s+(e.registrations||[]).length; },0);
  const checkedIn   = events.reduce(function(s,e){ return s+(e.registrations||[]).filter(function(r){return r.checkedIn;}).length; },0);
  const checkinRate = totalRegs > 0 ? Math.round(checkedIn/totalRegs*100) : 0;
  const maxParticipants = events.filter(function(e){ return e.maxParticipants>0; });
  const avgCapacity  = maxParticipants.length
    ? Math.round(maxParticipants.reduce(function(s,e){return s+(e.registrations||[]).length/e.maxParticipants;},0)/maxParticipants.length*100)
    : null;

  // Avg regs per event
  const avgRegs = events.length ? (totalRegs / events.length).toFixed(1) : 0;

  // Guestbook entries approved
  const guestbookTotal = events.reduce(function(s,e){ return s+(e.guestbook||[]).filter(function(g){return g.approved;}).length; },0);

  // Walk-ins
  const walkIns = events.reduce(function(s,e){ return s+(e.registrations||[]).filter(function(r){return r.walkIn;}).length; },0);

  res.json({
    // Core
    totalEvents:        events.length,
    totalRegistrations: totalRegs,
    activeVolunteers:   volunteerMap.size,
    totalAppearances:   totalAppearances,
    // By type
    eventsStand:  evByType.stand,
    eventsKurs:   evByType.kurs,
    eventsTur:    evByType.tur,
    eventsMote:   evByType.mote,
    // Last year comparison
    eventsLastYear:  evLastYear.length,
    regsLastYear:    regsLastYear,
    // Walk-ins
    walkIns:          walkIns,
    // Top volunteers this year (max 10)
    topVolunteers: Array.from(volunteerMap.entries())
      .sort(function(a,b){ return b[1]-a[1]; })
      .slice(0, 10)
      .map(function(e){ return { name: e[0], count: e[1] }; }),
    // Time-based
    eventsThisYear:  evThisYear.length,
    eventsThisMonth: evThisMonth.length,
    regsThisYear:    regsYear,
    upcomingEvents:  upcoming.length,
    // Quality
    checkedInTotal:  checkedIn,
    checkinRate:     checkinRate,
    avgRegsPerEvent: avgRegs,
    avgCapacityFill: avgCapacity,
    guestbookEntries: guestbookTotal,
    walkIns:          walkIns,
    // Recent
    recentEvents: sorted.slice(0, 5).map(function(e) {
      return {
        id: e.id, slug: e.slug, title: e.title, date: e.date,
        department: e.department || null,
        registrationCount: (e.registrations || []).length,
        maxParticipants: e.maxParticipants,
        staffCount: (e.staff || []).length,
        staffCheckedIn: (e.staff || []).filter(function(s){ return s.checkedIn; }).length,
      };
    }),
  });
});

// ── Stats: Site (platform-level) ───────────────────────────────────
app.get("/api/stats/site", auth, function(req, res) {
  const settings = getSettings();
  const departments = settings.departments || [];
  const users = readJSON(USERS_FILE) || [];
  const events = readJSON(EVENTS_FILE) || [];
  const members = readJSON(MEMBERS_FILE) || [];
  const volunteers = readJSON(VOLUNTEERS_FILE) || [];
  const tvNodes = readTvNodes ? (readTvNodes() || []) : [];

  // Visit log totals (all-time), reusing the same log file the visit-stats endpoint reads
  let visitTotal = 0;
  try {
    const visits = readJSON(VISITS_FILE) || [];
    visitTotal = visits.length;
  } catch (e) {}

  // Guestbook entries across all events (approved + pending)
  let guestbookTotal = 0, guestbookApproved = 0;
  events.forEach(function(e) {
    (e.guestbook || []).forEach(function(g) {
      guestbookTotal++;
      if (g.approved) guestbookApproved++;
    });
  });

  // Rough storage usage for the uploads directory
  let uploadsBytes = 0, uploadsFiles = 0;
  try {
    function walk(dir) {
      var entries = fs.readdirSync(dir, { withFileTypes: true });
      entries.forEach(function(ent) {
        var full = path.join(dir, ent.name);
        if (ent.isDirectory()) walk(full);
        else { uploadsBytes += fs.statSync(full).size; uploadsFiles++; }
      });
    }
    walk(UPLOADS);
  } catch (e) {}

  const tvOnline = tvNodes.filter(function(n) { return n.status === "registered"; }).length;

  res.json({
    departments: departments.length,
    users: users.length,
    admins: users.filter(function(u){ return u.role === "admin"; }).length,
    managers: users.filter(function(u){ return u.role !== "admin"; }).length,
    members: members.length,
    volunteers: volunteers.length,
    events: events.length,
    visitsAllTime: visitTotal,
    guestbookTotal: guestbookTotal,
    guestbookApproved: guestbookApproved,
    tvNodesTotal: tvNodes.length,
    tvNodesOnline: tvOnline,
    uploadsBytes: uploadsBytes,
    uploadsFiles: uploadsFiles,
    uptimeSeconds: Math.round(process.uptime()),
    version: APP_VERSION,
    nodeVersion: process.version,
  });
});

// ── Stats: Volunteers ───────────────────────────────────────────────
app.get("/api/stats/volunteers", auth, function(req, res) {
  const volunteers = readJSON(VOLUNTEERS_FILE) || [];
  const events = readJSON(EVENTS_FILE) || [];
  const now = Date.now();
  const yearStart = new Date(new Date().getFullYear(), 0, 1).getTime();

  let totalMinutesAllTime = 0, totalMinutesThisYear = 0;
  let totalLoggedRows = 0;
  let pendingSelfReports = 0;
  let pendingClothing = 0;
  let withPhoto = 0;

  volunteers.forEach(function(v) {
    if (v.photo) withPhoto++;
    (v.selfReported || []).forEach(function(sr) { if (sr.status === "pending") pendingSelfReports++; });
    if (v.clothing && typeof v.clothing === "object") {
      Object.keys(v.clothing).forEach(function(k) {
        var c = v.clothing[k];
        if (c && typeof c === "object" && c.size && !c.received) pendingClothing++;
      });
    }
    if (v.timeLogs) {
      Object.keys(v.timeLogs).forEach(function(eventId) {
        (v.timeLogs[eventId] || []).forEach(function(row) {
          var mins = parseInt(row.minutes, 10) || 0;
          totalMinutesAllTime += mins;
          totalLoggedRows++;
          var rowDate = row.date || null;
          if (rowDate && new Date(rowDate).getTime() >= yearStart) totalMinutesThisYear += mins;
          else if (!rowDate) {
            // Fall back to the event's own date if the row itself has none
            var ev = events.find(function(e){ return e.id === eventId; });
            if (ev && ev.date && new Date(ev.date).getTime() >= yearStart) totalMinutesThisYear += mins;
          }
        });
      });
    }
  });

  // Volunteers with at least one logged hour, ranked
  var hoursLeaderboard = volunteers
    .map(function(v) {
      var total = 0;
      if (v.timeLogs) Object.keys(v.timeLogs).forEach(function(eid) {
        (v.timeLogs[eid] || []).forEach(function(r) { total += parseInt(r.minutes, 10) || 0; });
      });
      return { name: v.name || "Ukjent", minutes: total };
    })
    .filter(function(x) { return x.minutes > 0; })
    .sort(function(a, b) { return b.minutes - a.minutes; })
    .slice(0, 10);

  // New volunteers this year (by createdAt / addedAt if present)
  var newThisYear = volunteers.filter(function(v) {
    var added = v.createdAt || v.addedAt || null;
    return added && new Date(added).getTime() >= yearStart;
  }).length;

  res.json({
    totalVolunteers: volunteers.length,
    newThisYear: newThisYear,
    withPhoto: withPhoto,
    pendingSelfReports: pendingSelfReports,
    pendingClothing: pendingClothing,
    totalLoggedRows: totalLoggedRows,
    totalMinutesAllTime: totalMinutesAllTime,
    totalMinutesThisYear: totalMinutesThisYear,
    hoursLeaderboard: hoursLeaderboard,
  });
});

// ── Stats: Members ───────────────────────────────────────────────────
app.get("/api/stats/members", auth, function(req, res) {
  const members = readJSON(MEMBERS_FILE) || [];
  const settings = getSettings();
  const departments = settings.departments || [];
  const now = Date.now();
  const yearStart = new Date(new Date().getFullYear(), 0, 1).getTime();
  const monthStart = new Date(new Date().getFullYear(), new Date().getMonth(), 1).getTime();
  const ninetyDaysAgo = now - 90 * 24 * 3600 * 1000;

  const newThisYear  = members.filter(function(m){ return m.addedAt && new Date(m.addedAt).getTime() >= yearStart; }).length;
  const newThisMonth = members.filter(function(m){ return m.addedAt && new Date(m.addedAt).getTime() >= monthStart; }).length;
  const newLast90     = members.filter(function(m){ return m.addedAt && new Date(m.addedAt).getTime() >= ninetyDaysAgo; }).length;

  // Per-department breakdown — combines the imported member list with any
  // manager-set manual override (dept.memberCount) so both data sources
  // are visible side by side, not just whichever happens to be non-zero.
  const perDept = departments.map(function(d) {
    var imported = members.filter(function(m){ return m.department === d.id; }).length;
    return {
      id: d.id,
      name: d.name,
      imported: imported,
      manualOverride: (d.memberCount != null) ? d.memberCount : null,
      displayed: (d.memberCount != null) ? d.memberCount : imported,
    };
  }).sort(function(a, b) { return b.displayed - a.displayed; });

  // Members with no department assigned at all (orphaned imports)
  const unassigned = members.filter(function(m){ return !m.department; }).length;

  // Simple monthly growth for the last 12 months (based on addedAt)
  const monthBuckets = [];
  for (var i = 11; i >= 0; i--) {
    var d = new Date(); d.setDate(1); d.setMonth(d.getMonth() - i);
    var bucketStart = d.getTime();
    var nd = new Date(d); nd.setMonth(nd.getMonth() + 1);
    var bucketEnd = nd.getTime();
    var count = members.filter(function(m) {
      if (!m.addedAt) return false;
      var t = new Date(m.addedAt).getTime();
      return t >= bucketStart && t < bucketEnd;
    }).length;
    monthBuckets.push({ label: d.toLocaleDateString("nb-NO", { month: "short", year: "2-digit" }), count: count });
  }

  res.json({
    totalMembers: members.length,
    unassigned: unassigned,
    newThisYear: newThisYear,
    newThisMonth: newThisMonth,
    newLast90Days: newLast90,
    perDepartment: perDept,
    monthlyGrowth: monthBuckets,
  });
});

