// ── Volunteer clothing API ────────────────────────────────────────────
// PUT /api/volunteers/:id/clothing  { jacket:{size,received}, vest:{size,received}, cap:{size,received}, ... }
app.put("/api/volunteers/:id/clothing", auth, managerOrAdmin, function(req, res) {
  var all = readJSON(VOLUNTEERS_FILE) || [];
  var i = all.findIndex(function(v){ return v.id === req.params.id; });
  if (i < 0) return res.status(404).json({ error: "Not found" });
  var clothing = all[i].clothing || {};
  // Accept any clothing key (standard + custom)
  Object.keys(req.body).forEach(function(item) {
    if (req.body[item] === null) {
      // null means delete this item
      delete clothing[item];
    } else if (typeof req.body[item] === "object") {
      clothing[item] = {
        size:        (req.body[item].size     || "").slice(0, 10),
        received:    !!req.body[item].received,
        note:        (req.body[item].note     || "").slice(0, 200),
        quantity:    parseInt(req.body[item].quantity) || 1,
        label:       (req.body[item].label    || "").slice(0, 60),
        inventoryId: req.body[item].inventoryId ? String(req.body[item].inventoryId).slice(0, 60) : (clothing[item] && clothing[item].inventoryId) || null,
        batchYear:   req.body[item].batchYear != null ? (parseInt(req.body[item].batchYear, 10) || null) : ((clothing[item] && clothing[item].batchYear) || null),
        imgFront:    (req.body[item].imgFront || "").slice(0, 200000),
        imgBack:     (req.body[item].imgBack  || "").slice(0, 200000),
      };
    }
  });
  all[i].clothing = clothing;
  writeJSON(VOLUNTEERS_FILE, all);
  res.json(all[i]);
});

// ── Bulk export: volunteer hours (CSV) ─────────────────────────
// GET /api/volunteers/export-hours?mode=year|range|event&year=2026&from=2026-01-01&to=2026-06-30&eventId=xxx
// Department-scoped for managers. Returns UTF-8 BOM CSV.
app.get("/api/volunteers/export-hours", auth, managerOrAdmin, function(req, res) {
  var mode    = String(req.query.mode || "year");
  var year    = parseInt(req.query.year, 10) || new Date().getFullYear();
  var fromStr = String(req.query.from || "");
  var toStr   = String(req.query.to   || "");
  var eventId = String(req.query.eventId || "");

  var events  = readJSON(EVENTS_FILE) || [];
  var vols    = readJSON(VOLUNTEERS_FILE) || [];
  var settings = getSettings();
  var allDepts = settings.departments || [];
  var deptName = function(id) { var d = allDepts.find(function(x){ return x.id === id; }); return d ? (d.displayName || d.name || id) : id; };

  // Department scoping for non-admin
  var me = req.session.user;
  if (me.role !== "admin") {
    var myDeptIds = getAccessList(me).map(function(t){ return t.department; });
    vols = vols.filter(function(v) {
      var volDepts = Array.isArray(v.departments) && v.departments.length
        ? v.departments : (v.department ? [v.department] : []);
      if (!volDepts.length) return true;
      return volDepts.some(function(did) { return myDeptIds.indexOf(did) !== -1; });
    });
  }

  // Build event lookup
  var evMap = {};
  events.forEach(function(e) { evMap[e.id] = e; });

  // Filter logic per mode
  function eventInScope(ev) {
    if (!ev) return false;
    if (mode === "event") return ev.id === eventId;
    if (mode === "year") {
      if (!ev.date) return false;
      return new Date(ev.date).getFullYear() === year;
    }
    if (mode === "range") {
      if (!ev.date) return false;
      var d = ev.date.slice(0, 10);
      if (fromStr && d < fromStr) return false;
      if (toStr && d > toStr) return false;
      return true;
    }
    return false;
  }

  // Collect rows
  var csvRows = [];
  vols.forEach(function(v) {
    var tl = v.timeLogs || {};
    var volDepts = Array.isArray(v.departments) && v.departments.length
      ? v.departments : (v.department ? [v.department] : []);
    var volDeptNames = volDepts.map(deptName).join("; ");

    Object.keys(tl).forEach(function(eid) {
      var ev = evMap[eid];
      var isImport = eid === "_excel_import";
      if (!isImport && !eventInScope(ev)) return;
      (tl[eid] || []).forEach(function(row) {
        // For imported rows without a real event, filter by the row's own date
        if (isImport) {
          var rd = row.date || "";
          if (mode === "year" && rd && new Date(rd).getFullYear() !== year) return;
          if (mode === "range") {
            if (fromStr && rd < fromStr) return;
            if (toStr && rd > toStr) return;
          }
        }
        var mins = parseInt(row.minutes, 10) || 0;
        var h = Math.floor(mins / 60);
        var m = mins % 60;
        csvRows.push({
          name: v.name || "",
          email: v.email || "",
          phone: v.phone || "",
          department: volDeptNames,
          eventTitle: isImport ? "Excel-import" : (ev ? ev.title : "(deleted)"),
          eventDate: isImport ? (row.date || "") : (ev ? (ev.date || "").slice(0, 10) : ""),
          eventDept: isImport ? volDeptNames : (ev && ev.department ? deptName(ev.department) : ""),
          rowDate: row.date || "",
          label: row.label || "",
          fromTime: row.fromTime || "",
          toTime: row.toTime || "",
          minutes: mins,
          hours: h + ":" + (m < 10 ? "0" : "") + m,
          addedBy: row.addedBy === "manager" ? "Manager" : row.addedBy === "import" ? "Import" : "Volunteer",
          addedAt: (row.addedAt || "").slice(0, 16).replace("T", " ")
        });
      });
    });
  });

  // Sort by volunteer name, then event date
  csvRows.sort(function(a, b) {
    var c = a.name.localeCompare(b.name, "nb");
    if (c) return c;
    return (a.eventDate || "").localeCompare(b.eventDate || "");
  });

  // Build CSV
  var hdr = ["Name","Email","Phone","Vol. department","Event","Event date","Event department","Row date","Activity","From","To","Minutes","Hours (h:mm)","Added by","Added at"];
  function esc(s) { s = String(s); if (/[",;\n\r]/.test(s)) return '"' + s.replace(/"/g, '""') + '"'; return s; }
  var lines = [hdr.map(esc).join(",")];
  csvRows.forEach(function(r) {
    lines.push([r.name, r.email, r.phone, r.department, r.eventTitle, r.eventDate, r.eventDept, r.rowDate, r.label, r.fromTime, r.toTime, r.minutes, r.hours, r.addedBy, r.addedAt].map(esc).join(","));
  });

  // Summary row
  var totalMin = csvRows.reduce(function(s, r){ return s + r.minutes; }, 0);
  var th = Math.floor(totalMin / 60), tm = totalMin % 60;
  lines.push("");
  lines.push(["TOTAL","","","","","","","","","","",totalMin, th + ":" + (tm < 10 ? "0" : "") + tm, "",""].map(esc).join(","));

  // Unique volunteers summary
  var uniqVols = {};
  csvRows.forEach(function(r){ uniqVols[r.email || r.name] = r.name; });
  lines.push(["Volunteers: " + Object.keys(uniqVols).length,"","","","Rows: " + csvRows.length].map(esc).join(","));

  var csv = "\ufeff" + lines.join("\r\n");
  var fn = "volunteer-hours";
  if (mode === "year") fn += "-" + year;
  else if (mode === "range") fn += "-" + (fromStr || "start") + "-to-" + (toStr || "end");
  else if (mode === "event") { var ev = evMap[eventId]; fn += "-" + (ev ? (ev.title || "").replace(/[^a-zA-Z0-9æøåÆØÅäöÄÖ _-]/g, "").slice(0, 40).trim().replace(/ /g, "-") : eventId).toLowerCase(); }
  fn += ".csv";

  res.setHeader("Content-Type", "text/csv; charset=utf-8");
  res.setHeader("Content-Disposition", 'attachment; filename="' + fn + '"');
  res.send(csv);
});

// GET /api/volunteers/export-hours-pdf — graphical PDF report
app.get("/api/volunteers/export-hours-pdf", auth, managerOrAdmin, function(req, res) {
  // Reuse the same filtering logic as CSV export
  var mode = req.query.mode || "year";
  var year = parseInt(req.query.year) || new Date().getFullYear();
  var fromStr = req.query.from || "";
  var toStr = req.query.to || "";
  var eventId = req.query.eventId || "";
  var events = readJSON(EVENTS_FILE) || [];
  var vols = readJSON(VOLUNTEERS_FILE) || [];
  var settings = getSettings();
  var evMap = {};
  events.forEach(function(e) { evMap[e.id] = e; });
  function deptName(did) { var d = (settings.departments || []).find(function(x) { return x.id === did; }); return d ? (d.displayName || d.name) : did; }
  function eventInScope(ev) {
    if (!ev) return false;
    var d = (ev.date || "").slice(0, 10);
    if (mode === "year") return d && new Date(d).getFullYear() === year;
    if (mode === "range") { return d >= (fromStr || "0") && d <= (toStr || "9"); }
    if (mode === "event") return ev.id === eventId;
    return false;
  }

  // Collect per-volunteer data
  var volData = [];
  vols.forEach(function(v) {
    var tl = v.timeLogs || {};
    var entries = [];
    Object.keys(tl).forEach(function(eid) {
      var ev = evMap[eid];
      var isImport = eid === "_excel_import";
      if (!isImport && !eventInScope(ev)) return;
      (tl[eid] || []).forEach(function(row) {
        if (isImport) {
          var rd = row.date || "";
          if (mode === "year" && rd && new Date(rd).getFullYear() !== year) return;
          if (mode === "range") { if (fromStr && rd < fromStr) return; if (toStr && rd > toStr) return; }
        }
        entries.push({
          date: row.date || (ev ? (ev.date || "").slice(0, 10) : ""),
          event: isImport ? "Excel-import" : (ev ? ev.title : "(slettet)"),
          label: row.label || "",
          minutes: parseInt(row.minutes, 10) || 0,
        });
      });
    });
    if (!entries.length) return;
    entries.sort(function(a, b) { return (a.date || "").localeCompare(b.date || ""); });
    var totalMin = entries.reduce(function(s, e) { return s + e.minutes; }, 0);
    volData.push({ name: v.name, email: v.email || "", entries: entries, totalMinutes: totalMin });
  });
  volData.sort(function(a, b) { return (a.name || "").localeCompare(b.name || "", "nb"); });

  // Build title
  var title = "Frivilligtimer";
  if (mode === "year") title += " " + year;
  else if (mode === "range") title += " " + fromStr + " – " + toStr;
  else if (mode === "event") { var ev = evMap[eventId]; title += " – " + (ev ? ev.title : eventId); }
  var orgName = settings.siteName || "Event-Admin";

  // Generate PDF with pdfkit (pure Node.js)
  var PDFDocument = require("pdfkit");
  var doc = new PDFDocument({ size: "A4", margins: { top: 50, bottom: 50, left: 45, right: 45 } });
  var buffers = [];
  doc.on("data", function(c) { buffers.push(c); });

  var pageW = 595.28 - 90; // A4 minus margins
  var accent = (settings.colors && settings.colors.accent) || "#FFD100";
  var dark = "#1a1a1a";
  var gray = "#666666";
  var lightBg = "#f5f5f5";

  // Helper: draw a table row
  function drawTableRow(doc, y, cols, widths, opts) {
    opts = opts || {};
    var x = 45;
    var h = opts.height || 18;
    if (opts.bg) { doc.save().rect(45, y, pageW, h).fill(opts.bg).restore(); }
    doc.fontSize(opts.fontSize || 7.5).font(opts.bold ? "Helvetica-Bold" : "Helvetica").fillColor(opts.color || dark);
    cols.forEach(function(text, i) {
      var align = opts.alignRight && i === cols.length - 1 ? "right" : "left";
      doc.text(String(text || ""), x + 3, y + 4, { width: widths[i] - 6, align: align, lineBreak: false });
      x += widths[i];
    });
    // Grid lines
    doc.save().strokeColor("#dddddd").lineWidth(0.5);
    doc.moveTo(45, y + h).lineTo(45 + pageW, y + h).stroke();
    var lx = 45;
    widths.forEach(function(w) { doc.moveTo(lx, y).lineTo(lx, y + h).stroke(); lx += w; });
    doc.moveTo(lx, y).lineTo(lx, y + h).stroke();
    doc.restore();
    return y + h;
  }

  // Title page
  doc.fontSize(20).font("Helvetica-Bold").fillColor(dark).text(title, 45, 50);
  doc.fontSize(10).font("Helvetica").fillColor(gray).text(orgName, 45, 75);
  var grandTotal = volData.reduce(function(s, v) { return s + v.totalMinutes; }, 0);
  var grandH = Math.floor(grandTotal / 60), grandM = grandTotal % 60;
  doc.fontSize(9).fillColor(gray).text(
    volData.length + " frivillige | " + grandH + "t " + String(grandM).padStart(2, "0") + "min totalt",
    45, 95
  );

  // Summary table
  var sumWidths = [220, 120, 120];
  var sy = 125;
  sy = drawTableRow(doc, sy, ["Navn", "Registreringer", "Timer"], sumWidths, { bg: accent, bold: true, color: dark, height: 22, fontSize: 8.5 });

  volData.forEach(function(v, vi) {
    if (sy > 760) { doc.addPage(); sy = 50; }
    var h = Math.floor(v.totalMinutes / 60), m = v.totalMinutes % 60;
    sy = drawTableRow(doc, sy, [v.name, v.entries.length, h + "t " + String(m).padStart(2, "0") + "min"], sumWidths,
      { bg: vi % 2 ? lightBg : "#ffffff", alignRight: true });
  });

  // Per-volunteer detail pages
  volData.forEach(function(v) {
    doc.addPage();
    doc.fontSize(14).font("Helvetica-Bold").fillColor(dark).text(v.name, 45, 50);
    var detY = 68;
    if (v.email) { doc.fontSize(8).font("Helvetica").fillColor(gray).text(v.email, 45, detY); detY += 14; }
    var vh = Math.floor(v.totalMinutes / 60), vm = v.totalMinutes % 60;
    doc.fontSize(9).font("Helvetica").fillColor(gray).text(
      "Totalt: " + vh + "t " + String(vm).padStart(2, "0") + "min (" + v.entries.length + " registreringer)", 45, detY
    );
    detY += 22;

    var detWidths = [70, 155, 195, 50];
    detY = drawTableRow(doc, detY, ["Dato", "Arrangement", "Beskrivelse", "Timer"], detWidths, { bg: accent, bold: true, color: dark, height: 20, fontSize: 8 });

    v.entries.forEach(function(e, ei) {
      if (detY > 760) { doc.addPage(); detY = 50; }
      var eh = Math.floor(e.minutes / 60), em = e.minutes % 60;
      detY = drawTableRow(doc, detY, [e.date || "-", e.event, e.label, eh + ":" + String(em).padStart(2, "0")], detWidths,
        { bg: ei % 2 ? lightBg : "#ffffff", alignRight: true });
    });
  });

  doc.end();

  // Wait for PDF to finish, then send
  doc.on("end", function() {
    var pdfBuf = Buffer.concat(buffers);
    var fn = "frivilligtimer_" + (mode === "year" ? year : mode === "range" ? fromStr + "_" + toStr : "rapport") + ".pdf";
    res.setHeader("Content-Type", "application/pdf");
    res.setHeader("Content-Disposition", 'inline; filename="' + fn + '"');
    res.send(pdfBuf);
  });
});

