      + (phone   ? '<a href="tel:' + escHtml(phone.replace(/\s/g,'')) + '" class="contact-chip">📞 ' + escHtml(phone) + '</a>' : '')
      + (website ? '<a href="' + escHtml(website) + '" target="_blank" rel="noopener" class="contact-chip">🌐 ' + escHtml(website.replace(/^https?:\/\//,'')) + '</a>' : '')
      + (address ? '<div class="contact-chip">\ud83d\udccd ' + escHtml(address) + '</div>' : '')
