    + '.banner-sep{color:var(--y);margin:0 2rem;flex-shrink:0}'
    + '.banner-slot{display:none!important}'
    + 'footer{display:none!important}'
    + '.header-qr-only{display:flex!important}'
    + '}'
    + '.col-head{background:var(--g2);border-radius:var(--r) var(--r) 0 0;padding:.6rem 1rem;border-bottom:2px solid var(--y);display:flex;align-items:center;gap:.5rem;margin-bottom:.5rem;position:sticky;top:0;z-index:10}'
    + '.col-head h2{font-size:.8rem;text-transform:uppercase;letter-spacing:.8px;color:var(--y);font-weight:800}'
    + '.col-count{font-size:.72rem;background:'+colCountBg+';color:'+colCountTxt+';padding:1px 7px;border-radius:20px;margin-left:auto}'
    + '.ev-card{display:flex;align-items:stretch;background:var(--g);border-radius:var(--r);margin-bottom:.6rem;text-decoration:none;color:var(--text);overflow:hidden;border:1px solid '+cardBorder+';transition:border-color .15s,transform .1s}'
    + '.ev-card:hover{border-color:var(--y);transform:translateY(-1px)}'
