    + '@keyframes pulse{0%,100%{box-shadow:0 0 0 1px var(--y),0 0 8px 2px rgba(245,197,0,.25)}50%{box-shadow:0 0 0 2px var(--y),0 0 18px 6px rgba(245,197,0,.45)}}'
    + '.today-badge{font-size:.6rem;font-weight:800;padding:2px 7px;border-radius:20px;background:'+badgeBg+';color:var(--y);text-transform:uppercase;letter-spacing:.5px}'
    + '.active-badge{font-size:.6rem;font-weight:800;padding:2px 7px;border-radius:20px;background:var(--y);color:'+activeBadClr+';text-transform:uppercase;letter-spacing:.5px;animation:pulse 2s ease-in-out infinite}'
    + '.ev-date-col{width:68px;min-height:70px;background:'+dateBg+';display:flex;flex-direction:column;align-items:center;justify-content:center;flex-shrink:0;padding:.4rem 0}'
    + '.ev-day{font-size:1.4rem;font-weight:900;line-height:1;color:var(--y)}'
