app.post("/api/events/:id/utstyr", auth, managerOrAdmin, function(req, res) {
  const events = readJSON(EVENTS_FILE);
  const evIdx = events.findIndex(e => e.id === req.params.id);
  if (evIdx === -1) return res.status(404).json({ err: "Not found" });
  if (!events[evIdx].utstyr) events[evIdx].utstyr = [];
  const { itemId, aktiv, quantity } = req.body;
  const existing = events[evIdx].utstyr.findIndex(u => u.id === itemId);
  const isDirectAdd = quantity !== undefined && aktiv === undefined;
  const resolvedQty = parseInt(quantity || antall) || 1;
  if (isDirectAdd || aktiv) {
    if (existing >= 0) events[evIdx].utstyr[existing].quantity = resolvedQty;
    else events[evIdx].utstyr.push({ id: itemId, quantity: resolvedQty });
  } else {
    if (existing >= 0) events[evIdx].utstyr.splice(existing, 1);
  }
  writeJSON(EVENTS_FILE, events);
  broadcastEventUpdate(events[evIdx].department);
  // Update usageCount on inventory item
  const items = readJSON(INVENTORY_FILE);
  const itemIdx = items.findIndex(i => i.id === itemId);
  if (itemIdx >= 0) {
    items[itemIdx].usageCount = events.filter(e => (e.utstyr||[]).some(u => u.id === itemId)).length;
    writeJSON(INVENTORY_FILE, items);
  }
  res.json({ ok: true });
});

// ── Auto-return utstyr (non-giveaway/salg) after event ends ─────────────
// Called by a periodic job or manually. Returns equipment (non-giveaway/salg) to
// inventory stock when the event has finished, if not already returned.
function autoReturnEquipment(evId) {
  var events   = readJSON(EVENTS_FILE);
  var evIdx    = events.findIndex(function(e) { return e.id === evId; });
  if (evIdx < 0) return { returned: [] };
  var ev = events[evIdx];

  // Only process finished events
  var now = Date.now();
  var evEnd = (function() {
    if (!ev.date) return null;
    var d = new Date(ev.endDate || ev.date);
    if (ev.endTime) { var p = ev.endTime.split(":"); d.setHours(+p[0], +p[1], 59, 999); }
    else d.setHours(23, 59, 59, 999);
    return d.getTime();
  })();
  if (!evEnd || evEnd > now) return { returned: [] };
  if (ev.utstyrReturned) return { returned: [], alreadyDone: true }; // idempotent

  var invItems = readJSON(INVENTORY_FILE);
  var NON_RETURN_CATS = new Set(["giveaway", "salgsvarer"]);
  var returned = [];

  (ev.utstyr || []).forEach(function(u) {
    var item = invItems.find(function(i) { return i.id === u.id; });
    if (!item) return;
    if (NON_RETURN_CATS.has(item.category)) return; // skip – manual count needed
    // Return qty back to stock
    item.quantity = (item.quantity || 0) + (u.quantity || 1);
    returned.push({ id: item.id, name: item.name, qty: u.quantity || 1 });
  });

  if (returned.length > 0) {
    writeJSON(INVENTORY_FILE, invItems);
    events[evIdx].utstyrReturned = new Date().toISOString();
    writeJSON(EVENTS_FILE, events);
  }
  return { returned };
}

// POST /api/events/:id/return-equipment  – manual trigger (also called by cron logic)
app.post("/api/events/:id/return-equipment", auth, managerOrAdmin, function(req, res) {
  var result = autoReturnEquipment(req.params.id);
  res.json(result);
});

// GET /api/events/pending-stock-update  – returns event IDs that need manual stock count
app.get("/api/inventory/pending-stock-update", auth, managerOrAdmin, function(req, res) {
  var events   = readJSON(EVENTS_FILE);
  var invItems = readJSON(INVENTORY_FILE);
  var now      = Date.now();
  var NON_RETURN_CATS = new Set(["giveaway", "salgsvarer"]);
  var flagged  = [];

  events.forEach(function(ev) {
    if (!ev.date) return;
    var evEnd = (function() {
      var d = new Date(ev.endDate || ev.date);
      if (ev.endTime) { var p = ev.endTime.split(":"); d.setHours(+p[0], +p[1], 59, 999); }
      else d.setHours(23, 59, 59, 999);
      return d.getTime();
    })();
    if (evEnd > now) return; // not finished yet

    var needsUpdate = false;
    var reasons = [];

    // Check giveaway items — flag if any have distributed > 0 but returned not set
    (ev.giveaway || []).forEach(function(g) {
      var item = invItems.find(function(i) { return i.id === g.id; });
      if (!item || !NON_RETURN_CATS.has(item.category)) return;
      if ((g.distributed || 0) > 0 && (g.returned == null || g.returned < 0)) {
        needsUpdate = true;
        reasons.push("Giveaway ikke oppdatert: " + (item.name || g.id));
      }
      if (g.returned == null) {
        needsUpdate = true;
        reasons.push("Giveaway mangler returtellingen: " + (item.name || g.id));
      }
    });

    // Check salg items — flag if sold count was never set (null/undefined)
    (ev.salg || []).forEach(function(s) {
      var item = invItems.find(function(i) { return i.id === s.id; });
      if (!item || item.category !== "salgsvarer") return;
      if (s.sold == null) {
        needsUpdate = true;
        reasons.push("Salgsantall ikke oppdatert: " + (item.name || s.id));
      }
    });

    // Also flag if event has giveaway/salg category items assigned but no entry recorded at all
    (ev.utstyr || []).forEach(function(u) {
      var item = invItems.find(function(i) { return i.id === u.id; });
      if (!item || !NON_RETURN_CATS.has(item.category)) return;
      // utstyr list has a giveaway/salg item — it should be in ev.giveaway or ev.salg
      var inGiveaway = (ev.giveaway || []).some(function(g) { return g.id === u.id; });
      var inSalg     = (ev.salg     || []).some(function(s) { return s.id === u.id; });
      if (!inGiveaway && !inSalg) {
        needsUpdate = true;
        reasons.push("Ikke registrert distribusjon/salg: " + (item.name || u.id));
      }
    });

    if (needsUpdate) flagged.push({ id: ev.id, title: ev.title, date: ev.date, reasons });
  });

  res.json(flagged);
});

// Startup: auto-return equipment for all finished events not yet processed
(function autoReturnOnStartup() {
  try {
    var events = readJSON(EVENTS_FILE);
    var now    = Date.now();
    events.forEach(function(ev) {
      if (ev.utstyrReturned) return;
      if (!ev.date) return;
      var d = new Date(ev.endDate || ev.date);
      if (ev.endTime) { var p = ev.endTime.split(":"); d.setHours(+p[0], +p[1], 59, 999); }
      else d.setHours(23, 59, 59, 999);
      if (d.getTime() < now) autoReturnEquipment(ev.id);
    });
  } catch(e) { console.error("[inventory] Auto-return on startup failed:", e.message); }
})();

// ── Reiserute per tur-event ───────────────────────────────────────
app.get("/api/events/:id/route", auth, function(req, res) {
  const events = readJSON(EVENTS_FILE);
  const ev = events.find(e => e.id === req.params.id);
  if (!ev) return res.status(404).json({ err: "Not found" });
  res.json(ev.route || { days: [] });
});

// ── Geocoding proxy (avoids CORS and network block from client) ────
// ── Paid maps provider — normalized search/reverse ───────────────────
// Each provider returns wildly different JSON shapes; these normalize to
// the same Nominatim-like array/object the rest of the app already expects,
// so switching providers doesn't require touching any client code.
async function mapsProviderSearch(cfg, q, limit) {
  const enc = encodeURIComponent(q);
  if (cfg.provider === "locationiq") {
    // LocationIQ is a hosted Nominatim — response is already in the right shape.
    const r = await fetch("https://us1.locationiq.com/v1/search?key=" + cfg.apiKey + "&q=" + enc + "&format=json&limit=" + limit + "&addressdetails=1", { signal: AbortSignal.timeout(6000) });
    if (!r.ok) throw new Error("LocationIQ HTTP " + r.status);
    return await r.json(); // already [{lat,lon,display_name,address,...}]
  }
  if (cfg.provider === "geoapify") {
    const r = await fetch("https://api.geoapify.com/v1/geocode/search?text=" + enc + "&limit=" + limit + "&format=json&apiKey=" + cfg.apiKey, { signal: AbortSignal.timeout(6000) });
    if (!r.ok) throw new Error("Geoapify HTTP " + r.status);
    const d = await r.json();
    return (d.results || []).map(function(it) {
      return {
        lat: String(it.lat), lon: String(it.lon),
        display_name: it.formatted || [it.address_line1, it.address_line2].filter(Boolean).join(", "),
        name: it.name || it.address_line1 || "",
        type: it.result_type || "", class: "",
        address: { city: it.city, town: it.city, county: it.county, state: it.state, country: it.country, road: it.street, house_number: it.housenumber, postcode: it.postcode }
      };
    });
  }
  if (cfg.provider === "mapbox") {
    const r = await fetch("https://api.mapbox.com/search/geocode/v6/forward?q=" + enc + "&limit=" + limit + "&access_token=" + cfg.apiKey, { signal: AbortSignal.timeout(6000) });
    if (!r.ok) throw new Error("Mapbox HTTP " + r.status);
    const d = await r.json();
    return (d.features || []).map(function(f) {
      const p = f.properties || {};
      const c = p.context || {};
      const coords = f.geometry && f.geometry.coordinates || [0, 0];
      return {
        lat: String(coords[1]), lon: String(coords[0]),
        display_name: p.full_address || p.place_formatted || p.name || "",
        name: p.name || "", type: p.feature_type || "", class: "",
        address: { city: (c.place||{}).name, county: (c.district||{}).name, state: (c.region||{}).name, country: (c.country||{}).name, road: (c.street||{}).name, postcode: (c.postcode||{}).name }
      };
    });
  }
  if (cfg.provider === "here") {
    const r = await fetch("https://geocode.search.hereapi.com/v1/geocode?q=" + enc + "&limit=" + limit + "&apiKey=" + cfg.apiKey, { signal: AbortSignal.timeout(6000) });
    if (!r.ok) throw new Error("HERE HTTP " + r.status);
    const d = await r.json();
    return (d.items || []).map(function(it) {
      const a = it.address || {};
      return {
        lat: String(it.position.lat), lon: String(it.position.lng),
        display_name: it.title || "", name: a.label || it.title || "",
        type: (it.resultType || ""), class: "",
        address: { city: a.city, county: a.county, state: a.state, country: a.countryName, road: a.street, house_number: a.houseNumber, postcode: a.postalCode }
      };
    });
  }
  throw new Error("Unknown map provider");
}

async function mapsProviderReverse(cfg, lat, lon) {
  if (cfg.provider === "locationiq") {
    const r = await fetch("https://us1.locationiq.com/v1/reverse?key=" + cfg.apiKey + "&lat=" + lat + "&lon=" + lon + "&format=json", { signal: AbortSignal.timeout(6000) });
    if (!r.ok) throw new Error("LocationIQ HTTP " + r.status);
    return await r.json(); // already {display_name, address}
  }
  if (cfg.provider === "geoapify") {
    const r = await fetch("https://api.geoapify.com/v1/geocode/reverse?lat=" + lat + "&lon=" + lon + "&format=json&apiKey=" + cfg.apiKey, { signal: AbortSignal.timeout(6000) });
    if (!r.ok) throw new Error("Geoapify HTTP " + r.status);
    const d = await r.json();
    const it = (d.results || [])[0];
    if (!it) return null;
    return { display_name: it.formatted || "", address: { city: it.city, town: it.city, county: it.county, state: it.state, country: it.country, road: it.street } };
  }
  if (cfg.provider === "mapbox") {
    const r = await fetch("https://api.mapbox.com/search/geocode/v6/reverse?longitude=" + lon + "&latitude=" + lat + "&access_token=" + cfg.apiKey, { signal: AbortSignal.timeout(6000) });
    if (!r.ok) throw new Error("Mapbox HTTP " + r.status);
    const d = await r.json();
    const f = (d.features || [])[0];
    if (!f) return null;
    const p = f.properties || {}, c = p.context || {};
    return { display_name: p.full_address || p.place_formatted || "", address: { city: (c.place||{}).name, county: (c.district||{}).name, state: (c.region||{}).name, country: (c.country||{}).name, road: (c.street||{}).name } };
  }
  if (cfg.provider === "here") {
    const r = await fetch("https://revgeocode.search.hereapi.com/v1/revgeocode?at=" + lat + "," + lon + "&apiKey=" + cfg.apiKey, { signal: AbortSignal.timeout(6000) });
    if (!r.ok) throw new Error("HERE HTTP " + r.status);
    const d = await r.json();
    const it = (d.items || [])[0];
    if (!it) return null;
    const a = it.address || {};
    return { display_name: it.title || "", address: { city: a.city, county: a.county, state: a.state, country: a.countryName, road: a.street } };
  }
  throw new Error("Unknown map provider");
}

// GET /api/maps/config — current provider + masked key (admin)
app.get("/api/maps/config", auth, adminOnly, function(req, res) {
  const s = getSettings();
  const m = s.maps || {};
  function mask(k){ if(!k) return ""; if(k.length<=8) return "••••"; return k.slice(0,4) + "…" + k.slice(-4); }
  res.json({
    provider: m.provider || "",
    apiKeyMasked: mask(m.apiKey || ""),
    hasApiKey: !!m.apiKey,
    configured: getMapsConfig().configured
  });
});

// PUT /api/maps/config — save provider + key (admin)
app.put("/api/maps/config", auth, adminOnly, function(req, res) {
  const s = getSettings();
  const m = Object.assign({}, s.maps || {});
  const b = req.body || {};
  if (b.provider === "" || MAPS_PROVIDERS.indexOf(b.provider) !== -1) m.provider = b.provider;
  function isRealKey(k){ return k && k.indexOf("…") === -1 && k.indexOf("•") === -1; }
  if (b.apiKey !== undefined) {
    if (b.apiKey === "") m.apiKey = "";
    else if (isRealKey(b.apiKey)) m.apiKey = String(b.apiKey).slice(0, 200);
  }
  s.maps = m;
  saveSettings(s);
  res.json({ ok: true, provider: getMapsConfig().provider, configured: getMapsConfig().configured });
});

// POST /api/maps/test — verify the configured provider actually returns results (admin)
app.post("/api/maps/test", auth, adminOnly, async function(req, res) {
  const cfg = getMapsConfig();
  if (!cfg.configured) return res.status(400).json({ ok: false, error: st("no_maps_key", req) });
  try {
    const results = await mapsProviderSearch(cfg, "Oslo, Norway", 1);
    if (!results || !results.length) return res.status(502).json({ ok: false, error: st("response_no_hits", req) });
    res.json({ ok: true, provider: cfg.provider, sample: results[0].display_name });
  } catch(e) {
    res.status(502).json({ ok: false, error: e.message || "Tilkobling feilet" });
  }
});

// ══════════════════════════════════════════════════════════════════
// Direction anchors for AI route planning
// ------------------------------------------------------------------
// The route planner used to hardcode example towns per compass
// direction ("north -> think Hamar, Lillehammer"). That silently
// anchored every customer to eastern Norway: starting in Stockholm,
// "north" would still be pushed towards Lillehammer, which is west.
//
// Instead we derive the anchors from the actual start point: geocode
// the start, project real coordinates out along the requested bearing
// at a few distances, and reverse-geocode those to get real towns that
// genuinely lie in that direction. The AI then gets concrete, correct
// anchors for wherever the customer actually is.
//
// Everything degrades safely: if geocoding is unavailable we fall back
// to a purely geometric constraint, which is still correct, just less
// specific.
// ══════════════════════════════════════════════════════════════════

const EARTH_R_KM = 6371;

// Compass bearings in degrees, clockwise from north.
const DIR_BEARING = {
  nord: 0, nordøst: 45, øst: 90, sørøst: 135,
  sør: 180, sørvest: 225, vest: 270, nordvest: 315,
};

// English label per direction key, for the prompt text itself.
const DIR_LABEL = {
  nord: "NORTH", nordøst: "NORTH-EAST", øst: "EAST", sørøst: "SOUTH-EAST",
  sør: "SOUTH", sørvest: "SOUTH-WEST", vest: "WEST", nordvest: "NORTH-WEST",
};

// Geometric rule per direction, used as the always-true constraint and as
// the fallback when no anchor towns could be resolved.
const DIR_RULE = {
  nord:     "at a clearly higher latitude",
  nordøst:  "at both a higher latitude and a higher longitude",
  øst:      "at a clearly higher longitude",
  sørøst:   "at a lower latitude and a higher longitude",
  sør:      "at a clearly lower latitude",
  sørvest:  "at both a lower latitude and a lower longitude",
  vest:     "at a clearly lower longitude",
  nordvest: "at a higher latitude and a lower longitude",
};

// Project a point a given distance along a bearing (great-circle).
function projectPoint(lat, lon, bearingDeg, distanceKm) {
  const rad = Math.PI / 180;
  const br  = bearingDeg * rad;
  const d   = distanceKm / EARTH_R_KM;
  const la1 = lat * rad, lo1 = lon * rad;
  const la2 = Math.asin(Math.sin(la1) * Math.cos(d) + Math.cos(la1) * Math.sin(d) * Math.cos(br));
  const lo2 = lo1 + Math.atan2(Math.sin(br) * Math.sin(d) * Math.cos(la1),
                               Math.cos(d) - Math.sin(la1) * Math.sin(la2));
  return { lat: la2 / rad, lon: ((lo2 / rad + 540) % 360) - 180 };
}

// Forward-geocode a free-text place using whichever provider is configured,
// falling back to the public Photon service.
async function geocodePlace(name) {
  const cfg = getMapsConfig();
  if (cfg.configured) {
    try {
      const r = await mapsProviderSearch(cfg, name, 1);
      const it = (r || [])[0];
      if (it && it.lat) return { lat: parseFloat(it.lat), lon: parseFloat(it.lon) };
    } catch (e) { /* fall through to Photon */ }
  }
  try {
    const r = await fetch("https://photon.komoot.io/api?q=" + encodeURIComponent(name) + "&limit=1", {
      headers: { "User-Agent": "Event-Admin/1.0 (" + (process.env.BASE_DOMAIN || DOMAIN) + ")" },
      signal: AbortSignal.timeout(6000),
    });
    if (!r.ok) return null;
    const d = await r.json();
    const f = (d.features || [])[0];
    if (!f || !f.geometry) return null;
    return { lat: f.geometry.coordinates[1], lon: f.geometry.coordinates[0] };
  } catch (e) { return null; }
}

// Name of the nearest settlement to a coordinate.
async function reverseName(lat, lon) {
  const cfg = getMapsConfig();
  if (cfg.configured) {
    try {
      const d = await mapsProviderReverse(cfg, lat, lon);
      const a = (d && d.address) || {};
      const n = a.city || a.town || a.village || a.municipality || a.county;
      if (n) return n;
    } catch (e) { /* fall through */ }
  }
  try {
    const r = await fetch("https://photon.komoot.io/reverse?lat=" + lat + "&lon=" + lon + "&limit=1", {
      headers: { "User-Agent": "Event-Admin/1.0 (" + (process.env.BASE_DOMAIN || DOMAIN) + ")" },
      signal: AbortSignal.timeout(6000),
    });
    if (!r.ok) return null;
    const d = await r.json();
    const p = ((d.features || [])[0] || {}).properties || {};
    return p.city || p.name || p.county || p.state || null;
  } catch (e) { return null; }
}

// Real towns that actually lie in the requested direction from the start.
// Samples at ~35%, ~65% and ~95% of the trip distance so the anchors span
// the whole route rather than clustering near the start.
async function findDirectionAnchors(start, direction, distanceKm) {
  const bearing = DIR_BEARING[direction];
  if (bearing === undefined) return [];
  const origin = await geocodePlace(start);
  if (!origin) return [];

  const total = Math.max(40, Math.min(2000, parseFloat(distanceKm) || 150));
  const names = [];
  const seen  = new Set([String(start).trim().toLowerCase()]);

  for (const frac of [0.35, 0.65, 0.95]) {
    const p = projectPoint(origin.lat, origin.lon, bearing, total * frac);
    const n = await reverseName(p.lat, p.lon);
    if (n && !seen.has(n.trim().toLowerCase())) {
      seen.add(n.trim().toLowerCase());
      names.push(n);
    }
  }
  return names;
}

// The direction instruction handed to the AI: geometric constraint always,
// plus real anchor towns when we managed to resolve them.
function buildDirectionBlock(start, direction, anchors) {
  const label = DIR_LABEL[direction] || String(direction || "").toUpperCase();
  const rule  = DIR_RULE[direction] || "in the requested direction";
  let block = "ABSOLUTE REQUIREMENT: Ride " + label + " from " + start + ". "
            + "Every suggested place MUST lie " + rule + " relative to " + start + ". "
            + "Do not suggest anywhere in the opposite direction.";
  if (anchors && anchors.length) {
    block += " Places in roughly the right direction and distance include: "
           + anchors.join(", ") + ". Use these as a guide to the correct region, "
           + "not as a fixed list - pick whatever is genuinely worth visiting near that corridor.";
  }
  return block;
}

app.get("/api/geocode/photon", auth, rateLimit(60, 60000), async function(req, res) {
  const q = (req.query.q || "").trim().slice(0, 200);
  if (!q) return res.json({ features: [] });
  try {
    const url = "https://photon.komoot.io/api/?q=" + encodeURIComponent(q) + "&limit=7&lang=no";
    const r = await fetch(url, {
      headers: {
        "User-Agent": "Event-Admin/1.0 (" + (process.env.BASE_DOMAIN || DOMAIN) + ")",
        "Accept": "application/json",
        "Accept-Language": "no,nb;q=0.9,en;q=0.8",
        "Referer": "https://" + DOMAIN + "/"
      }
    });
    if (!r.ok) {
      console.error("[photon] HTTP " + r.status + " for q=" + q);
      return res.status(502).json({ error: st("photon_error_prefix", req) + r.status });
    }
    const d = await r.json();
    res.json(d);
  } catch(e) {
    res.status(502).json({ error: "Geocoding utilgjengelig" });
  }
});

// Reverse geocode proxy — avoids CORS and rate-limit issues from the browser
// Overpass API proxy — avoids CORS and rate-limit issues from browser
// Caches results aggressively since OSM data changes slowly
app.get("/api/overpass/interpreter", auth, rateLimit(60, 60000), async function(req, res) {
  const query = req.query.data || "";
  if (!query) return res.status(400).json({ error: "Missing query" });
  return proxyOverpass(query, res);
});
app.post("/api/overpass/interpreter", auth, rateLimit(60, 60000), express.raw({ type: '*/*', limit: '100kb' }), async function(req, res) {
  let query = "";
  const raw = req.body ? req.body.toString('utf8') : "";
  if (raw.startsWith("data=")) {
    query = decodeURIComponent(raw.slice(5).replace(/\+/g, ' '));
  } else if (raw.startsWith("[out:")) {
    query = raw; // already a raw QL query
  } else if (req.query.data) {
    query = req.query.data;
  }
  if (!query) return res.status(400).json({ error: "Missing query" });
  return proxyOverpass(query, res);
});
async function proxyOverpass(query, res) {
  if (!query || query.trim().length < 10) return res.status(400).json({ error: "Invalid query" });
  if (!app._overpassCache) app._overpassCache = new Map();
  const cacheKey = query.slice(0, 500);
  if (app._overpassCache.has(cacheKey)) {
    return res.json(app._overpassCache.get(cacheKey));
  }

  // Try multiple Overpass endpoints in order
  const endpoints = [
    "https://overpass-api.de/api/interpreter",
    "https://overpass.kumi.systems/api/interpreter",
    "https://maps.mail.ru/osm/tools/overpass/api/interpreter",
  ];

  for (const endpoint of endpoints) {
    try {
      const r = await fetch(endpoint, {
        method: "POST",
        headers: {
          "Content-Type": "application/x-www-form-urlencoded",
          "User-Agent": "Event-Admin/1.0 (" + (process.env.BASE_DOMAIN || DOMAIN) + ")"
        },
        body: "data=" + encodeURIComponent(query),
        signal: AbortSignal.timeout(12000)
      });
      if (!r.ok) {
        console.warn("[overpass] " + endpoint + " returned " + r.status + " — trying next");
        continue;
      }
      const d = await r.json();
      app._overpassCache.set(cacheKey, d);
      if (app._overpassCache.size > 200) app._overpassCache.delete(app._overpassCache.keys().next().value);
      return res.json(d);
    } catch(e) {
      console.warn("[overpass] " + endpoint + " failed: " + e.message + " — trying next");
    }
  }

  // All endpoints failed
  console.error("[overpass] All endpoints unreachable");
  res.status(502).json({ error: "Overpass unavailable — all endpoints failed", elements: [] });
}

app.get("/api/geocode/reverse", auth, rateLimit(120, 60000), async function(req, res) {
  const lat  = parseFloat(req.query.lat);
  const lon  = parseFloat(req.query.lon);
  const zoom = parseInt(req.query.zoom) || 10;
  if (isNaN(lat) || isNaN(lon)) return res.status(400).json({ error: "Missing lat/lon" });

  // Cache reverse geocode results (rounded to ~100m grid)
  if (!app._revGeoCache) app._revGeoCache = new Map();
  // Zoom must be part of the key: a coarse (municipality) lookup and a fine
  // (village) lookup at the same point are different answers, and without
  // this the first one served poisons the other.
  const cacheKey = lat.toFixed(3) + "," + lon.toFixed(3) + "@" + zoom;
  if (app._revGeoCache.has(cacheKey)) return res.json(app._revGeoCache.get(cacheKey));

  function cacheAndReturn(d) {
    app._revGeoCache.set(cacheKey, d);
    if (app._revGeoCache.size > 2000) app._revGeoCache.delete(app._revGeoCache.keys().next().value);
    return res.json(d);
  }

  // Paid provider first, if configured — faster & more reliable than public services
  const mapsCfg = getMapsConfig();
  if (mapsCfg.configured) {
    try {
      const d = await mapsProviderReverse(mapsCfg, lat, lon);
      if (d) return cacheAndReturn(d);
    } catch(e) { console.warn("[revgeo] " + mapsCfg.provider + " failed: " + e.message + " — falling back"); }
  }

  // Try Photon reverse first (reliable, no IP restrictions)
  try {
    const pr = await fetch("https://photon.komoot.io/reverse?lat=" + lat + "&lon=" + lon + "&limit=1", {
      headers: { "User-Agent": "Event-Admin/1.0 (" + (process.env.BASE_DOMAIN || DOMAIN) + ")" }
    });
    if (pr.ok) {
      const pd = await pr.json();
      const f = pd.features && pd.features[0];
      if (f) {
        const p = f.properties || {};
        const d = {
          display_name: [p.name, p.street, p.city || p.town || p.village, p.country].filter(Boolean).join(", "),
          address: {
            city: p.city || p.town || p.village || p.municipality,
            town: p.town, village: p.village, municipality: p.municipality,
            county: p.county, state: p.state, country: p.country,
            road: p.street
          }
        };
        return cacheAndReturn(d);
      }
    }
  } catch(e) { console.error("[revgeo] Photon failed:", e.message); }

  // Fallback: Nominatim
  try {
    const url = "https://nominatim.openstreetmap.org/reverse?format=json&lat=" + lat + "&lon=" + lon + "&zoom=" + zoom;
    const r = await fetch(url, {
      headers: {
        "User-Agent": "Event-Admin/1.0 (" + (process.env.BASE_DOMAIN || DOMAIN) + ")",
        "Accept-Language": "no,nb;q=0.9,sv;q=0.8"
      }
    });
    if (r.ok) { return cacheAndReturn(await r.json()); }
  } catch(e) { console.error("[revgeo] Nominatim failed:", e.message); }

  res.status(502).json({ error: "Reverse geocoding utilgjengelig" });
});

// ── Geocoding rate limiter — Nominatim allows max 1 req/sec ──────────
var _nominatimQueue    = [];
var _nominatimRunning  = false;

function nominatimEnqueue(url, headers) {
  return new Promise(function(resolve, reject) {
    _nominatimQueue.push({ url, headers, resolve, reject });
    if (!_nominatimRunning) nominatimDrain();
  });
}

async function nominatimDrain() {
  if (_nominatimRunning || !_nominatimQueue.length) return;
  _nominatimRunning = true;
  while (_nominatimQueue.length) {
    const { url, headers, resolve, reject } = _nominatimQueue.shift();
    try {
      const r = await fetch(url, { headers, signal: AbortSignal.timeout(8000) });
      resolve(r);
    } catch(e) {
      reject(e);
    }
    if (_nominatimQueue.length) await new Promise(function(r){ setTimeout(r, 1100); }); // 1.1s between requests
  }
  _nominatimRunning = false;
}

app.get("/api/geocode/nominatim", auth, rateLimit(120, 60000), async function(req, res) {
  const q           = (req.query.q || "").trim().slice(0, 300);
  const limit       = Math.min(parseInt(req.query.limit) || 7, 20);
  const addressdetails = req.query.addressdetails === "1";
  // Optional location bias from client (map center)
  const biasLat = parseFloat(req.query.lat) || null;
  const biasLon = parseFloat(req.query.lon) || null;
  if (!q) return res.json([]);

  // Simple in-memory cache — include bias in key so same query near diff locations returns different results
  const biasKey = biasLat ? (biasLat.toFixed(1) + "," + biasLon.toFixed(1)) : "global";
  const cacheKey = q.toLowerCase() + "|" + limit + "|" + biasKey;
  if (!app._geocodeCache) app._geocodeCache = new Map();
  if (app._geocodeCache.has(cacheKey)) {
    return res.json(app._geocodeCache.get(cacheKey));
  }

  // Paid provider first, if configured — faster & more reliable than public services
  const mapsCfg = getMapsConfig();
  if (mapsCfg.configured) {
    try {
      const results = await mapsProviderSearch(mapsCfg, q, limit);
      if (results && results.length) {
        app._geocodeCache.set(cacheKey, results);
        if (app._geocodeCache.size > 500) app._geocodeCache.delete(app._geocodeCache.keys().next().value);
        return res.json(results);
      }
    } catch(e) { console.warn("[geocode] " + mapsCfg.provider + " failed: " + e.message + " — falling back"); }
  }

  // Try Photon first — with location bias so "Berlin" returns Berlin, not Berlitz in Pakistan
  try {
    const bLat = biasLat || 63.0;
    const bLon = biasLon || 14.0;
    const photonUrl = "https://photon.komoot.io/api/?q=" + encodeURIComponent(q)
      + "&limit=" + limit + "&lang=no"
      + "&lat=" + bLat + "&lon=" + bLon + "&location_bias_scale=0.3";
    const pr = await fetch(photonUrl, {
      headers: { "User-Agent": "Event-Admin/1.0 (" + (process.env.BASE_DOMAIN || DOMAIN) + ")" },
      signal: AbortSignal.timeout(5000)
    });
    if (pr.ok) {
      const pd = await pr.json();
      const features = (pd.features || []);
      if (features.length > 0) {
        // Convert Photon GeoJSON to Nominatim-compatible format
        const results = features.map(function(f) {
          const p = f.properties || {};
          const coords = f.geometry && f.geometry.coordinates;
          const lon = coords ? coords[0] : 0;
          const lat = coords ? coords[1] : 0;
          const parts = [p.name, p.street, p.city || p.town || p.village, p.country].filter(Boolean);
          return {
            lat: String(lat), lon: String(lon),
            display_name: parts.join(", "),
            name: p.name || "",
            type: p.type || "",
            class: p.osm_type || "",
            address: addressdetails ? {
              city: p.city || p.town || p.village || p.municipality,
              town: p.town, village: p.village, municipality: p.municipality,
              county: p.county, state: p.state, country: p.country,
              road: p.street, house_number: p.housenumber,
              postcode: p.postcode
            } : undefined
          };
        });
        app._geocodeCache.set(cacheKey, results);
        if (app._geocodeCache.size > 500) {
          // Evict oldest entry
          app._geocodeCache.delete(app._geocodeCache.keys().next().value);
        }
        return res.json(results);
      }
    }
  } catch(e) {
    console.error("[geocode] Photon failed:", e.message);
  }

  // Fallback: Nominatim (rate-limited queue — max 1 req/sec)
  try {
    const url = "https://nominatim.openstreetmap.org/search?format=json&limit=" + limit
      + (addressdetails ? "&addressdetails=1" : "")
      + (biasLat ? "&viewbox=" + (biasLon-2) + "," + (biasLat+2) + "," + (biasLon+2) + "," + (biasLat-2) + "&bounded=0" : "")
      + "&q=" + encodeURIComponent(q);
    const r = await nominatimEnqueue(url, {
      "User-Agent": "Event-Admin/1.0 (" + (process.env.BASE_DOMAIN || DOMAIN) + ")",
      "Accept-Language": "no,nb;q=0.9,sv;q=0.8,de;q=0.7,en;q=0.6"
    });
    if (r.status === 429) return res.status(429).json({ error: st("geocoding_rate_limited", req) });
    if (!r.ok) return res.status(502).json({ error: st("geocoding_error_prefix", req) + r.status });
    const d = await r.json();
    app._geocodeCache.set(cacheKey, d);
    return res.json(d);
  } catch(e) {
    return res.status(502).json({ error: "Geocoding utilgjengelig: " + e.message });
  }
});

// ── GPX-eksport ───────────────────────────────────────────────────
// ── Google Maps URL resolver ─────────────────────────────────────
app.get("/api/resolve-maps-url", auth, async function(req, res) {
  const url = req.query.url || "";
  if (!url || !url.includes("google") && !url.includes("goo.gl")) {
    return res.status(400).json({ error: st("invalid_url", req) });
  }
  try {
    // Follow the redirect to get the full URL
    const r = await fetch(url, { redirect: "follow", headers: { "User-Agent": "Mozilla/5.0" } });
    const finalUrl = r.url;

    let lat = null, lon = null, name = "";
    const coordM = finalUrl.match(/@(-?\d+\.?\d*),(-?\d+\.?\d*)/)
      || finalUrl.match(/[?&]q=(-?\d+\.?\d*),(-?\d+\.?\d*)/);
    if (coordM) { lat = parseFloat(coordM[1]); lon = parseFloat(coordM[2]); }

    const placeM = finalUrl.match(/\/place\/([^/@]+)/);
    if (placeM) name = decodeURIComponent(placeM[1].replace(/\+/g, " ")).split(",")[0].trim();

    res.json({ lat, lon, name, url: finalUrl });
  } catch(e) {
    res.status(500).json({ error: e.message });
  }
});

