      { "type": "opplevelse", "from": "stedsnavn", "to": "attraksjonsnavn", "km": tall, "profile": "${usedProfile}", "notat": "hva som er spesielt her" },
      { "type": "stop",      "from": "stedsnavn", "to": "stedsnavn",       "km": tall, "profile": "${usedProfile}", "notat": "" },
      { "type": "lunch",      "from": "stedsnavn", "to": "kafénavn",        "km": tall, "profile": "${usedProfile}", "notat": "anbefalt sted" },
      { "type": "opplevelse", "from": "stedsnavn", "to": "attraksjonsnavn", "km": tall, "profile": "${usedProfile}", "notat": "hva som er spesielt" },
      { "type": "end",      "from": "stedsnavn", "to": "${roundtrip ? start : 'destinasjon'}", "km": tall, "profile": "${usedProfile}", "notat": "" }
