    + '  \n'
    + '  # TTY/video group permissions\n'
    + '  usermod -a -G tty,video,input,render "$KIOSK_USER" 2>/dev/null || true\n'
    + '  cat > /etc/udev/rules.d/99-tv-agent.rules << UDEVEOF\n'
    + 'KERNEL=="tty0", GROUP="tty", MODE="0660"\n'
