// Upload MP4/WebM video as a fullscreen TV slide
app.post("/api/tv/:deptId/video-slides", auth, managerOrAdmin, deptGuard,
  multer({ dest: UPLOADS, limits: { fileSize: 10 * 1024 * 1024 * 1024 },
    fileFilter: function(req, file, cb) {
      const ok = /^video\//.test(file.mimetype) || /\.(mp4|webm|mov|m4v|avi|mkv|hevc|h265)$/i.test(file.originalname);
      cb(null, !!ok);
    }
  }).single("video"),
  async function(req, res) {
    if (!req.file) return res.status(400).json({ error: st("no_video_file", req) });
    const deptId   = req.params.deptId;
    const origPath = req.file.path;
    const ts       = Date.now();
    const outName  = "video_" + deptId + "_" + ts + ".mp4";
    const outPath  = path.join(UPLOADS, outName);

    // Svar umiddelbart med "konverterer"-status
    const videoUrl = "/uploads/" + outName;
    const slide    = { type: "mp4-slide", url: videoUrl, name: req.file.originalname, converting: true };
    const prev     = getTvState(deptId);
    const slides   = (prev.slides || []).concat(slide);
    const next     = Object.assign({}, prev, { slides });
    tvState.set(deptId, next);
    _saveTvState();
    broadcastTv(deptId, Object.assign({ type: "state" }, next));
    res.json({ ok: true, slides, converting: true, message: "Konverterer video til H.264 i bakgrunnen…" });

    // Convert asynkront i bakgrunnen
    try {
      await new Promise(function(resolve, reject) {
        const { spawn } = require("child_process");
        const ff = spawn("ffmpeg", [
          "-i", origPath,
          "-c:v", "libx264",
          "-preset", "fast",
          "-crf", "23",
          "-vf", "scale=trunc(iw/2)*2:trunc(ih/2)*2", // Sikre jevne dimensjoner
          "-c:a", "aac",
          "-b:a", "128k",
          "-movflags", "+faststart",
          "-y",
          outPath
        ]);
        ff.stderr.on("data", function(d) {}); // Slukt stderr
        ff.on("close", function(code) { code === 0 ? resolve() : reject(new Error("ffmpeg kode: " + code)); });
        ff.on("error", reject);
      });
      // Converting ferdig – generate thumbnail
      try { fs.unlinkSync(origPath); } catch(e) {}
      const thumbName = "thumb_" + deptId + "_" + ts + ".jpg";
      const thumbPath = path.join(UPLOADS, thumbName);
      let thumbUrl = null;
      try {
        await new Promise(function(resolve) {
          const { spawn } = require("child_process");
          const ff = spawn("ffmpeg", ["-i", outPath, "-ss", "00:00:05", "-vframes", "1", "-vf", "scale=320:-1", "-y", thumbPath]);
          ff.on("close", resolve);
          ff.on("error", resolve);
        });
        if (fs.existsSync(thumbPath)) thumbUrl = "/uploads/" + thumbName;
      } catch(e) {}
      const curr = getTvState(deptId);
      const updSlides = (curr.slides || []).map(function(s) {
        if (s && s.url === videoUrl) return Object.assign({}, s, { converting: false, thumb: thumbUrl });
        return s;
      });
      const updated = Object.assign({}, curr, { slides: updSlides });
      tvState.set(deptId, updated);
      _saveTvState();
      broadcastTv(deptId, Object.assign({ type: "state" }, updated));
      console.log("[video] Konvertert: " + outName);
    } catch(e) {
      console.error("[video] Konvertering feilet:", e.message);
      // Try using the original as a fallback
      try { fs.renameSync(origPath, outPath); } catch(e2) {}
      const curr = getTvState(deptId);
      const updSlides = (curr.slides || []).map(function(s) {
        if (s && s.url === videoUrl) return Object.assign({}, s, { converting: false });
        return s;
      });
      tvState.set(deptId, Object.assign({}, curr, { slides: updSlides }));
      _saveTvState();
    }
  }
);

// Upload PPTX and convert to slides for TV channel
app.post("/api/tv/:deptId/pptx", auth, managerOrAdmin, deptGuard,
  multer({ dest: UPLOADS, limits: { fileSize: 10 * 1024 * 1024 * 1024 },
    fileFilter: function(req, file, cb) {
      const ok = file.originalname.match(/\.pptx?$/i) || file.mimetype.includes("presentation") || file.mimetype === "application/octet-stream";
      cb(null, !!ok);
    }
  }).single("pptx"),
  function(req, res) {
    if (!req.file) return res.status(400).json({ error: st("no_pptx_file", req) });
    const { execFile, spawn } = require("child_process");
    const os = require("os");
    const deptId = req.params.deptId;
    const pptxPath = req.file.path;
    const workDir = path.join(os.tmpdir(), "tv_pptx_" + deptId + "_" + require("crypto").randomBytes(8).toString("hex"));
    fs.mkdirSync(workDir, { recursive: true });
    function cleanup() {
      try { fs.rmSync(workDir, { recursive: true, force: true }); } catch(e) {}
      try { fs.unlinkSync(pptxPath); } catch(e) {}
    }

    // Find LibreOffice binary
    const loCmd = (function() {
      const candidates = [
        "/usr/lib/libreoffice/program/soffice",
        "/usr/bin/soffice",
        "/usr/bin/libreoffice",
        "/opt/libreoffice/program/soffice"
      ];
      for (var i = 0; i < candidates.length; i++) {
        if (fs.existsSync(candidates[i])) return candidates[i];
      }
      try { return require("child_process").execSync("which soffice 2>/dev/null || which libreoffice 2>/dev/null").toString().trim(); } catch(e) { return null; }
    })();
    if (!loCmd) { cleanup(); return res.status(500).json({ error: st("libreoffice_missing", req) }); }

    // Step 1: PPTX → PDF via LibreOffice (spawn + poll for stability)
    const loProc = spawn(loCmd, ["--headless","--convert-to","pdf","--outdir", workDir, pptxPath], {
      timeout: 600000,
      env: Object.assign({}, process.env, { HOME: workDir })
    });
    let loFinished = false;
    const loTimeout = setTimeout(function() {
      if (!loFinished) { try { loProc.kill(); } catch(e) {} }
    }, 590000);

    let pollCount = 0, lastPdfSize = -1, stableCount = 0;
    const pollInterval = setInterval(function() {
      pollCount++;
      try {
        const pdfs = fs.readdirSync(workDir).filter(function(f) { return f.endsWith(".pdf"); });
        if (pdfs.length > 0) {
          const size = fs.statSync(path.join(workDir, pdfs[0])).size;
          if (size > 0 && size === lastPdfSize) {
            stableCount++;
            if (stableCount >= 3) {
              clearInterval(pollInterval);
              clearTimeout(loTimeout);
              loFinished = true;
              try { loProc.kill(); } catch(e) {}
              proceedWithPdf(pdfs[0]);
            }
          } else { lastPdfSize = size; stableCount = 0; }
        }
      } catch(e) {}
      if (pollCount > 600) {
        clearInterval(pollInterval);
        cleanup();
        if (!res.headersSent) res.status(500).json({ error: "LibreOffice timeout" });
      }
    }, 1000);

    loProc.on("error", function(err) {
      if (!loFinished) {
        clearInterval(pollInterval); clearTimeout(loTimeout); cleanup();
        if (!res.headersSent) res.status(500).json({ error: st("libreoffice_error_prefix", req) + err.message });
      }
    });

    // Step 2: PDF → PNG via pdftoppm
    function proceedWithPdf(pdfFile) {
      const slidePrefix = path.join(workDir, "slide");
      execFile("pdftoppm", ["-r","120","-png", path.join(workDir, pdfFile), slidePrefix],
        { timeout: 600000 }, function(err) {
        if (err) { cleanup(); return res.status(500).json({ error: st("pdftoppm_failed_prefix", req) + (err.message||"ukjent") }); }
        const pngFiles = fs.readdirSync(workDir)
          .filter(function(f) { return f.match(/slide-?\d+\.png$/i); })
          .sort(function(a,b) {
            // Natural sort by number
            var na = parseInt(a.match(/\d+/)[0]), nb = parseInt(b.match(/\d+/)[0]);
            return na - nb;
          });
        if (!pngFiles.length) { cleanup(); return res.status(500).json({ error: st("no_slides_generated", req) }); }
        const ts = Date.now() + "_" + require("crypto").randomBytes(4).toString("hex");
        const newSlides = [];
        pngFiles.forEach(function(f, i) {
          const src  = path.join(workDir, f);
          const dest = path.join(UPLOADS, "tv_" + deptId + "_" + ts + "_" + String(i).padStart(4,"0") + ".png");
          fs.copyFileSync(src, dest);
          newSlides.push("/uploads/" + path.basename(dest));
        });
        cleanup();
        const prev = getTvState(deptId);
        const slides = (prev.slides || []).concat(newSlides);
        const next = Object.assign({}, prev, { slides });
        tvState.set(deptId, next);
        _saveTvState();
        broadcastTv(deptId, Object.assign({ type: "state" }, next));
        res.json({ ok: true, slides: newSlides, total: slides.length });
      });
    }
  }
);

// Delete a TV slide
app.delete("/api/tv/:deptId/slides/:idx", auth, managerOrAdmin, deptGuard, function(req, res) {
  const deptId = req.params.deptId;
  const idx = parseInt(req.params.idx);
  const prev = getTvState(deptId);
  const slides = (prev.slides || []).slice();
  if (idx < 0 || idx >= slides.length) return res.status(404).json({ error: "Not found" });
  const removed = slides.splice(idx, 1)[0];
  try { if (removed && removed.startsWith("/uploads/")) deleteMediaFile(path.basename(removed)); } catch(e) {}
  const next = Object.assign({}, prev, { slides });
  tvState.set(deptId, next);
  _saveTvState();
  broadcastTv(deptId, Object.assign({ type: "state" }, next));
  res.json({ ok: true, slides });
});

