// ── Global TV Channel (rotates through all departments) ─────────
app.get("/api/tv/_global/state", function(req, res) {
  var settings = getSettings();
  var depts = settings.departments || [];
  var events = readJSON(EVENTS_FILE);
  var now = Date.now();
  var globalState = getTvState("_global");

  var deptViews = [];
  depts.forEach(function(dept) {
    var deptApp = getDeptAppearanceById(dept.id);
    var deptState = getTvState(dept.id);
    var upcoming = events
      .filter(function(e) {
        if (e.department !== dept.id || !e.date || e.hideFromList) return false;
        var sMs = new Date(e.date).getTime();
        var eD = e.endDate ? new Date(e.endDate) : new Date(e.date);
        if (e.endTime) { var eP = e.endTime.split(":"); eD.setHours(+eP[0], +eP[1], 59, 999); }
        else eD.setHours(23, 59, 59, 999);
        if (sMs <= now && eD.getTime() >= now) return true;
        return sMs > now - 3600000;
      })
      .sort(function(a, b) {
        var aS = new Date(a.date).getTime(); var bS = new Date(b.date).getTime();
        var aO = aS <= now; var bO = bS <= now;
        if (aO && !bO) return -1; if (!aO && bO) return 1;
        return aS - bS;
      })
      .slice(0, deptState.eventCount || 5)
      .map(function(e) {
        try {
          var regs = (e.registrations || []).filter(function(r) { return !r.anonymized; });
          return {
            id: e.id, title: e.title, date: e.date, endDate: e.endDate || null, endTime: e.endTime || null,
            location: e.location, eventType: e.eventType, image: e.image || null,
            description: e.description ? String(e.description).slice(0, 300) : null,
            registrationCount: regs.length, maxParticipants: e.maxParticipants || null,
            cancelled: !!e.cancelled, cancelReason: e.cancelReason || null,
          };
        } catch(mapErr) {
          return { id: e.id, title: e.title, date: e.date, location: e.location, eventType: e.eventType, image: e.image || null };
        }
      });
    // Only include departments that have events
    if (upcoming.length > 0) {
      deptViews.push({
        id: dept.id, name: dept.displayName || dept.name, slug: dept.slug || dept.id,
        accent: deptApp.accent, logo: deptApp.logo, theme: deptApp.themeTV || deptApp.theme,
        upcoming: upcoming,
      });
    }
  });

  // Collect media pool: all slides from all departments
  var mediaPool = [];
  depts.forEach(function(dept) {
    var st = getTvState(dept.id);
    (st.slides || []).forEach(function(slide) {
      var url = typeof slide === "string" ? slide : (slide && slide.url ? slide.url : null);
      var thumb = typeof slide === "string" ? slide : (slide && slide.thumb ? slide.thumb : url);
      if (url) mediaPool.push({ url: url, thumb: thumb || url, department: dept.id, departmentName: dept.displayName || dept.name });
    });
  });

  res.json({
    departments: deptViews,
    mediaPool: mediaPool,
    interleaveMedia: globalState.interleaveMedia || [],
    slideInterval: globalState.slideInterval || 20,
    typeNames: settings.typeNames || {},
    typeColors: settings.typeColors || {},
    colors: settings.colors || {},
  });
});

